G1S_TRAITS = ["GCST90205183", "HYPERTENSION", "T2D", "LEIOMYOMA", "ENDO_ALL"]

for d in (OUT, WORK, LOG.parent, GTEX_FILE.parent, GNOMAD_DIR):
    d.mkdir(parents=True, exist_ok=True)
