NICE = ["nice", "-n", "10"]
ENV1 = dict(os.environ, OPENBLAS_NUM_THREADS="1", OMP_NUM_THREADS="1", VECLIB_MAXIMUM_THREADS="1")

REPRO = ["Uterus", "Ovary", "Vagina", "Fallopian Tube", "Cervix - Ectocervix", "Cervix - Endocervix"]
DSTROMAL = ["dStromal_early", "dStromal_mid", "dStromal_late"]
LINEAGES = ["stromal", "epithelial", "endothelial", "myeloid", "lymphocyte"]
N_PERM = 100
PERM_SEED = 20261106

for d in (OUT, WORK, LOG.parent, KDIR, MUNGED, HM3_DIR):
    d.mkdir(parents=True, exist_ok=True)
_fh = open(LOG, "w", encoding="utf-8")
SUM = {"task": "PAPER9_V023_KOLLER", "timestamp_utc": TS, "gates": {}, "results": {}}


def say(msg=""):
    print(msg, flush=True)
    _fh.write(msg + "\n")
    _fh.flush()


def sh(cmd, timeout=None):
    try:
        p = subprocess.run([str(c) for c in cmd], capture_output=True, text=True, timeout=timeout, env=ENV1)
        return p.returncode, p.stdout, p.stderr
    except subprocess.TimeoutExpired:
        return 124, "", "timeout"


def holm(p):
    p = np.asarray(p, dtype=float)
    m = len(p)
    order = np.argsort(p)
    adj = np.empty(m)
    run = 0.0
    for r, i in enumerate(order):
        run = max(run, min(1.0, (m - r) * p[i]))
        adj[i] = run
    return adj


def bh(p):
    p = np.asarray(p, dtype=float)
    n = len(p)
    order = np.argsort(p)
    ranked = p[order] * n / (np.arange(n) + 1)
    q = np.minimum.accumulate(ranked[::-1])[::-1]
    out = np.empty(n)
    out[order] = np.minimum(q, 1.0)
    return out


def entrez_unique():
    sym2, dup = {}, set()
    for line in open(GENE_LOC_B37):
        x = line.split()
        if len(x) >= 6 and x[1] in [str(c) for c in range(1, 23)]:
            if x[5] in sym2:
                dup.add(x[5])
            sym2[x[5]] = x[0]
    for d in dup:
        sym2.pop(d, None)
    return sym2


def magma_gp(trait, covf, cond, tag):
    raw = MAGMA_OUT / (trait + "_35_10.genes.raw")
    if not raw.exists() or not Path(covf).exists():
        return None
    outp = WORK / ("%s__%s" % (trait, tag))
    gsa = Path(str(outp) + ".gsa.out")
    keys = ["condition-hide=", "condition="] if cond else [None]
    o = e = ""
    for key in keys:
        if gsa.exists():
            gsa.unlink()
        model = ["direction=greater"] if key is None else [key + cond, "direction=greater"]
        rc, o, e = sh(NICE + [MAGMA, "--gene-results", raw, "--gene-covar", covf, "--model"] + model + ["--out", outp],
                      timeout=3 * 3600)
        if rc == 0 and gsa.exists():
            rows = [l for l in open(gsa) if not l.startswith("#") and l.strip()]
            hdr = rows[0].split()
            res = {}
            for l in rows[1:]:
                d = dict(zip(hdr, l.split()))
                name = d.get("FULL_NAME", d.get("VARIABLE"))
                try:
                    res[name] = {"beta": float(d["BETA"]), "beta_std": float(d.get("BETA_STD", "nan")),
                                 "se": float(d["SE"]), "p": float(d["P"])}
                except (KeyError, ValueError):
                    continue
            return res
    say("    [MAGMA_FAIL] %s %s %s" % (trait, tag, (o + e).strip()[-200:]))
    return None


# ----------------------------------------------------------------------------
# 1. Download, format detection, rsID mapping
# ----------------------------------------------------------------------------
def zenodo_links():
    p = subprocess.run(["curl", "-sSL", "--fail", "--max-time", "60", "-A", "paper9", ZENODO_API], capture_output=True)
    links = {}
    if p.returncode == 0:
        rec = json.loads(p.stdout.decode("utf-8", "replace"))
        for f in rec.get("files", []):
            links[f.get("key")] = (f.get("links", {}).get("self"), f.get("size", 0))
    return links


def download(name, links):
    dst = KDIR / name
    url, size = links.get(name, (None, 0))
    if dst.exists() and (not size or dst.stat().st_size == size):
        say("[DL] %-40s SKIP_PRESENT %.1f MB" % (name, dst.stat().st_size / 1e6))
        return dst
    urls = [u for u in [url, "https://zenodo.org/records/18983492/files/%s?download=1" % name] if u]
    for u in urls:
        part = dst.with_name(dst.name + ".part")
        rc, o, e = sh(["curl", "-L", "-sS", "--fail", "--retry", "3", "-C", "-", "-A", "paper9", "-o", part, u], timeout=7200)
        if rc == 0 and part.exists() and (not size or part.stat().st_size == size):
            part.rename(dst)
            say("[DL] %-40s OK %.1f MB" % (name, dst.stat().st_size / 1e6))
            return dst
        say("[DL] %-40s FAILED rc=%s %s" % (name, rc, e.strip()[:120]))
    return None


def pick(cols, cands):
    low = {c.lower(): c for c in cols}
    for c in cands:
        if c in low:
            return low[c]
    return None


def detect(kfile):
    head = pd.read_csv(kfile, sep=None, engine="python", nrows=20000, compression="infer")
    cols = list(head.columns)
    say("[FORMAT] columns: " + ", ".join(cols))
    for line in head.head(3).to_string(index=False).splitlines():
        say("    " + line[:220])
    c = {
        "id": pick(cols, ["rsid", "snp", "markername", "variant_id", "snpid", "id", "rs", "rs_id"]),
        "chr": pick(cols, ["chr", "chrom", "chromosome", "#chrom", "#chr", "hg38_chr", "chr_b38"]),
        "pos": pick(cols, ["pos", "bp", "position", "base_pair_location", "pos_b38", "hg38_pos", "bp_b38"]),
        "a1": pick(cols, ["allele1", "a1", "effect_allele", "ea", "alt", "tested_allele"]),
        "a2": pick(cols, ["allele2", "a2", "other_allele", "nea", "ref", "non_effect_allele"]),
        "p": pick(cols, ["p-value", "p", "pval", "p_value", "pvalue", "p.value"]),
        "z": pick(cols, ["zscore", "z", "z_score", "stat"]),
        "beta": pick(cols, ["beta", "effect", "b", "log_or", "logor"]),
        "se": pick(cols, ["se", "stderr", "standard_error", "sebeta"]),
        "n": pick(cols, ["n", "weight", "n_total", "neff", "totaln", "n_eff", "samplesize"]),
        "frq": pick(cols, ["freq1", "eaf", "effect_allele_frequency", "frq", "af", "maf"]),
    }
    ids = head[c["id"]].astype(str) if c["id"] else pd.Series([], dtype=str)
    rs_share = float(ids.str.startswith("rs").mean()) if len(ids) else 0.0
    say("[FORMAT] mapped columns: " + ", ".join("%s=%s" % (k, v) for k, v in c.items()) + " | rsID share=%.3f" % rs_share)
    return c, rs_share


def key_of(chrom, pos):
    ch = pd.Series(chrom).astype(str).str.replace("chr", "", regex=False).str.upper().replace({"X": "23", "Y": "24"})
    ch = pd.to_numeric(ch, errors="coerce")
    ps = pd.to_numeric(pd.Series(pos), errors="coerce")
    k = ch * 10_000_000_000 + ps
    return k.to_numpy(dtype="float64")


def build_map(build):
    # Arrays of (chr*1e10 + pos) -> rs number, sorted; b38 from the GCST harmonised file, b37 from the 1000G bim
    keys, rs = [], []
    if build == "b38":
        for ch in pd.read_csv(GCST_H, sep="\t", compression="gzip", chunksize=1_000_000,
                              usecols=lambda x: x in ("hm_rsid", "rsid", "hm_chrom", "hm_pos", "chromosome", "base_pair_location")):
            idc = "hm_rsid" if "hm_rsid" in ch.columns else "rsid"
            cc = "hm_chrom" if "hm_chrom" in ch.columns else "chromosome"
            pc = "hm_pos" if "hm_pos" in ch.columns else "base_pair_location"
            r = ch[idc].astype(str)
            ok = r.str.startswith("rs")
            keys.append(key_of(ch.loc[ok, cc], ch.loc[ok, pc]))
            rs.append(pd.to_numeric(r[ok].str[2:], errors="coerce").to_numpy(dtype="float64"))
    else:
        for ch in pd.read_csv(str(G1000) + ".bim", sep=r"\s+", header=None, usecols=[0, 1, 3], chunksize=2_000_000):
            r = ch[1].astype(str)
            ok = r.str.startswith("rs")
            keys.append(key_of(ch.loc[ok, 0], ch.loc[ok, 3]))
            rs.append(pd.to_numeric(r[ok].str[2:], errors="coerce").to_numpy(dtype="float64"))
    k = np.concatenate(keys)
    r = np.concatenate(rs)
    m = np.isfinite(k) & np.isfinite(r)
    k, r = k[m], r[m]
    o = np.argsort(k, kind="mergesort")
    return k[o], r[o]


def lookup(kmap, rmap, k):
    i = np.searchsorted(kmap, k)
    i = np.clip(i, 0, len(kmap) - 1)
    hit = kmap[i] == k
    out = np.full(len(k), np.nan)
    out[hit] = rmap[i[hit]]
    return out


def prepare(kfile):
    say("")
    say("-" * 72)
    say("[SECTION] 1. Koller 2026 EUR without 23andMe: format and rsID mapping")
    pfile = MAGMA_OUT / (TRAIT + ".pval.txt")
    hfile = HM3_DIR / (TRAIT + ".tsv")
    c, rs_share = detect(kfile)
    if pfile.exists() and hfile.exists():
        say("[PREPARE] present -> reuse")
        return c
    if c["p"] is None or (c["id"] is None and (c["chr"] is None or c["pos"] is None)):
        raise RuntimeError("cannot find p-value / SNP identifier columns")
    hm3 = set()
    for line in open(HM3_LIST, errors="ignore"):
        t = line.split()
        if t and t[0].startswith("rs"):
            hm3.add(t[0])
    use_pos = rs_share < 0.5
    kmap = rmap = None
    if use_pos:
        sample = pd.read_csv(kfile, sep=None, engine="python", nrows=200000, compression="infer")
        if c["chr"] and c["pos"]:
            ks = key_of(sample[c["chr"]], sample[c["pos"]])
        else:
            parts = sample[c["id"]].astype(str).str.replace("chr", "", regex=False).str.split(r"[:_]", expand=True)
            ks = key_of(parts[0], parts[1])
        best = None
        for b in ("b38", "b37"):
            km, rm = build_map(b)
            share = float(np.isfinite(lookup(km, rm, ks)).mean())
            say("[BUILD] %s match share in first 200k rows: %.3f" % (b, share))
            if best is None or share > best[0]:
                best = (share, b, km, rm)
            else:
                del km, rm
        _, b, kmap, rmap = best
        say("[BUILD] using %s positions" % b)
        SUM["gates"]["BUILD"] = b
    n_in = n_out = n_hm3 = 0
    with gzip.open(kfile, "rt") as f0:
        first = f0.readline()
    sep = "\t" if "\t" in first else r"\s+"
    reader = pd.read_csv(kfile, sep=sep, chunksize=500000, compression="infer", low_memory=False)
    with open(pfile, "w") as fp, open(hfile, "w") as fh:
        fp.write("SNP\tP\tN\n" if c["n"] else "SNP\tP\n")
        fh.write("SNP\tA1\tA2\tZ\tP\tN\n" if c["n"] else "SNP\tA1\tA2\tZ\tP\n")
        for ch in reader:
            n_in += len(ch)
            if use_pos:
                if c["chr"] and c["pos"]:
                    k = key_of(ch[c["chr"]], ch[c["pos"]])
                else:
                    parts = ch[c["id"]].astype(str).str.replace("chr", "", regex=False).str.split(r"[:_]", expand=True)
                    k = key_of(parts[0], parts[1])
                rn = lookup(kmap, rmap, k)
                ok = np.isfinite(rn)
                snp = pd.Series(["rs%d" % v for v in rn[ok]], index=ch.index[ok])
                ch = ch.loc[ok]
            else:
                snp = ch[c["id"]].astype(str).str.split(r"[;,]").str[0]
                ok = snp.str.startswith("rs").to_numpy()
                ch, snp = ch.loc[ok], snp[ok]
            p = pd.to_numeric(ch[c["p"]], errors="coerce")
            if c["z"]:
                z = pd.to_numeric(ch[c["z"]], errors="coerce")
            elif c["beta"] and c["se"]:
                z = pd.to_numeric(ch[c["beta"]], errors="coerce") / pd.to_numeric(ch[c["se"]], errors="coerce")
            elif c["beta"]:
                from scipy.stats import norm
                z = np.sign(pd.to_numeric(ch[c["beta"]], errors="coerce")) * norm.isf(p / 2)
            else:
                z = pd.Series(np.nan, index=ch.index)
            n = pd.to_numeric(ch[c["n"]], errors="coerce") if c["n"] else None
            good = p.notna() & (p > 0) & (p <= 1)
            df = pd.DataFrame({"SNP": snp, "P": p})
            if n is not None:
                df["N"] = n
            df = df[good.to_numpy()].drop_duplicates("SNP")
            df.to_csv(fp, sep="\t", header=False, index=False)
            n_out += len(df)
            if c["a1"] and c["a2"]:
                h = pd.DataFrame({"SNP": snp, "A1": ch[c["a1"]].astype(str).str.upper(), "A2": ch[c["a2"]].astype(str).str.upper(),
                                  "Z": z, "P": p})
                if n is not None:
                    h["N"] = n
                h = h[good.to_numpy() & h["SNP"].isin(hm3).to_numpy()].drop_duplicates("SNP")
                h.to_csv(fh, sep="\t", header=False, index=False)
                n_hm3 += len(h)
    say("[PREPARE] rows in=%d | MAGMA SNPs=%d | HapMap3 rows=%d" % (n_in, n_out, n_hm3))
    SUM["gates"]["KOLLER_SNPS"] = n_out
    return c


# ----------------------------------------------------------------------------
# 2-3. MAGMA gene analysis, munge, h2, rg
# ----------------------------------------------------------------------------
def gene_analysis(c):
    raw = MAGMA_OUT / (TRAIT + "_35_10.genes.raw")
    if raw.exists():
        say("[MAGMA_GENE] present")
        return True
    pfile = MAGMA_OUT / (TRAIT + ".pval.txt")
    if c["n"]:
        pv = [str(pfile), "ncol=N"]
        nn = []
    else:
        pv = [str(pfile)]
        nn = ["N=1000000"]
        say("[MAGMA_GENE] WARNING no per-SNP N column; N=1,000,000 used")
    t0 = time.time()
    say("[MAGMA_GENE] %s running (~35 min, quiet)" % TRAIT)
    rc, o, e = sh(NICE + [MAGMA, "--bfile", G1000, "--pval"] + pv + nn + ["--gene-annot", ANNOT,
                  "--out", MAGMA_OUT / (TRAIT + "_35_10")], timeout=6 * 3600)
    say("[MAGMA_GENE] rc=%d %.0f min %s" % (rc, (time.time() - t0) / 60, "" if rc == 0 else (o + e).strip()[-300:]))
    return raw.exists()


def top_genes():
    sym = {}
    for line in open(GENE_LOC_B37):
        x = line.split()
        if len(x) >= 6:
            sym[x[0]] = x[5]
    res = {}
    for t in (REF, TRAIT):
        f = MAGMA_OUT / (t + "_35_10.genes.out")
        if f.exists():
            g = pd.read_csv(f, sep=r"\s+")
            g["GENE"] = g["GENE"].astype(str)
            res[t] = g
    if TRAIT in res:
        g = res[TRAIT]
        bonf = 0.05 / len(g)
        top = g.sort_values("P").head(15)
        say("[MAGMA_TOP] %s Bonferroni genes=%d; top: %s" % (TRAIT, int((g["P"] < bonf).sum()),
            ", ".join("%s(%.0e)" % (sym.get(e, e), p) for e, p in zip(top["GENE"], top["P"]))))
        if REF in res:
            m = res[REF].merge(g, on="GENE", suffixes=("_ref", "_k"))
            r = np.corrcoef(m["ZSTAT_ref"], m["ZSTAT_k"])[0, 1]
            both = int(((m["P_ref"] < bonf) & (m["P_k"] < bonf)).sum())
            say("[MAGMA_OVERLAP] gene Z correlation with %s r=%.3f; Bonferroni in both=%d (ref %d, Koller %d)" % (
                REF, r, both, int((m["P_ref"] < bonf).sum()), int((m["P_k"] < bonf).sum())))


def ld_prefixes():
    def find(dirname):
        d = REF_UNPACKED / dirname
        for p in sorted(d.rglob("*.l2.ldscore.gz")) if d.exists() else []:
            m = re.match(r"^(.*\.)1\.l2\.ldscore\.gz$", p.name)
            if m:
                return str(p.parent / m.group(1))
        return None
    return find("LDscore"), find("1000G_Phase3_weights_hm3_no_MHC")


def ldsc_block():
    say("")
    say("-" * 72)
    say("[SECTION] 3. munge, h2, rg with GCST90205183 and ENDO_ALL (overlap)")
    ldsc_py = LDSC_DIR / "ldsc.py"
    munge_py = LDSC_DIR / "munge_sumstats.py"
    ss = MUNGED / (TRAIT + ".sumstats.gz")
    if not ss.exists():
        src = HM3_DIR / (TRAIT + ".tsv")
        hdr = open(src).readline().rstrip("\n").split("\t")
        n_med = pd.read_csv(src, sep="\t", usecols=["N"])["N"].median() if "N" in hdr else float("nan")
        cmd = [LDSC_PY, munge_py, "--sumstats", src, "--snp", "SNP", "--a1", "A1", "--a2", "A2", "--p", "P",
               "--signed-sumstats", "Z,0", "--merge-alleles", MERGE_ALLELES, "--chunksize", "500000", "--out", MUNGED / TRAIT]
        cmd += ["--N-col", "N"] if np.isfinite(n_med) else ["--N", "1000000"]
        rc, o, e = sh(cmd, timeout=3600)
        say("[MUNGE] rc=%d %s" % (rc, "" if rc == 0 else (o + e).strip()[-300:]))
    if not ss.exists():
        return
    ref, w = ld_prefixes()
    rc, o, e = sh([LDSC_PY, ldsc_py, "--h2", ss, "--ref-ld-chr", ref, "--w-ld-chr", w, "--out", WORK / "h2_koller"], timeout=3600)
    t = Path(str(WORK / "h2_koller") + ".log").read_text(errors="ignore") if Path(str(WORK / "h2_koller") + ".log").exists() else o + e
    for pat in [r"Total Observed scale h2:.*", r"Lambda GC:.*", r"Mean Chi\^2:.*", r"Intercept:.*", r"Ratio.*"]:
        m = re.search(pat, t)
        if m:
            say("    [H2] " + m.group(0).strip())
    others = [x for x in [REF, "ENDO_ALL"] if (MUNGED / (x + ".sumstats.gz")).exists()]
    rc, o, e = sh([LDSC_PY, ldsc_py, "--rg", ",".join(str(MUNGED / (x + ".sumstats.gz")) for x in [TRAIT] + others),
                   "--ref-ld-chr", ref, "--w-ld-chr", w, "--out", WORK / "rg_koller"], timeout=7200)
    t = Path(str(WORK / "rg_koller") + ".log").read_text(errors="ignore") if Path(str(WORK / "rg_koller") + ".log").exists() else o + e
    if "Summary of Genetic Correlation Results" in t:
        block = t.split("Summary of Genetic Correlation Results")[1].strip().splitlines()
        hdr = block[0].split()
        for line in block[1:]:
            x = line.split()
            if len(x) != len(hdr):
                break
            d = dict(zip(hdr, x))
            say("    [RG] %s ~ %-14s rg=%s se=%s gcov_int=%s (%s)" % (TRAIT, Path(d["p2"]).name.replace(".sumstats.gz", ""),
                d.get("rg"), d.get("se"), d.get("gcov_int"), d.get("gcov_int_se")))
    else:
        say("    [RG] failed rc=%d %s" % (rc, (o + e).strip()[-200:]))


# ----------------------------------------------------------------------------
# 4. Re-runs
# ----------------------------------------------------------------------------
def gtex_tissues():
    hdr = gzip.open(GTEX_FILE, "rt").read(200000).splitlines()[2].split("\t")
    return [c for c in hdr[2:] if not c.startswith("Cells")]


def rerun_g6():
    say("")
    say("-" * 72)
    say("[SECTION] 4a. G6 tissues (GTEx v8) and X4, Koller vs GCST90205183")
    tissues = gtex_tissues()
    lab = {"T%02d" % (i + 1): t for i, t in enumerate(tissues)}
    for trait in (REF, TRAIT):
        r = magma_gp(trait, COV_G6, "Average", "G6")
        if not r:
            continue
        df = pd.DataFrame([{"tissue": lab[k], **r[k]} for k in lab if k in r]).sort_values("p").reset_index(drop=True)
        df["q"] = bh(df["p"].values)
        rep = df[df["tissue"].isin(REPRO)].copy()
        rep["holm"] = holm(rep["p"].values)
        say("    [G6] %-13s top: %s" % (trait[:13], "; ".join("%s p=%.1e" % (t, p) for t, p in zip(df["tissue"].head(5), df["p"].head(5)))))
        say("    [G6] %-13s reproductive: %s" % (trait[:13], " | ".join("%s r%d H=%.2g" % (t, i + 1, h) for i, (t, h) in
                                                                      zip(rep.index, zip(rep["tissue"], rep["holm"])))))
        df.to_csv(OUT / ("G6_%s.csv" % trait), index=False)
    fa = COV_X4 / "X4a.covar.txt"
    for trait in (REF, TRAIT):
        r = magma_gp(trait, fa, "Average,SMOOTH", "X4a")
        if r and "MULL" in r:
            say("    [X4a] %-13s MULL|Avg+SMOOTH beta=%.4f p=%.2e | UTERUS beta=%.4f p=%.2e" % (
                trait[:13], r["MULL"]["beta"], r["MULL"]["p"], r.get("UTERUS", {}).get("beta", np.nan), r.get("UTERUS", {}).get("p", np.nan)))
        parts = []
        for k in ("T1", "T2", "T3"):
            rr = magma_gp(trait, COV_X4 / ("X4b_%s.covar.txt" % k), "Average,SMOOTH", "X4b_" + k)
            if rr and "MULL" in rr:
                parts.append("%s BETA_STD=%.3f p=%.1e" % (k, rr["MULL"]["beta_std"], rr["MULL"]["p"]))
        say("    [X4b] %-13s %s" % (trait[:13], " | ".join(parts)))


def rerun_g4():
    say("")
    say("-" * 72)
    say("[SECTION] 4b. G4 HECA (control donors) M1 specificity|Average and M3 log-mean (no conditioning)")
    types = list(pd.read_csv(HECA_GS / "specificity_by_type.csv.gz", index_col=0, nrows=1).columns)
    lab = {"T%02d" % (i + 1): t for i, t in enumerate(types)}
    for mname, covf, cond in (("M1", COV_C5 / "C5_M1_specificity.covar.txt", "Average"),
                              ("M3", COV_C5 / "C5_M23_logmean.covar.txt", None)):
        for trait in (REF, TRAIT):
            r = magma_gp(trait, covf, cond, "C5_" + mname)
            if not r:
                continue
            df = pd.DataFrame([{"type": lab[k], **r[k]} for k in lab if k in r]).sort_values("p").reset_index(drop=True)
            ds = df[df["type"].isin(DSTROMAL)].copy()
            ds["holm"] = holm(ds["p"].values)
            say("    [G4_%s] %-13s top3: %s | dStromal: %s" % (mname, trait[:13],
                "; ".join("%s(p=%.1e)" % (t, p) for t, p in zip(df["type"].head(3), df["p"].head(3))),
                "; ".join("%s r%d p=%.2g H=%.2g" % (t.replace("dStromal_", "dS_"), i + 1, p, h)
                          for i, t, p, h in zip(ds.index, ds["type"], ds["p"], ds["holm"]))))
            df.to_csv(OUT / ("G4_%s_%s.csv" % (mname, trait)), index=False)
            if trait == TRAIT and mname == "M1":
                SUM["results"]["G4_M1_koller_dS_holm_min"] = float(ds["holm"].min()) if len(ds) else None


def unit_profiles(M, G, lineage, context):
    sub = G[(G["lineage_ref"] == lineage) & (G["context"] == context) & (G["agree"])]
    prof = {}
    for pid, g in sub.groupby("patient"):
        if int(g["n_cells"].sum()) < 10:
            continue
        v = M[g.index.to_numpy()].sum(axis=0)
        prof[(pid, context)] = np.log2(v / max(v.sum(), 1) * 1e6 + 1)
    return prof


def write_contrast(A_list, B_list, genes, mapped, sym2, tag):
    A = np.vstack(A_list).mean(axis=0)
    B = np.vstack(B_list).mean(axis=0)
    ex = (np.maximum(2 ** A - 1, 2 ** B - 1) >= 1.0) & mapped
    g = np.asarray(genes)[ex]
    covf = WORK / ("G1_%s.covar.txt" % tag)
    pd.DataFrame({"GENE": [sym2[x] for x in g], "D": (A - B)[ex], "DN": (B - A)[ex], "AVG": ((A + B) / 2)[ex]}).to_csv(
        covf, sep="\t", index=False, float_format="%.6g")
    return covf


def rerun_g1(sym2):
    say("")
    say("-" * 72)
    say("[SECTION] 4c. G1 primary (peritoneal lesion vs eutopic), Koller vs GCST90205183, Holm over lineages")
    rows = []
    for lin in LINEAGES:
        f = COVAR_G1 / ("LES_vs_EU__%s.covar.txt" % lin)
        for trait in (REF, TRAIT):
            r = magma_gp(trait, f, "AVG", "G1_" + lin)
            if r and "D" in r and "DN" in r:
                rows.append({"trait": trait, "lineage": lin, "beta": r["D"]["beta"], "se": r["D"]["se"],
                             "p_greater": r["D"]["p"], "p_less": r["DN"]["p"]})
    df = pd.DataFrame(rows)
    for trait, g in df.groupby("trait"):
        hl, hg = holm(g["p_less"].values), holm(g["p_greater"].values)
        say("    [G1] %-13s " % trait[:13] + " ".join("%s:%+.3f(pL=%.3f,HL=%.2f,HG=%.2f)" % (l[:5], b, pl, a, c)
                                                     for l, b, pl, a, c in zip(g["lineage"], g["beta"], g["p_less"], hl, hg)))
    df.to_csv(OUT / "G1_koller.csv", index=False)
    M = np.load(PB213 / "pseudobulk_counts.npy", mmap_mode="r")
    G = pd.read_csv(PB213 / "pseudobulk_groups.csv").reset_index(drop=True)
    genes = list(pd.read_csv(PB213 / "genes.csv")["symbol"].astype(str))
    mapped = np.array([x in sym2 for x in genes])
    pa = unit_profiles(M, G, "lymphocyte", "peritoneal_lesion")
    pb = unit_profiles(M, G, "lymphocyte", "eutopic")
    base = df[(df["trait"] == TRAIT) & (df["lineage"] == "lymphocyte")]
    if len(pa) >= 3 and len(pb) >= 3 and len(base):
        units = list(pa.values()) + list(pb.values())
        lab = np.array([1] * len(pa) + [0] * len(pb))
        rng = np.random.default_rng(PERM_SEED)
        ts = []
        t0 = time.time()
        for b in range(N_PERM):
            pl = rng.permutation(lab)
            covf = write_contrast([units[j] for j in range(len(units)) if pl[j] == 1],
                                  [units[j] for j in range(len(units)) if pl[j] == 0], genes, mapped, sym2, "perm")
            r = magma_gp(TRAIT, covf, "AVG", "G1_perm")
            if r and "D" in r:
                ts.append(r["D"]["beta"] / r["D"]["se"])
        tobs = base["beta"].iloc[0] / base["se"].iloc[0]
        ts = np.array(ts)
        pe = (1 + np.sum(ts <= tobs)) / (1 + len(ts)) if len(ts) else float("nan")
        say("    [G1_PERM] %s lymphocyte t_obs=%.2f permutation p_less=%.3f (B=%d) vs parametric %.4f | %.0f min" % (
            TRAIT, tobs, pe, len(ts), base["p_less"].iloc[0], (time.time() - t0) / 60))


# ----------------------------------------------------------------------------
def main():
    say("=" * 72)
    say("PAPER 9 | v0.0.23 | Koller 2026 EUR (without 23andMe) as second GWAS | " + TS)
    say("=" * 72)
    t0 = time.time()
    links = zenodo_links()
    say("[ZENODO] files listed: %d" % len(links))
    rd = download(README_NAME, links)
    if rd:
        for line in rd.read_text(errors="ignore").splitlines()[:60]:
            say("    [README] " + line[:200])
    kfile = download(KFILE_NAME, links)
    if kfile is None:
        say("[FATAL] GWAS file not available")
    else:
        try:
            c = prepare(kfile)
            ok = gene_analysis(c)
            SUM["gates"]["KOLLER_GENES_RAW"] = ok
            top_genes()
        except Exception as e:
            import traceback
            say("[STEP_ERROR] prepare/gene %s: %s" % (type(e).__name__, str(e)[:300]))
            say(traceback.format_exc()[-1200:])
        for name, fn in (("ldsc", ldsc_block), ("g6", rerun_g6), ("g4", rerun_g4), ("g1", lambda: rerun_g1(entrez_unique()))):
            try:
                fn()
            except Exception as e:
                import traceback
                say("[STEP_ERROR] %s %s: %s" % (name, type(e).__name__, str(e)[:300]))
                say(traceback.format_exc()[-1000:])
    with open(OUT / "p9_v023_summary.json", "w") as f:
        json.dump(SUM, f, indent=2, default=str)
    say("")
    for k, v in SUM["gates"].items():
        say("[GATE] %-24s %s" % (k, v))
    say("[TIME] %.0f min" % ((time.time() - t0) / 60))
    say("[OUTPUT] " + str(OUT))
    say("[LOG] " + str(LOG))
    say("[POLICY] rules fixed in CHANGELOG v0.2.14 before this run (larger, partially overlapping GWAS)")
    say("[DONE] PAPER9_V023_COMPLETE")
    _fh.close()


if __name__ == "__main__":
    main()
''',
    'scripts/p9_v024_g4_specificity.py': r'''#!/usr/bin/env python3
# Paper 9 | v0.0.24 | G4-S specificity of the decidual signal (HECA M1) + G1 epithelial permutation.
#   Rules: CHANGELOG v0.2.15 (fixed before this run; post hoc, descriptive).
# Runs in ~/Desktop/paper9/.venv, low-heat (MAGMA single thread, nice 10). ~15-25 min.

import os
os.environ.setdefault("OMP_NUM_THREADS", "1")
os.environ.setdefault("OPENBLAS_NUM_THREADS", "1")
os.environ.setdefault("VECLIB_MAXIMUM_THREADS", "1")
try:
    os.nice(10)
except Exception:
    pass

import datetime as dt
import json
import subprocess
import time
from pathlib import Path

import numpy as np
import pandas as pd

# ----------------------------------------------------------------------------
# Hardcoded locations
# ----------------------------------------------------------------------------
HOME = Path.home()
REPO = HOME / "Desktop" / "paper9"
INTERIM = REPO / "data" / "interim"
PROC = REPO / "data" / "processed"
TOOLS = REPO / "tools"
MAGMA = TOOLS / "magma" / "magma_bin"
GENE_LOC_B37 = TOOLS / "magma" / "genes_b37" / "NCBI37.3.gene.loc"
MAGMA_OUT = INTERIM / "magma"
HECA_GS = PROC / "genesets" / "heca_v014"
COV_X4A = INTERIM / "magma_v022" / "X4a.covar.txt"
PB213 = PROC / "gse213216_pseudobulk_clusters"

TS = dt.datetime.now(dt.timezone.utc).strftime("%Y%m%dT%H%M%SZ")
OUT = REPO / "results" / "g4s" / ("p9_v024_g4s_" + TS)
WORK = INTERIM / "magma_v024"
LOG = REPO / "logs" / ("p9_v024_g4s_" + TS + ".log")
NICE = ["nice", "-n", "10"]
ENV1 = dict(os.environ, OPENBLAS_NUM_THREADS="1", OMP_NUM_THREADS="1", VECLIB_MAXIMUM_THREADS="1")

# Fixed (CHANGELOG v0.2.15)
FOCUS = ["KOLLER_EUR", "GCST90205183"]
PANEL = ["KOLLER_EUR", "GCST90205183", "ENDO_ALL", "ENDO_OVARY", "ENDO_PERITONEUM", "ENDO_DEEP",
         "LEIOMYOMA", "HYPERTENSION", "T2D"]
CONTROLS_Z = ["T2D", "HYPERTENSION", "LEIOMYOMA"]
DS = {"dStromal_mid": "DSMID", "dStromal_early": "DSEARLY", "dStromal_late": "DSLATE"}
VASC = {"ePV_2": "EPV2", "Arterial": "ART", "uSMCs": "USMC"}
N_PERM = 100
PERM_SEED = 20261106

for d in (OUT, WORK, LOG.parent):
    d.mkdir(parents=True, exist_ok=True)
_fh = open(LOG, "w", encoding="utf-8")
SUM = {"task": "PAPER9_V024_G4S", "timestamp_utc": TS, "results": {}}


def say(msg=""):
    print(msg, flush=True)
    _fh.write(msg + "\n")
    _fh.flush()


def sh(cmd, timeout=None):
    try:
        p = subprocess.run([str(c) for c in cmd], capture_output=True, text=True, timeout=timeout, env=ENV1)
        return p.returncode, p.stdout, p.stderr
    except subprocess.TimeoutExpired:
        return 124, "", "timeout"


def holm(p):
    p = np.asarray(p, dtype=float)
    m = len(p)
    order = np.argsort(p)
    adj = np.empty(m)
    run = 0.0
    for r, i in enumerate(order):
        run = max(run, min(1.0, (m - r) * p[i]))
        adj[i] = run
    return adj


def entrez_unique():
    sym2, dup = {}, set()
    for line in open(GENE_LOC_B37):
        x = line.split()
        if len(x) >= 6 and x[1] in [str(c) for c in range(1, 23)]:
            if x[5] in sym2:
                dup.add(x[5])
            sym2[x[5]] = x[0]
    for d in dup:
        sym2.pop(d, None)
    return sym2


def magma_gp(trait, covf, cond, tag):
    raw = MAGMA_OUT / (trait + "_35_10.genes.raw")
    if not raw.exists():
        return None
    outp = WORK / ("%s__%s" % (trait, tag))
    gsa = Path(str(outp) + ".gsa.out")
    o = e = ""
    for key in ("condition-hide=", "condition="):
        if gsa.exists():
            gsa.unlink()
        rc, o, e = sh(NICE + [MAGMA, "--gene-results", raw, "--gene-covar", covf, "--model", key + cond,
                              "direction=greater", "--out", outp], timeout=3 * 3600)
        if rc == 0 and gsa.exists():
            rows = [l for l in open(gsa) if not l.startswith("#") and l.strip()]
            hdr = rows[0].split()
            res = {}
            for l in rows[1:]:
                d = dict(zip(hdr, l.split()))
                name = d.get("FULL_NAME", d.get("VARIABLE"))
                try:
                    res[name] = {"beta": float(d["BETA"]), "se": float(d["SE"]), "p": float(d["P"])}
                except (KeyError, ValueError):
                    continue
            return res
    say("    [MAGMA_FAIL] %s %s %s" % (trait, tag, (o + e).strip()[-200:]))
    return None


def gene_z(trait):
    f = MAGMA_OUT / (trait + "_35_10.genes.out")
    if not f.exists():
        return None
    g = pd.read_csv(f, sep=r"\s+")
    return pd.Series(g["ZSTAT"].values, index=g["GENE"].astype(str))


# ----------------------------------------------------------------------------
# G4-S
# ----------------------------------------------------------------------------
def build_cov(sym2):
    S = pd.read_csv(HECA_GS / "specificity_by_type.csv.gz", index_col=0)
    M = pd.read_csv(HECA_GS / "mean_cpm_by_type.csv.gz", index_col=0).loc[S.index, S.columns]
    cov = pd.DataFrame(index=S.index)
    for lab, k in list(DS.items()) + list(VASC.items()):
        if lab in S.columns:
            cov[k] = S[lab]
        else:
            say("[G4S_WARN] type missing in HECA table: " + lab)
    cov["Average"] = np.log2(M.mean(axis=1) + 1.0)
    cov["GENE"] = [sym2.get(g) for g in cov.index]
    cov = cov.dropna(subset=["GENE"])
    cov["GENE"] = cov["GENE"].astype(str)
    x4 = pd.read_csv(COV_X4A, sep="\t")
    x4["GENE"] = x4["GENE"].astype(str)
    cov = cov.merge(x4[["GENE", "MULL"]], on="GENE", how="left")
    for t in CONTROLS_Z:
        z = gene_z(t)
        cov["Z_" + t] = cov["GENE"].map(z) if z is not None else np.nan
    full = cov.dropna()
    say("[G4S_COV] HECA genes=%d; with MULL and all control gene z=%d" % (len(cov), len(full)))
    cols = ["GENE"] + [c for c in full.columns if c != "GENE"]
    f = WORK / "G4S.covar.txt"
    full[cols].to_csv(f, sep="\t", index=False, float_format="%.6g")
    return f


def g4s(sym2):
    say("")
    say("-" * 72)
    say("[SECTION] G4-S specificity of the decidual signal (HECA control donors, M1; post hoc, v0.2.15)")
    covf = build_cov(sym2)
    ds_keys = [k for k in DS.values()]
    models = [("base", "Average"),
              ("+zT2D", "Average,Z_T2D"), ("+zHTN", "Average,Z_HYPERTENSION"), ("+zLEIO", "Average,Z_LEIOMYOMA"),
              ("+vasc", "Average,EPV2,ART,USMC"), ("+MULL", "Average,MULL")]
    have = set(open(covf).readline().rstrip("\n").split("\t"))
    models = [(m, ",".join(v for v in c.split(",") if v in have)) for m, c in models]
    rows = []
    for trait in FOCUS:
        for mname, cond in models:
            r = magma_gp(trait, covf, cond, "G4S_" + mname.replace("+", "p"))
            if not r:
                continue
            for lab, k in DS.items():
                if k in r:
                    rows.append({"trait": trait, "model": mname, "type": lab, **r[k]})
    df = pd.DataFrame(rows)
    df.to_csv(OUT / "G4S_conditional.csv", index=False)
    for trait in FOCUS:
        sub = df[df["trait"] == trait]
        if not len(sub):
            continue
        say("  [S5] %s (dStromal_mid beta / p; same genes in every model)" % trait)
        for mname, _ in models:
            s = sub[sub["model"] == mname].set_index("type")
            if "dStromal_mid" in s.index:
                say("    [S5] %-7s dS_mid beta=%.3f p=%.4f | dS_early p=%.3f | dS_late p=%.3f" % (
                    mname, s.loc["dStromal_mid", "beta"], s.loc["dStromal_mid", "p"],
                    s.loc["dStromal_early", "p"] if "dStromal_early" in s.index else np.nan,
                    s.loc["dStromal_late", "p"] if "dStromal_late" in s.index else np.nan))
        ok_z = all(((sub["model"] == m) & (sub["type"] == "dStromal_mid") & (sub["p"] < 0.05)).any() for m in ("+zT2D", "+zHTN", "+zLEIO"))
        ok_v = ((sub["model"] == "+vasc") & (sub["type"] == "dStromal_mid") & (sub["p"] < 0.05)).any()
        ok_m = ((sub["model"] == "+MULL") & (sub["type"] == "dStromal_mid") & (sub["p"] < 0.05)).any()
        say("  [S5_READING] %s: not explained by generic gene-level signal: %s | separable from perivascular/SMC: %s | beyond MULL: %s" % (
            trait, "YES" if ok_z else "NO", "YES" if ok_v else "NO", "YES" if ok_m else "NO"))
        SUM["results"]["S5_" + trait] = {"generic": ok_z, "vascular": ok_v, "mull": ok_m}

    # S5d panel with the original M1 file (all 32 types)
    say("  [S5d] M1 panel (all HECA types; dStromal Holm over 3; rank among types)")
    types = list(pd.read_csv(HECA_GS / "specificity_by_type.csv.gz", index_col=0, nrows=1).columns)
    lab = {"T%02d" % (i + 1): t for i, t in enumerate(types)}
    m1 = INTERIM / "magma_v020" / "C5_M1_specificity.covar.txt"
    for trait in PANEL:
        r = magma_gp(trait, m1, "Average", "S5d")
        if not r:
            continue
        t = pd.DataFrame([{"type": lab[k], **r[k]} for k in lab if k in r]).sort_values("p").reset_index(drop=True)
        ds = t[t["type"].isin(DS.keys())].copy()
        ds["holm"] = holm(ds["p"].values)
        say("    [S5d] %-15s top=%s(p=%.1e) | %s" % (trait[:15], t["type"].iloc[0], t["p"].iloc[0], "; ".join(
            "%s r%d p=%.3f H=%.3f" % (x.replace("dStromal_", "dS_"), i + 1, p, h) for i, x, p, h in zip(ds.index, ds["type"], ds["p"], ds["holm"]))))


# ----------------------------------------------------------------------------
# G1-S epithelial permutation
# ----------------------------------------------------------------------------
def unit_profiles(M, G, lineage, context):
    sub = G[(G["lineage_ref"] == lineage) & (G["context"] == context) & (G["agree"])]
    prof = {}
    for pid, g in sub.groupby("patient"):
        if int(g["n_cells"].sum()) < 10:
            continue
        v = M[g.index.to_numpy()].sum(axis=0)
        prof[(pid, context)] = np.log2(v / max(v.sum(), 1) * 1e6 + 1)
    return prof


def write_contrast(A_list, B_list, genes, mapped, sym2, tag):
    A = np.vstack(A_list).mean(axis=0)
    B = np.vstack(B_list).mean(axis=0)
    ex = (np.maximum(2 ** A - 1, 2 ** B - 1) >= 1.0) & mapped
    g = np.asarray(genes)[ex]
    covf = WORK / ("G1_%s.covar.txt" % tag)
    pd.DataFrame({"GENE": [sym2[x] for x in g], "D": (A - B)[ex], "DN": (B - A)[ex], "AVG": ((A + B) / 2)[ex]}).to_csv(
        covf, sep="\t", index=False, float_format="%.6g")
    return covf


def g1_epithelial(sym2):
    say("")
    say("-" * 72)
    say("[SECTION] G1-S epithelial contrast: patient-label permutation (B=%d)" % N_PERM)
    M = np.load(PB213 / "pseudobulk_counts.npy", mmap_mode="r")
    G = pd.read_csv(PB213 / "pseudobulk_groups.csv").reset_index(drop=True)
    genes = list(pd.read_csv(PB213 / "genes.csv")["symbol"].astype(str))
    mapped = np.array([x in sym2 for x in genes])
    pa = unit_profiles(M, G, "epithelial", "peritoneal_lesion")
    pb = unit_profiles(M, G, "epithelial", "eutopic")
    say("    [G1E] units lesion=%d eutopic=%d" % (len(pa), len(pb)))
    if len(pa) < 3 or len(pb) < 3:
        return
    units = list(pa.values()) + list(pb.values())
    lab = np.array([1] * len(pa) + [0] * len(pb))
    obs = write_contrast(list(pa.values()), list(pb.values()), genes, mapped, sym2, "obs")
    traits = [t for t in ["KOLLER_EUR", "GCST90205183", "T2D"] if (MAGMA_OUT / (t + "_35_10.genes.raw")).exists()]
    tobs = {}
    for t in traits:
        r = magma_gp(t, obs, "AVG", "G1E_obs")
        if r and "D" in r:
            tobs[t] = (r["D"]["beta"] / r["D"]["se"], r["DN"]["p"])
    rng = np.random.default_rng(PERM_SEED)
    perm = {t: [] for t in tobs}
    t0 = time.time()
    for b in range(N_PERM):
        pl = rng.permutation(lab)
        covf = write_contrast([units[j] for j in range(len(units)) if pl[j] == 1],
                              [units[j] for j in range(len(units)) if pl[j] == 0], genes, mapped, sym2, "perm")
        for t in tobs:
            r = magma_gp(t, covf, "AVG", "G1E_perm")
            if r and "D" in r:
                perm[t].append(r["D"]["beta"] / r["D"]["se"])
    for t, (to, pp) in tobs.items():
        ts = np.array(perm[t])
        pe = (1 + np.sum(ts <= to)) / (1 + len(ts)) if len(ts) else float("nan")
        say("    [G1E_PERM] %-13s t_obs=%.2f permutation p_less=%.3f (B=%d) vs parametric %.2e | perm t sd=%.2f" % (
            t[:13], to, pe, len(ts), pp, ts.std() if len(ts) else float("nan")))
        SUM["results"]["G1E_perm_" + t] = {"t_obs": to, "p_perm": pe}
    say("    [G1E_PERM] %.0f min" % ((time.time() - t0) / 60))


def main():
    say("=" * 72)
    say("PAPER 9 | v0.0.24 | G4-S decidual specificity + G1 epithelial permutation | " + TS)
    say("=" * 72)
    t0 = time.time()
    sym2 = entrez_unique()
    for name, fn in (("g4s", lambda: g4s(sym2)), ("g1e", lambda: g1_epithelial(sym2))):
        try:
            fn()
        except Exception as e:
            import traceback
            say("[STEP_ERROR] %s %s: %s" % (name, type(e).__name__, str(e)[:300]))
            say(traceback.format_exc()[-1000:])
    with open(OUT / "p9_v024_summary.json", "w") as f:
        json.dump(SUM, f, indent=2, default=str)
    say("")
    say("[TIME] %.0f min" % ((time.time() - t0) / 60))
    say("[OUTPUT] " + str(OUT))
    say("[LOG] " + str(LOG))
    say("[POLICY] rules fixed in CHANGELOG v0.2.15 before this run (post hoc, descriptive)")
    say("[DONE] PAPER9_V024_COMPLETE")
    _fh.close()


if __name__ == "__main__":
    main()
''',
    'scripts/p9_v025_scdrs_ochoa.py': r'''#!/usr/bin/env python3
# Paper 9 | v0.0.25 | Option A: Ochoa 2025 claim (lesion macrophages, scDRS) re-tested on GSE213216 (Fonseca 2023)
#   with our cell labels, two endometriosis GWAS and unrelated-trait controls. Rules: CHANGELOG v0.2.16.
#   (1) per-sample re-processing as v016 -> per-cell labels (subsampled)  (2) scDRS per trait and context
#   (3) scDRS association test per lineage and fine label.
# Runs in ~/Desktop/paper9/.venv, low-heat (2 threads, nice 10). ~60-90 min.

import os
os.environ.setdefault("OMP_NUM_THREADS", "2")
os.environ.setdefault("OPENBLAS_NUM_THREADS", "2")
os.environ.setdefault("VECLIB_MAXIMUM_THREADS", "2")
os.environ.setdefault("NUMBA_NUM_THREADS", "2")
try:
    os.nice(10)
except Exception:
    pass

import datetime as dt
import gzip
import json
import subprocess
import sys
import time
from pathlib import Path

import numpy as np
import pandas as pd

# ----------------------------------------------------------------------------
# Hardcoded locations
# ----------------------------------------------------------------------------
HOME = Path.home()
REPO = HOME / "Desktop" / "paper9"
RAW = REPO / "data" / "raw"
INTERIM = REPO / "data" / "interim"
PROC = REPO / "data" / "processed"
VENV_PY = REPO / ".venv" / "bin" / "python"
SERIES_MATRIX_URL = "https://ftp.ncbi.nlm.nih.gov/geo/series/GSE213nnn/GSE213216/matrix/GSE213216_series_matrix.txt.gz"
SERIES_MATRIX = RAW / "geo" / "GSE213216" / "GSE213216_series_matrix.txt.gz"
X_DIR = INTERIM / "gse213216_extract"
REF_PB = PROC / "gse266265_pseudobulk"
REF_SPEC = PROC / "genesets" / "gse266265_v007" / "SA_refined_ALL" / "specificity_by_type.csv.gz"
GENE_LOC_B37 = REPO / "tools" / "magma" / "genes_b37" / "NCBI37.3.gene.loc"
MAGMA_OUT = INTERIM / "magma"
CELLS_DIR = PROC / "gse213216_cells_v025"

TS = dt.datetime.now(dt.timezone.utc).strftime("%Y%m%dT%H%M%SZ")
OUT = REPO / "results" / "scdrs" / ("p9_v025_scdrs_" + TS)
LOG = REPO / "logs" / ("p9_v025_scdrs_" + TS + ".log")

# Processing rules (CHANGELOG v0.2.7, unchanged)
MIN_GENES = 200
MAX_PCT_MT = 25.0
MIN_CELLS_SAMPLE = 200
N_HVG = 2000
N_PCS = 30
LEIDEN_RES = 1.0
N_MARKERS_PER_TYPE = 30
MIN_REF_DONOR_CELLS = 10
LINEAGE_MARKERS = {
    "epithelial": ["EPCAM", "KRT8", "KRT18", "KRT19", "CDH1"],
    "stromal": ["PDGFRA", "DCN", "COL1A1", "COL3A1", "LUM"],
    "endothelial": ["PECAM1", "VWF", "CDH5", "CLDN5"],
    "myeloid": ["CD68", "LYZ", "CD14", "C1QA", "TYROBP"],
    "lymphoid": ["CD3E", "CD2", "NKG7", "GNLY", "MS4A1"],
    "smooth_muscle": ["ACTA2", "MYH11", "DES", "CNN1"],
    "mesothelial": ["MSLN", "UPK3B", "KRT5", "CALB2"],
}
# scDRS rules (CHANGELOG v0.2.16)
CAP_PER_SAMPLE_LABEL = 150
SEED = 20261106
TRAITS = ["GCST90205183", "KOLLER_EUR", "HYPERTENSION", "T2D", "LEIOMYOMA"]
N_TOP = 1000
N_CTRL = 1000
MIN_GROUP_CELLS = 100
CONTEXTS = {"lesion": ["peritoneal_lesion", "endometrioma"], "eutopic": ["eutopic"]}

for d in (OUT, LOG.parent, CELLS_DIR):
    d.mkdir(parents=True, exist_ok=True)
_fh = open(LOG, "w", encoding="utf-8")
SUM = {"task": "PAPER9_V025_SCDRS", "timestamp_utc": TS, "gates": {}, "results": {}}


def say(msg=""):
    print(msg, flush=True)
    _fh.write(msg + "\n")
    _fh.flush()


def curl(url, dst=None, max_time=120):
    cmd = ["curl", "-sSL", "--fail", "--max-time", str(max_time), "-A", "paper9"]
    if dst:
        cmd += ["-o", str(dst)]
    cmd.append(url)
    p = subprocess.run(cmd, capture_output=True)
    if p.returncode != 0:
        return None
    return True if dst else p.stdout


def holm(p):
    p = np.asarray(p, dtype=float)
    m = len(p)
    order = np.argsort(p)
    adj = np.empty(m)
    run = 0.0
    for r, i in enumerate(order):
        run = max(run, min(1.0, (m - r) * p[i]))
        adj[i] = run
    return adj


# ----------------------------------------------------------------------------
# Functions reused verbatim from v018 (same processing rules)
# ----------------------------------------------------------------------------
def ensure_leiden():
    try:
        import leidenalg  # noqa
        import igraph  # noqa
        return True
    except Exception:
        p = subprocess.run([str(VENV_PY), "-m", "pip", "install", "-q", "leidenalg", "igraph"], capture_output=True, text=True)
        say("[PIP] leidenalg igraph rc=%d" % p.returncode)
        try:
            import importlib
            importlib.invalidate_caches()
            import leidenalg  # noqa
            import igraph  # noqa
            return True
        except Exception as e:
            say("[LEIDEN] unavailable (%s) -> k-means fallback" % type(e).__name__)
            return False


def sample_metadata():
    if not SERIES_MATRIX.exists():
        curl(SERIES_MATRIX_URL, SERIES_MATRIX)
    txt = gzip.open(SERIES_MATRIX, "rt", errors="ignore").read().split("!series_matrix_table_begin")[0]
    rows = {}
    for line in txt.splitlines():
        if line.startswith("!Sample_"):
            tag = line.split("\t")[0]
            vals = [v.strip().strip('"') for v in line.split("\t")[1:]]
            rows.setdefault(tag, []).append(vals)
    n = len(rows["!Sample_geo_accession"][0])
    md = pd.DataFrame({"gsm": rows["!Sample_geo_accession"][0], "title": rows["!Sample_title"][0],
                       "source": rows["!Sample_source_name_ch1"][0]})
    for vals in rows.get("!Sample_characteristics_ch1", []):
        for i, v in enumerate(vals):
            if ":" in v:
                k, x = v.split(":", 1)
                md.loc[i, k.strip()] = x.strip()
    for tag in ["!Sample_library_strategy", "!Sample_description", "!Sample_molecule_ch1"]:
        if tag in rows:
            md[tag.replace("!Sample_", "")] = rows[tag][0]
    md.to_csv(OUT / "gse213216_sample_metadata.csv", index=False)
    say("[METADATA] samples=%d columns=%s" % (n, ", ".join(md.columns)))
    return md


def context_of(row):
    t = str(row.get("tissue", "")) + " " + str(row.get("source", ""))
    t = t.lower()
    if "eutopic" in t:
        return "eutopic"
    if "endometrioma" in t:
        return "endometrioma"
    if "no endometriosis" in t:
        return "peritoneum_unaffected"
    if "ovary" in t:
        return "ovary_unaffected"
    if "endometriosis" in t:
        return "peritoneal_lesion"
    return "other"


def reference():
    pb = np.load(REF_PB / "pseudobulk_counts.npy", mmap_mode="r")
    gt = pd.read_csv(REF_PB / "pseudobulk_groups.csv")
    genes = pd.read_csv(REF_PB / "genes.csv")["symbol"].astype(str).tolist()
    S = pd.read_csv(REF_SPEC, index_col=0)
    markers = set()
    for c in S.columns:
        markers.update(S[c].sort_values(ascending=False).index[:N_MARKERS_PER_TYPE])
    gidx = {g: i for i, g in enumerate(genes)}
    markers = sorted(m for m in markers if m in gidx)
    cols = [gidx[m] for m in markers]
    cent = {}
    lineage = {}
    sub = gt[gt["n_cells"] >= MIN_REF_DONOR_CELLS]
    for t in S.columns:
        rows = sub.index[sub["refined"] == t].to_numpy()
        if len(rows) == 0:
            continue
        mats = np.asarray(pb[rows, :], dtype=np.float64)
        lib = mats.sum(axis=1, keepdims=True)
        cpm = mats / np.where(lib > 0, lib, 1) * 1e6
        cent[t] = np.log2(cpm[:, cols] + 1).mean(axis=0)
        lineage[t] = sub.loc[rows, "main"].mode().iloc[0]
    C = pd.DataFrame(cent, index=markers)
    say("[REFERENCE] types=%d marker genes=%d" % (C.shape[1], C.shape[0]))
    return C, lineage


def find_10x(d):
    mtx = sorted(d.rglob("*matrix.mtx*"))
    if mtx:
        name = mtx[0].name
        return ("mtx", mtx[0].parent, name[:name.index("matrix.mtx")])
    h5 = sorted(d.rglob("*.h5"))
    if h5:
        return ("h5", h5[0], "")
    return None


def cluster_labels(adata, use_leiden):
    import scanpy as sc
    sc.pp.highly_variable_genes(adata, n_top_genes=N_HVG, flavor="seurat")
    ad = adata[:, adata.var["highly_variable"]].copy()
    sc.pp.scale(ad, max_value=10)
    sc.tl.pca(ad, n_comps=min(N_PCS, ad.n_obs - 1, ad.n_vars - 1))
    if use_leiden:
        sc.pp.neighbors(ad, n_neighbors=15, transformer="sklearn")
        sc.tl.leiden(ad, resolution=LEIDEN_RES, key_added="cl", flavor="igraph", n_iterations=2, directed=False)
        return ad.obs["cl"].astype(str).values
    from sklearn.cluster import KMeans
    k = max(5, min(30, ad.n_obs // 300))
    return KMeans(n_clusters=k, n_init=5, random_state=0).fit_predict(ad.obsm["X_pca"]).astype(str)


def lineage_agree(ref, mk):
    if ref is None:
        return False
    ref = str(ref).lower()
    if mk == "smooth_muscle":
        return ref in ("stromal",)
    if mk == "mesothelial":
        return ref in ("stromal", "epithelial")
    if mk == "lymphoid":
        return ref in ("lymphocyte",)
    return ref == mk


# ----------------------------------------------------------------------------
# 1. Per-sample processing -> per-cell labels (subsampled)
# ----------------------------------------------------------------------------
def process_cells(gsm, d, C, lineage, use_leiden, rng):
    import scanpy as sc
    import scipy.sparse as sp
    tenx = find_10x(d)
    if tenx is None:
        return None, "no_10x_matrix"
    if tenx[0] == "mtx":
        adata = sc.read_10x_mtx(tenx[1], var_names="gene_symbols", make_unique=True, prefix=tenx[2] or None)
    else:
        adata = sc.read_10x_h5(tenx[1])
        adata.var_names_make_unique()
    adata.var["mt"] = adata.var_names.str.upper().str.startswith("MT-")
    sc.pp.calculate_qc_metrics(adata, qc_vars=["mt"], inplace=True, percent_top=None, log1p=False)
    adata = adata[(adata.obs["n_genes_by_counts"] >= MIN_GENES) & (adata.obs["pct_counts_mt"] < MAX_PCT_MT)].copy()
    if adata.n_obs < MIN_CELLS_SAMPLE:
        return None, "too_few_cells"
    counts = adata.X.tocsr() if sp.issparse(adata.X) else sp.csr_matrix(adata.X)
    sc.pp.normalize_total(adata, target_sum=1e4)
    sc.pp.log1p(adata)
    cl = cluster_labels(adata, use_leiden)
    genes = np.array(adata.var_names)
    gpos = {g: i for i, g in enumerate(genes)}
    common = [g for g in C.index if g in gpos]
    Cc = C.loc[common]
    lab = np.empty(adata.n_obs, dtype=object)
    lin = np.empty(adata.n_obs, dtype=object)
    agree = np.zeros(adata.n_obs, dtype=bool)
    for c in sorted(set(cl)):
        idx = np.where(cl == c)[0]
        tot = np.asarray(counts[idx].sum(axis=0)).ravel()
        cpm = tot / max(tot.sum(), 1) * 1e6
        prof = np.log2(cpm[[gpos[g] for g in common]] + 1)
        r = Cc.apply(lambda col: pd.Series(prof).corr(pd.Series(col.values), method="spearman")).sort_values(ascending=False)
        lm = {}
        for ln, ms in LINEAGE_MARKERS.items():
            ii = [gpos[m] for m in ms if m in gpos]
            lm[ln] = float(np.mean(np.log2(cpm[ii] + 1))) if ii else 0.0
        best = r.index[0]
        lab[idx] = best
        lin[idx] = lineage.get(best)
        agree[idx] = lineage_agree(lineage.get(best), max(lm, key=lm.get))
    keep = []
    for l in pd.unique(lab[agree]):
        idx = np.where(agree & (lab == l))[0]
        if len(idx) > CAP_PER_SAMPLE_LABEL:
            idx = rng.choice(idx, CAP_PER_SAMPLE_LABEL, replace=False)
        keep.extend(sorted(idx.tolist()))
    keep = np.array(sorted(keep), dtype=int)
    sub = counts[keep].astype(np.float32)
    obs = pd.DataFrame({"gsm": gsm, "label": lab[keep], "lineage": lin[keep],
                        "n_genes": np.asarray((counts[keep] > 0).sum(axis=1)).ravel()})
    return (sub, genes, obs, int(adata.n_obs), int(agree.sum())), "ok"


def build_cells():
    import scipy.sparse as sp
    f = CELLS_DIR / "cells.npz"
    if f.exists():
        z = np.load(f, allow_pickle=True)
        X = sp.csr_matrix((z["data"], z["indices"], z["indptr"]), shape=tuple(z["shape"]))
        obs = pd.read_csv(CELLS_DIR / "obs.csv")
        genes = list(pd.read_csv(CELLS_DIR / "genes.csv")["symbol"].astype(str))
        say("[CELLS] cached: cells=%d genes=%d" % X.shape)
        return X, obs, genes
    md = sample_metadata()
    md["context"] = md.apply(context_of, axis=1)
    pid_col = next((c for c in md.columns if c.lower().startswith("patient")), None)
    C, lineage = reference()
    use_leiden = ensure_leiden()
    rng = np.random.default_rng(SEED)
    want = set(sum(CONTEXTS.values(), []))
    mats, obss, union = [], [], {}
    t0 = time.time()
    for d in sorted(p for p in X_DIR.iterdir() if p.is_dir()):
        row = md[md["gsm"] == d.name]
        if not len(row):
            continue
        row = row.iloc[0]
        desc = (str(row.get("description", "")) + " " + str(row.get("library_strategy", ""))).lower()
        if row["context"] not in want or "visium" in desc or "spatial" in desc or str(row.get("library_strategy", "")).upper() == "OTHER":
            continue
        try:
            res, st = process_cells(d.name, d, C, lineage, use_leiden, rng)
        except Exception as e:
            res, st = None, "error:%s" % type(e).__name__
        if res is None:
            say("    [SKIP] %s %s" % (d.name, st))
            continue
        sub, genes, obs, nqc, nagree = res
        obs["context"] = row["context"]
        obs["patient"] = row.get(pid_col) if pid_col else None
        for g in genes:
            if g not in union:
                union[g] = len(union)
        mats.append((sub, genes))
        obss.append(obs)
        say("    [CELLS] %s %-18s qc=%d agree=%d kept=%d %.0f min" % (d.name, row["context"], nqc, nagree, sub.shape[0], (time.time() - t0) / 60))
    glist = list(union.keys())
    blocks = []
    for sub, genes in mats:
        coo = sub.tocoo()
        cols = np.array([union[g] for g in genes])[coo.col]
        blocks.append(sp.csr_matrix((coo.data, (coo.row, cols)), shape=(sub.shape[0], len(glist))))
    X = sp.vstack(blocks).tocsr()
    obs = pd.concat(obss, ignore_index=True)
    np.savez_compressed(f, data=X.data, indices=X.indices, indptr=X.indptr, shape=np.array(X.shape))
    obs.to_csv(CELLS_DIR / "obs.csv", index=False)
    pd.Series(glist).to_csv(CELLS_DIR / "genes.csv", index=False, header=["symbol"])
    say("[CELLS] built: cells=%d genes=%d" % X.shape)
    return X, obs, glist


# ----------------------------------------------------------------------------
# 2-3. scDRS
# ----------------------------------------------------------------------------
def ensure_scdrs():
    try:
        import scdrs  # noqa
        return True
    except Exception:
        p = subprocess.run([str(VENV_PY), "-m", "pip", "install", "-q", "scdrs==1.0.2"], capture_output=True, text=True)
        say("[PIP] scdrs==1.0.2 rc=%d %s" % (p.returncode, p.stderr.strip()[-200:]))
        try:
            import importlib
            importlib.invalidate_caches()
            import scdrs  # noqa
            return True
        except Exception as e:
            say("[SCDRS] unavailable: %s %s" % (type(e).__name__, str(e)[:200]))
            return False


def gene_sets(present):
    sym = {}
    for line in open(GENE_LOC_B37):
        x = line.split()
        if len(x) >= 6:
            sym[x[0]] = x[5]
    out = {}
    for t in TRAITS:
        f = MAGMA_OUT / (t + "_35_10.genes.out")
        if not f.exists():
            say("[GS] %s genes.out missing" % t)
            continue
        g = pd.read_csv(f, sep=r"\s+")
        g["SYM"] = g["GENE"].astype(str).map(sym)
        g = g[g["SYM"].isin(present)].sort_values("ZSTAT", ascending=False).drop_duplicates("SYM").head(N_TOP)
        out[t] = (list(g["SYM"]), list(np.minimum(g["ZSTAT"].values, 10.0)))
        say("[GS] %-13s %d genes (z %.2f .. %.2f)" % (t, len(g), g["ZSTAT"].min(), g["ZSTAT"].max()))
    return out


def assoc(norm, ctrl, idx):
    q_obs = np.quantile(norm[idx], 0.95)
    q_ctrl = np.quantile(ctrl[idx], 0.95, axis=0)
    mcp = (1 + np.sum(q_ctrl >= q_obs)) / (1 + ctrl.shape[1])
    mcz = (q_obs - q_ctrl.mean()) / max(q_ctrl.std(), 1e-12)
    return mcp, mcz


def is_macro(label):
    s = str(label)
    return s.startswith("MPhi") or s.startswith("M$\\Phi$") or s.startswith("MΦ")


def run_scdrs(X, obs, genes):
    import anndata as ad
    import scanpy as sc
    import scdrs
    rows = []
    gs_all = gene_sets(set(genes))
    for ctx, members in CONTEXTS.items():
        m = obs["context"].isin(members).to_numpy()
        a = ad.AnnData(X=X[m].copy(), obs=obs.loc[m].reset_index(drop=True))
        a.var_names = genes
        a.obs_names = ["c%d" % i for i in range(a.n_obs)]
        sc.pp.filter_genes(a, min_cells=10)
        sc.pp.normalize_total(a, target_sum=1e4)
        sc.pp.log1p(a)
        cov = pd.DataFrame(index=a.obs_names, data={"const": 1.0, "n_genes": a.obs["n_genes"].values.astype(float)})
        scdrs.preprocess(a, cov=cov, n_mean_bin=20, n_var_bin=20, copy=False)
        say("")
        say("[SCDRS] context=%s cells=%d genes=%d" % (ctx, a.n_obs, a.n_vars))
        groups = {}
        for lin in sorted(a.obs["lineage"].dropna().unique()):
            groups["lineage:" + lin] = np.where(a.obs["lineage"].values == lin)[0]
        vc = a.obs["label"].value_counts()
        for l in vc.index[vc >= MIN_GROUP_CELLS]:
            groups["label:" + l] = np.where(a.obs["label"].values == l)[0]
        for t, (gl, gw) in gs_all.items():
            keep = [i for i, g in enumerate(gl) if g in set(a.var_names)]
            t0 = time.time()
            res = scdrs.score_cell(data=a, gene_list=[gl[i] for i in keep], gene_weight=[gw[i] for i in keep],
                                   ctrl_match_key="mean_var", n_ctrl=N_CTRL, weight_opt="vs", return_ctrl_raw_score=False,
                                   return_ctrl_norm_score=True, verbose=False)
            norm = res["norm_score"].to_numpy(dtype=np.float32)
            ctrl = res[[c for c in res.columns if c.startswith("ctrl_norm_score_")]].to_numpy(dtype=np.float32)
            for gname, idx in groups.items():
                p, z = assoc(norm, ctrl, idx)
                rows.append({"context": ctx, "trait": t, "group": gname, "n_cells": len(idx), "mc_p": p, "mc_z": z})
            del res, ctrl
            say("    [SCDRS] %-13s %s scored in %.1f min" % (t, ctx, (time.time() - t0) / 60))
    df = pd.DataFrame(rows)
    df.to_csv(OUT / "scdrs_group_tests.csv", index=False)
    return df


def report(df):
    say("")
    say("-" * 72)
    say("[SECTION] scDRS association tests (MC p, 1,000 control gene sets; min p = 0.001)")
    for ctx in CONTEXTS:
        say("[CONTEXT] " + ctx)
        sub = df[df["context"] == ctx]
        lin = sub[sub["group"].str.startswith("lineage:")]
        piv = lin.pivot_table(index="group", columns="trait", values="mc_p")
        for g, r in piv.iterrows():
            say("    [LIN] %-24s %s" % (g.replace("lineage:", "")[:24], " ".join("%s=%.3f" % (t[:6], r.get(t, np.nan)) for t in TRAITS if t in piv.columns)))
        lab = sub[sub["group"].str.startswith("label:")]
        for t in TRAITS:
            s = lab[lab["trait"] == t].sort_values("mc_p")
            if len(s):
                say("    [TOP] %-13s %s" % (t[:13], "; ".join("%s p=%.3f" % (g.replace("label:", "")[:22], p) for g, p in zip(s["group"].head(5), s["mc_p"].head(5)))))
        mac = lab[lab["group"].str.replace("label:", "", regex=False).map(is_macro)]
        say("    [MACRO] labels: %s" % ", ".join(sorted(set(mac["group"].str.replace("label:", "", regex=False)))))
        for t in TRAITS:
            s = pd.concat([mac[mac["trait"] == t], lin[(lin["trait"] == t) & (lin["group"] == "lineage:myeloid")]])
            if len(s):
                h = holm(s["mc_p"].values)
                say("    [MACRO] %-13s %s" % (t[:13], "; ".join("%s p=%.3f H=%.3f" % (g.replace("label:", "").replace("lineage:", "")[:20], p, hh)
                                                              for g, p, hh in zip(s["group"], s["mc_p"], h))))
                SUM["results"]["%s_%s_macro_minHolm" % (ctx, t)] = float(h.min())
    # Fixed reading (v0.2.16)
    r = SUM["results"]
    endo = min(r.get("lesion_GCST90205183_macro_minHolm", 1), r.get("lesion_KOLLER_EUR_macro_minHolm", 1))
    repro = endo < 0.05
    spec = repro and r.get("lesion_HYPERTENSION_macro_minHolm", 0) >= 0.05 and r.get("lesion_T2D_macro_minHolm", 0) >= 0.05
    say("[OCHOA_VERDICT] lesion macrophage / myeloid association reproduced: %s (min Holm %.3f) | endometriosis-specific: %s" % (
        "YES" if repro else "NO", endo, "YES" if spec else "NO"))


def main():
    say("=" * 72)
    say("PAPER 9 | v0.0.25 | scDRS on GSE213216 (Ochoa 2025 claim), two GWAS + controls | " + TS)
    say("=" * 72)
    t0 = time.time()
    if not ensure_scdrs():
        say("[FATAL] scdrs not available")
    else:
        try:
            X, obs, genes = build_cells()
            say("[CELLS_BY_CONTEXT] " + " | ".join("%s=%d" % (k, v) for k, v in obs["context"].value_counts().items()))
            df = run_scdrs(X, obs, genes)
            report(df)
        except Exception as e:
            import traceback
            say("[STEP_ERROR] %s: %s" % (type(e).__name__, str(e)[:300]))
            say(traceback.format_exc()[-1500:])
    with open(OUT / "p9_v025_summary.json", "w") as f:
        json.dump(SUM, f, indent=2, default=str)
    say("")
    say("[TIME] %.0f min" % ((time.time() - t0) / 60))
    say("[OUTPUT] " + str(OUT))
    say("[LOG] " + str(LOG))
    say("[POLICY] rules fixed in CHANGELOG v0.2.16 before this run")
    say("[DONE] PAPER9_V025_COMPLETE")
    _fh.close()


if __name__ == "__main__":
    main()
