TRAITS = ["KOLLER_EUR", "GCST90205183", "ENDO_OVARY", "ENDO_PERITONEUM", "HYPERTENSION", "T2D", "LEIOMYOMA"]
JK_TRAITS = ["KOLLER_EUR", "GCST90205183", "ENDO_OVARY"]
N_BLOCKS = 50

for d in (OUT, WORK, LOG.parent, FT_FILE.parent, PB_DIR):
    d.mkdir(parents=True, exist_ok=True)
_fh = open(LOG, "w", encoding="utf-8")
SUM = {"task": "PAPER9_V032_B1", "timestamp_utc": TS, "results": {}}


def say(msg=""):
    print(msg, flush=True)
    _fh.write(msg + "\n")
    _fh.flush()


def sh(cmd, timeout=None):
    try:
        p = subprocess.run([str(c) for c in cmd], capture_output=True, text=True, timeout=timeout, env=ENV1)
        return p.returncode, p.stdout, p.stderr
    except subprocess.TimeoutExpired:
        return 124, "", "timeout"


def entrez_unique():
    sym2, dup = {}, set()
    for line in open(GENE_LOC_B37):
        x = line.split()
        if len(x) >= 6 and x[1] in [str(c) for c in range(1, 23)]:
            if x[5] in sym2:
                dup.add(x[5])
            sym2[x[5]] = x[0]
    for d in dup:
        sym2.pop(d, None)
    return sym2


def gene_positions():
    pos = {}
    for line in open(GENE_LOC_B37):
        x = line.split()
        if len(x) >= 6 and x[1] in [str(c) for c in range(1, 23)]:
            pos[x[0]] = (int(x[1]), int(x[2]))
    return pos


def magma_gp(trait, covf, cond, tag):
    raw = MAGMA_OUT / (trait + "_35_10.genes.raw")
    if not raw.exists():
        return None
    outp = WORK / ("%s__%s" % (trait, tag))
    gsa = Path(str(outp) + ".gsa.out")
    o = e = ""
    for key in ("condition-hide=", "condition="):
        if gsa.exists():
            gsa.unlink()
        rc, o, e = sh(NICE + [MAGMA, "--gene-results", raw, "--gene-covar", covf, "--model", key + cond,
                              "direction=greater", "--out", outp], timeout=3600)
        if rc == 0 and gsa.exists():
            rows = [l for l in open(gsa) if not l.startswith("#") and l.strip()]
            hdr = rows[0].split()
            res = {}
            for l in rows[1:]:
                d = dict(zip(hdr, l.split()))
                name = d.get("FULL_NAME", d.get("VARIABLE"))
                try:
                    res[name] = {"beta": float(d["BETA"]), "beta_std": float(d.get("BETA_STD", "nan")),
                                 "se": float(d["SE"]), "p": float(d["P"])}
                except (KeyError, ValueError):
                    continue
            return res
    say("    [MAGMA_FAIL] %s %s %s" % (trait, tag, (o + e).strip()[-200:]))
    return None


# ----------------------------------------------------------------------------
# 1. Download and read the atlas (h5py, streaming)
# ----------------------------------------------------------------------------
def download():
    if FT_FILE.exists() and FT_FILE.stat().st_size > 100_000_000:
        say("[DL] present %.0f MB" % (FT_FILE.stat().st_size / 1e6))
        return True
    p = subprocess.run(["curl", "-sSL", "--fail", "--max-time", "120", "-A", "paper9", CXG_API], capture_output=True)
    url = None
    if p.returncode == 0:
        rec = json.loads(p.stdout.decode("utf-8", "replace"))
        for ds in rec.get("datasets", []):
            if ds.get("dataset_id") == DATASET_ID:
                for a in ds.get("assets", []):
                    if a.get("filetype", "").upper() == "H5AD":
                        url = a.get("url")
    if not url:
        say("[DL] asset URL not found via API")
        return False
    part = FT_FILE.with_name(FT_FILE.name + ".part")
    t0 = time.time()
    rc, o, e = sh(["curl", "-L", "-sS", "--fail", "--retry", "3", "-C", "-", "-A", "paper9", "-o", part, url], timeout=4 * 3600)
    if rc == 0 and part.exists():
        part.rename(FT_FILE)
        say("[DL] OK %.0f MB in %.0f min" % (FT_FILE.stat().st_size / 1e6, (time.time() - t0) / 60))
        return True
    say("[DL] FAILED rc=%d %s" % (rc, e.strip()[:200]))
    return False


def dec(x):
    return x.decode() if isinstance(x, bytes) else str(x)


def obs_col(f, name):
    g = f["obs"][name]
    if isinstance(g, h5py.Group) and "categories" in g:
        cats = np.array([dec(c) for c in g["categories"][:]], dtype=object)
        codes = g["codes"][:]
        out = np.empty(len(codes), dtype=object)
        ok = codes >= 0
        out[ok] = cats[codes[ok]]
        return out
    if "__categories" in f["obs"] and name in f["obs"]["__categories"]:
        cats = np.array([dec(c) for c in f["obs"]["__categories"][name][:]], dtype=object)
        codes = g[:]
        out = np.empty(len(codes), dtype=object)
        ok = codes >= 0
        out[ok] = cats[codes[ok]]
        return out
    v = g[:]
    return np.array([dec(x) for x in v], dtype=object) if v.dtype.kind in "SO" else v


def var_symbols(f, matrix_group):
    # gene symbols for the columns of the chosen matrix
    base = "raw/var" if matrix_group.startswith("raw") and "raw/var" in f else "var"
    v = f[base]
    for col in ("feature_name", "gene_symbols", "gene_name"):
        if col in v:
            g = v[col]
            if isinstance(g, h5py.Group) and "categories" in g:
                cats = np.array([dec(c) for c in g["categories"][:]], dtype=object)
                return cats[g["codes"][:]]
            return np.array([dec(x) for x in g[:]], dtype=object)
    if base == "raw/var" and "feature_name" in f["var"]:
        return var_symbols(f, "X")
    idx = v.attrs.get("_index", "_index")
    return np.array([dec(x) for x in v[idx][:]], dtype=object)


def build_pseudobulk():
    done = PB_DIR / "pseudobulk_counts.npy"
    if done.exists():
        gt = pd.read_csv(PB_DIR / "groups.csv")
        genes = list(pd.read_csv(PB_DIR / "genes.csv")["symbol"].astype(str))
        say("[PB] cached groups=%d genes=%d" % (len(gt), len(genes)))
        return np.load(done), gt, genes
    f = h5py.File(FT_FILE, "r")
    cols = [k for k in f["obs"].keys() if k not in ("_index", "__categories")]
    say("[OBS] columns: " + ", ".join(cols))
    info = {}
    for c in cols:
        try:
            v = obs_col(f, c)
            if v.dtype == object:
                vc = pd.Series(v).value_counts()
                info[c] = vc
                if len(vc) <= 40:
                    say("    [OBS] %-28s n=%d %s" % (c, len(vc), " | ".join("%s=%d" % (k, n) for k, n in vc.head(25).items())[:600]))
        except Exception:
            continue
    # cell-type column: author annotation with most categories, else cell_type
    cand = [c for c in info if re.search(r"author|annotation|celltype|cell_type_|cluster", c, re.I) and c != "cell_type_ontology_term_id"]
    cand = [c for c in cand if 3 <= len(info[c]) <= 80]
    ctype_col = max(cand, key=lambda c: len(info[c])) if cand else "cell_type"
    say("[CELLTYPE_COLUMN] %s (%d labels)" % (ctype_col, len(info.get(ctype_col, []))))
    ctype = obs_col(f, ctype_col)
    donor = obs_col(f, "donor_id") if "donor_id" in cols else obs_col(f, next(c for c in cols if "donor" in c.lower()))
    keep = np.ones(len(ctype), dtype=bool)
    meno_col = None
    for c, vc in info.items():
        if any(re.search(r"pre.?menopaus", str(k), re.I) for k in vc.index):
            meno_col = c
            break
    if meno_col:
        v = obs_col(f, meno_col)
        keep = np.array([bool(re.search(r"pre.?menopaus", str(x), re.I)) for x in v])
        say("[DONORS] pre-menopausal by column %s: cells %d / %d" % (meno_col, int(keep.sum()), len(keep)))
    elif "development_stage" in cols:
        v = obs_col(f, "development_stage")
        age = np.array([float(m.group(1)) if (m := re.search(r"(\d+)-year", str(x))) else np.nan for x in v])
        if np.isfinite(age).any():
            keep = age < 50
            say("[DONORS] pre-menopausal by age < 50: cells %d / %d" % (int(keep.sum()), len(keep)))
        else:
            say("[DONORS] no menopause / age information: all donors kept")
    mg = "raw/X" if "raw" in f and "X" in f["raw"] else "X"
    X = f[mg]
    genes = var_symbols(f, mg)
    say("[MATRIX] %s; genes=%d; encoding=%s" % (mg, len(genes), dict(X.attrs).get("encoding-type") if isinstance(X, h5py.Group) else "dense"))
    if not isinstance(X, h5py.Group):
        raise RuntimeError("dense matrix not supported")
    data, indices, indptr = X["data"], X["indices"], X["indptr"][:]
    sample = np.asarray(data[:2_000_000])
    say("[MATRIX] integer-valued sample: %s (max %.0f)" % (bool(np.all(np.mod(sample, 1) == 0)), sample.max()))
    keys = pd.Series([("%s||%s" % (d, t)) if k else None for d, t, k in zip(donor, ctype, keep)])
    codes, uniq = pd.factorize(keys)
    ng = len(genes)
    acc = np.zeros(len(uniq) * ng, dtype=np.float64)
    n = len(indptr) - 1
    step = 20000
    t0 = time.time()
    for a in range(0, n, step):
        b = min(n, a + step)
        s, e = int(indptr[a]), int(indptr[b])
        ii = np.asarray(indices[s:e], dtype=np.int64)
        xx = np.asarray(data[s:e], dtype=np.float64)
        g = np.repeat(codes[a:b], np.diff(indptr[a:b + 1]))
        m = g >= 0
        acc += np.bincount(g[m] * ng + ii[m], weights=xx[m], minlength=len(uniq) * ng)
    pb = acc.reshape(len(uniq), ng)
    gt = pd.DataFrame({"group": list(uniq)})
    gt["donor"] = gt["group"].str.split("||", regex=False).str[0]
    gt["type"] = gt["group"].str.split("||", regex=False).str[1]
    gt["n_cells"] = pd.Series(codes[codes >= 0]).value_counts().sort_index().values
    np.save(done, pb)
    gt.to_csv(PB_DIR / "groups.csv", index=False)
    pd.Series(genes).to_csv(PB_DIR / "genes.csv", index=False, header=["symbol"])
    say("[PB] built groups=%d genes=%d (%.0f min)" % (len(gt), ng, (time.time() - t0) / 60))
    return pb, gt, list(genes)


# ----------------------------------------------------------------------------
# 2. Specificity and covariates
# ----------------------------------------------------------------------------
def ft_specificity(pb, gt, genes):
    sub = gt[gt["n_cells"] >= MIN_CELLS_DONOR_TYPE]
    agg = sub.groupby("type").agg(n_donors=("donor", "nunique"), n_cells=("n_cells", "sum"))
    ok = agg[(agg["n_donors"] >= MIN_DONORS_TYPE) & (agg["n_cells"] >= MIN_CELLS_TYPE)].index.tolist()
    say("[FT_TYPES] eligible %d / %d" % (len(ok), len(agg)))
    for t, r in agg.sort_values("n_cells", ascending=False).iterrows():
        comp = "FT_SEC" if FT_SEC_RE.search(t) else ("FT_CIL" if FT_CIL_RE.search(t) else ("FT_STR (post hoc)" if FT_STR_RE.search(t) else "-"))
        if comp != "-":
            say("    [FT_TYPE] %-12s donors=%-3d cells=%-7d %-4s %s" % (t[:12], r["n_donors"], r["n_cells"], "OK" if t in ok else "DROP", comp))
    means = {}
    for t in ok:
        rows = sub.index[sub["type"] == t].to_numpy()
        mats = pb[rows]
        lib = mats.sum(axis=1, keepdims=True)
        means[t] = (mats / np.where(lib > 0, lib, 1) * 1e6).mean(axis=0)
    M = pd.DataFrame(means, index=genes)
    M = M.groupby(level=0).sum()
    M = M[(M >= 1.0).any(axis=1)]
    S = M.div(M.sum(axis=1), axis=0)
    return S, M


def joint_covariates(S_ft, M_ft, sym2):
    S_h = pd.read_csv(HECA_GS / "specificity_by_type.csv.gz", index_col=0)
    M_h = pd.read_csv(HECA_GS / "mean_cpm_by_type.csv.gz", index_col=0).loc[S_h.index, S_h.columns]
    epi = [t for t in S_h.columns if HECA_EPI_RE.search(t) and not HECA_CIL_RE.search(t)]
    cil = [t for t in S_h.columns if HECA_CIL_RE.search(t)]
    hstr = [t for t in S_h.columns if HECA_STR_RE.search(t)]
    sec = [t for t in S_ft.columns if FT_SEC_RE.search(t)]
    ftc = [t for t in S_ft.columns if FT_CIL_RE.search(t) and not FT_SEC_RE.search(t)]
    fstr = [t for t in S_ft.columns if FT_STR_RE.search(t)]
    say("[COMPARTMENTS] FT_SEC=%s | FT_CIL=%s | FT_STR=%s" % (", ".join(sec) or "-", ", ".join(ftc) or "-", ", ".join(fstr) or "-"))
    say("[COMPARTMENTS] HECA_EPI=%s | HECA_CIL=%s" % (", ".join(epi) or "-", ", ".join(cil) or "-"))
    say("[COMPARTMENTS] HECA_STR=%s" % (", ".join(hstr) or "-"))
    genes = [g for g in S_ft.index.intersection(S_h.index) if g in sym2]
    J = pd.DataFrame(index=genes)
    J["FT_SEC"] = S_ft.loc[genes, sec].sum(axis=1) if sec else np.nan
    J["FT_CIL"] = S_ft.loc[genes, ftc].sum(axis=1) if ftc else np.nan
    J["HECA_EPI"] = S_h.loc[genes, epi].sum(axis=1) if epi else np.nan
    J["HECA_CIL"] = S_h.loc[genes, cil].sum(axis=1) if cil else np.nan
    J["FT_STR"] = S_ft.loc[genes, fstr].sum(axis=1) if fstr else np.nan
    J["HECA_STR"] = S_h.loc[genes, hstr].sum(axis=1) if hstr else np.nan
    J["AVG_FT"] = np.log2(M_ft.loc[genes].mean(axis=1) + 1.0)
    J["AVG_H"] = np.log2(M_h.loc[genes].mean(axis=1) + 1.0)
    J = J.dropna(axis=1, how="all").dropna()
    J.insert(0, "GENE", [sym2[g] for g in J.index])
    fj = WORK / "B1_joint.covar.txt"
    J.to_csv(fj, sep="\t", index=False, float_format="%.6g")
    keys = ["K%02d" % (i + 1) for i in range(S_ft.shape[1])]
    lab = dict(zip(keys, S_ft.columns))
    F = pd.DataFrame(S_ft.loc[genes].values, columns=keys, index=genes)
    F["Average"] = J["AVG_FT"]
    F = F.dropna()
    F.insert(0, "GENE", [sym2[g] for g in F.index])
    ff = WORK / "B1_ft_types.covar.txt"
    F.to_csv(ff, sep="\t", index=False, float_format="%.6g")
    say("[COVARIATES] shared genes=%d" % len(J))
    return fj, ff, lab, list(J.columns[1:])


def label_check(S_ft):
    # author label vs CELLxGENE cell_type (pre-menopausal cells) for every compartment label
    f = h5py.File(FT_FILE, "r")
    cols = list(f["obs"].keys())
    if "author_cell_type" not in cols or "cell_type" not in cols:
        say("[LABEL_CHECK] author_cell_type / cell_type not found; skipped")
        f.close()
        return
    a = obs_col(f, "author_cell_type")
    c = obs_col(f, "cell_type")
    m = obs_col(f, "donor_menopausal_status") if "donor_menopausal_status" in cols else None
    f.close()
    keep = np.array([bool(re.search(r"pre.?menopaus", str(x), re.I)) for x in m]) if m is not None else np.ones(len(a), bool)
    T = pd.crosstab(pd.Series(a[keep], name="author"), pd.Series(c[keep], name="cell_type"))
    T.to_csv(OUT / "label_check_author_vs_celltype.csv")
    for comp, rx in (("FT_SEC", FT_SEC_RE), ("FT_CIL", FT_CIL_RE), ("FT_STR", FT_STR_RE)):
        labs = [t for t in S_ft.columns if rx.search(t) and t in T.index and not (comp == "FT_CIL" and FT_SEC_RE.search(t))]
        if not labs:
            continue
        sub = T.loc[labs].sum(axis=0)
        sub = sub[sub > 0].sort_values(ascending=False)
        say("[LABEL_CHECK] %s (%d labels, %d cells): %s" % (comp, len(labs), int(sub.sum()),
                                                          "; ".join("%s %.0f%%" % (k, 100 * v / sub.sum()) for k, v in sub.head(3).items())))


# ----------------------------------------------------------------------------
# 3. Tests
# ----------------------------------------------------------------------------
def jk(full, parts):
    parts = np.asarray([x for x in parts if np.isfinite(x)])
    B = len(parts)
    se = math.sqrt((B - 1) / B * np.sum((parts - parts.mean()) ** 2)) if B > 1 else float("nan")
    return se


def tests(fj, ff, lab, jcols):
    say("")
    say("-" * 72)
    say("[SECTION] B1 tests (MAGMA gene-property, direction=greater; primary KOLLER_EUR)")
    rows = []
    for trait in TRAITS:
        r = magma_gp(trait, ff, "Average", "B1_types")
        if r:
            df = pd.DataFrame([{"type": lab[k], **r[k]} for k in lab if k in r]).sort_values("p")
            say("    [FT_TOP] %-15s %s" % (trait[:15], "; ".join("%s p=%.1e" % (t[:22], p) for t, p in zip(df["type"].head(5), df["p"].head(5)))))
            df.assign(trait=trait).to_csv(OUT / ("B1_types_%s.csv" % trait), index=False)
    comps = [c for c in ("FT_SEC", "FT_CIL", "HECA_EPI", "HECA_CIL", "FT_STR", "HECA_STR") if c in jcols]
    pairs = [("FT_SEC", "HECA_EPI"), ("FT_CIL", "HECA_CIL"), ("FT_STR", "HECA_STR")]
    for trait in TRAITS:
        base = magma_gp(trait, fj, "AVG_FT,AVG_H", "B1_marg")
        if not base:
            continue
        line = []
        for a, b in pairs:
            if a in comps and b in comps:
                ca = magma_gp(trait, fj, "AVG_FT,AVG_H," + b, "B1_%s_given_%s" % (a, b))
                cb = magma_gp(trait, fj, "AVG_FT,AVG_H," + a, "B1_%s_given_%s" % (b, a))
                pa, pb_ = (ca or {}).get(a, {}).get("p", np.nan), (cb or {}).get(b, {}).get("p", np.nan)
                line.append("%s p=%.3g (|%s %.3g) vs %s p=%.3g (|%s %.3g)" % (a, base[a]["p"], b, pa, b, base[b]["p"], a, pb_))
                rows.append({"trait": trait, "pair": a + "_vs_" + b, "p_a": base[a]["p"], "p_a_cond": pa, "p_b": base[b]["p"], "p_b_cond": pb_,
                             "bstd_a": base[a]["beta_std"], "bstd_b": base[b]["beta_std"]})
        say("    [B1] %-15s %s" % (trait[:15], " || ".join(line)))
    R = pd.DataFrame(rows)
    if not len(R):
        say("[STOP] no compartment pair available; nothing to test")
        return False
    # jackknife of standardized differences (marginal model)
    pos = gene_positions()
    J = pd.read_csv(fj, sep="\t")
    J["GENE"] = J["GENE"].astype(str)
    g = sorted([x for x in J["GENE"] if x in pos], key=lambda x: pos[x])
    blocks = [set(np.array(g)[i]) for i in np.array_split(np.arange(len(g)), N_BLOCKS)]
    for trait in JK_TRAITS:
        parts = {p: [] for p in pairs}
        for bl in blocks:
            f = WORK / "B1_blk.covar.txt"
            J[~J["GENE"].isin(bl)].to_csv(f, sep="\t", index=False, float_format="%.6g")
            r = magma_gp(trait, f, "AVG_FT,AVG_H", "B1_blk")
            for a, b in pairs:
                if r and a in r and b in r:
                    parts[(a, b)].append(r[a]["beta_std"] - r[b]["beta_std"])
        for a, b in pairs:
            s = R[(R["trait"] == trait) & (R["pair"] == a + "_vs_" + b)]
            if not len(s) or not parts[(a, b)]:
                continue
            full = float(s["bstd_a"].iloc[0] - s["bstd_b"].iloc[0])
            se = jk(full, parts[(a, b)])
            z = full / se if se and se > 1e-12 else np.nan
            p1 = 0.5 * math.erfc(z / math.sqrt(2)) if np.isfinite(z) else np.nan
            say("    [B1_JK] %-15s BETA_STD(%s) - BETA_STD(%s) = %+.4f (jk se %.4f, z %+.2f, one-sided p %.3f)" % (trait[:15], a, b, full, se, z, p1))
            R.loc[s.index, "jk_diff"] = full
            R.loc[s.index, "jk_p"] = p1
    R.to_csv(OUT / "B1_compartments.csv", index=False)
    # Fixed reading (v0.2.19)
    for a, b in pairs:
        k = R[(R["trait"] == "KOLLER_EUR") & (R["pair"] == a + "_vs_" + b)]
        h = R[(R["trait"] == "HYPERTENSION") & (R["pair"] == a + "_vs_" + b)]
        t2 = R[(R["trait"] == "T2D") & (R["pair"] == a + "_vs_" + b)]
        if not len(k):
            continue
        ok = (k["p_a_cond"].iloc[0] < 0.05) and (k.get("jk_p", pd.Series([np.nan])).iloc[0] < 0.05)
        ctrl = (len(h) and h["p_a_cond"].iloc[0] < 0.05) or (len(t2) and t2["p_a_cond"].iloc[0] < 0.05)
        v = "YES" if ok and not ctrl else ("NO (shared with a control trait)" if ok else "NO")
        say("[B1_VERDICT] %s preferential over %s%s: %s" % (a, b, " (POST HOC)" if a == "FT_STR" else "", v))
        SUM["results"]["B1_" + a] = v
    return True


def main():
    say("=" * 72)
    say("PAPER 9 | v0.0.32 | B1 fallopian-tube programs vs endometrium, re-run (exploratory) | " + TS)
    say("=" * 72)
    t0 = time.time()
    complete = False
    try:
        if download():
            pb, gt, genes = build_pseudobulk()
            S_ft, M_ft = ft_specificity(pb, gt, genes)
            label_check(S_ft)
            fj, ff, lab, jcols = joint_covariates(S_ft, M_ft, entrez_unique())
            complete = bool(tests(fj, ff, lab, jcols))
    except Exception as e:
        import traceback
        say("[STEP_ERROR] %s: %s" % (type(e).__name__, str(e)[:300]))
        say(traceback.format_exc()[-1500:])
    with open(OUT / "p9_v029_summary.json", "w") as f:
        json.dump(SUM, f, indent=2, default=str)
    say("")
    say("[TIME] %.0f min" % ((time.time() - t0) / 60))
    say("[OUTPUT] " + str(OUT))
    say("[LOG] " + str(LOG))
    say("[POLICY] rules CHANGELOG v0.2.19; label amendment v0.2.22 written after v029 printed the per-type list (see CHANGELOG)")
    say("[DONE] PAPER9_V032_COMPLETE" if complete else "[DONE] PAPER9_V032_INCOMPLETE")
    _fh.close()


if __name__ == "__main__":
    main()
''',
    'scripts/p9_v034_koller_sign.py': r'''#!/usr/bin/env python3
# Paper 9 | v0.0.34 | A5 follow-up on the v031 LD scores (rules CHANGELOG v0.2.23); no new LD scores:
#   K7 sign decomposition: for every cell type, joint S-LDSC of its UP and DOWN sets (UP | DOWN and DOWN | UP);
#   K8 decidual stroma (UP sets) vs every vascular / perivascular / smooth-muscle UP set, both directions.
# Runs in ~/Desktop/paper9/.venv, low-heat (nice 10, 2 BLAS threads). ~30-45 min; cached fits are reused.

import os
os.environ.setdefault("OMP_NUM_THREADS", "2")
os.environ.setdefault("OPENBLAS_NUM_THREADS", "2")
os.environ.setdefault("VECLIB_MAXIMUM_THREADS", "2")
os.environ.setdefault("NUMBA_NUM_THREADS", "2")
try:
    os.nice(10)
except Exception:
    pass

import datetime as dt
import json
import re
import subprocess
import time
from pathlib import Path

import h5py
import numpy as np
import pandas as pd

# ----------------------------------------------------------------------------
# Hardcoded locations
# ----------------------------------------------------------------------------
HOME = Path.home()
REPO = HOME / "Desktop" / "paper9"
RAW = REPO / "data" / "raw"
INTERIM = REPO / "data" / "interim"
PROC = REPO / "data" / "processed"
TOOLS = REPO / "tools"
LDSC_PY = TOOLS / "ldsc_venv" / "bin" / "python"
LDSC = TOOLS / "ldsc_py3" / "ldsc.py"
MAGMA = TOOLS / "magma" / "magma_bin"
GENE_LOC_B37 = TOOLS / "magma" / "genes_b37" / "NCBI37.3.gene.loc"
MAGMA_OUT = INTERIM / "magma"
REF = RAW / "ldsc_ref" / "unpacked"
PLINK_DIR = REF / "1000G_EUR_Phase3_plink"
FRQ_DIR = REF / "1000G_Phase3_frq"
HM3_LIST = RAW / "ldsc_ref" / "hm3_no_MHC.list.txt"
MUNGED = PROC / "munged"
HECA_FILE = RAW / "heca" / "endometriumAtlasV2_cells_with_counts.h5ad"
V030_GS = PROC / "genesets" / "heca_koller_v030"
V030_LD = PROC / "ldscores" / "heca_koller_v030"
GS_BASE = PROC / "genesets" / "heca_koller_v031"
LD_BASE = PROC / "ldscores" / "heca_koller_v031"
LD_DIR = V030_LD  # reassigned per family (helpers below read this global)

TS = dt.datetime.now(dt.timezone.utc).strftime("%Y%m%dT%H%M%SZ")
OUT = REPO / "results" / "koller_repro" / ("p9_v034_" + TS)
LOG = REPO / "logs" / ("p9_v034_koller_sign_" + TS + ".log")
NICE = ["nice", "-n", "10"]
N_WORKERS = 1
BLAS_THREADS = "2"
L2_ENV = dict(os.environ, OPENBLAS_NUM_THREADS=BLAS_THREADS, OMP_NUM_THREADS=BLAS_THREADS,
              VECLIB_MAXIMUM_THREADS=BLAS_THREADS, MKL_NUM_THREADS=BLAS_THREADS, NUMEXPR_NUM_THREADS=BLAS_THREADS)
WINDOW_BP = 100_000
LD_WIND_CM = 1.0

# Fixed (CHANGELOG v0.2.20)
DONOR_COL = "genotype"
TYPE_COL = "celltype"
PATHOLOGY_COL = "Endometrial_pathology"
STAGE_COL = "Binary Stage"
EXCLUDE_STAGE = "Hormones"
IMMUNE_RE = re.compile(r"Immune|^uM|uNK|^T_|^B_|Mast|DC|Mono|Macro|Neutro|Plasma|ILC|Lymphoid|Myeloid")
NOT_IMMUNE_RE = re.compile(r"Lymphatic")
MIN_CELLS_TYPE = 30
CAP_CELLS_TYPE = 400
SEED = 20261106
LFC = 1.2
PADJ = 0.01
MIN_SET = 20
TRAITS = ["KOLLER_EUR", "GCST90205183", "ENDO_ALL", "HYPERTENSION", "T2D", "LEIOMYOMA"]
TRAITS_SENS = ["KOLLER_EUR", "GCST90205183", "ENDO_ALL"]
TRAITS_COND = ["KOLLER_EUR", "GCST90205183"]
KOLLER_N = {"ENDO": 22, "CTL": 13}
FOCUS_RE = r"dStromal|SOX9_functionalis"
ENDOTHELIAL_RE = r"^(Venous|Arterial)$"
VARIANTS = {"P": {"hormones": False, "cap": CAP_CELLS_TYPE, "desc": "v030 cells (non-hormone, <= 400 per type)"},
            "H": {"hormones": True, "cap": CAP_CELLS_TYPE, "desc": "hormone-treated samples included"},
            "N": {"hormones": False, "cap": None, "desc": "all cells (no cap)"}}

for d in (OUT, LOG.parent, GS_BASE, LD_BASE):
    d.mkdir(parents=True, exist_ok=True)
_fh = open(LOG, "w", encoding="utf-8")
SUM = {"task": "PAPER9_V034_KOLLER_SIGN", "timestamp_utc": TS, "gates": {}, "results": {}}


def say(msg=""):
    print(msg, flush=True)
    _fh.write(msg + "\n")
    _fh.flush()


def sh(cmd, cwd=None, timeout=None, env=None):
    try:
        p = subprocess.run([str(c) for c in cmd], cwd=cwd, capture_output=True, text=True, timeout=timeout, env=env)
        return p.returncode, p.stdout, p.stderr
    except FileNotFoundError as e:
        return 127, "", str(e)
    except OSError as e:
        return 126, "", str(e)
    except subprocess.TimeoutExpired:
        return 124, "", "timeout"


def safe(name):
    return re.sub(r"[^A-Za-z0-9]+", "_", name).strip("_")


def bh(p):
    p = np.asarray(p, dtype=float)
    n = len(p)
    order = np.argsort(p)
    ranked = p[order] * n / (np.arange(n) + 1)
    q = np.minimum.accumulate(ranked[::-1])[::-1]
    out = np.empty(n)
    out[order] = np.minimum(q, 1.0)
    return out


def dec(x):
    return x.decode() if isinstance(x, bytes) else str(x)


def obs_cat(f, name):
    obs = f["obs"]
    g = obs[name]
    if isinstance(g, h5py.Group) and "categories" in g:
        cats = np.array([dec(c) for c in g["categories"][:]], dtype=object)
        codes = g["codes"][:]
    elif "__categories" in obs and name in obs["__categories"]:
        cats = np.array([dec(c) for c in obs["__categories"][name][:]], dtype=object)
        codes = g[:]
    else:
        v = g[:]
        return np.array([dec(x) for x in v], dtype=object)
    out = np.empty(len(codes), dtype=object)
    ok = codes >= 0
    out[ok] = cats[codes[ok]]
    out[~ok] = None
    return out


def gene_map():
    sym2, dup = {}, set()
    for line in open(GENE_LOC_B37):
        t = line.split()
        if len(t) >= 6 and t[1] in [str(c) for c in range(1, 23)]:
            if t[5] in sym2:
                dup.add(t[5])
            sym2[t[5]] = (t[0], int(t[1]), int(t[2]), int(t[3]))
    for d in dup:
        sym2.pop(d, None)
    return sym2


# ----------------------------------------------------------------------------
# LDSC-SEG helpers reused verbatim from v012
# ----------------------------------------------------------------------------
def merged_intervals(gene_rows, chrom):
    iv = sorted((max(0, s - WINDOW_BP), e + WINDOW_BP) for c, s, e in gene_rows if c == chrom)
    out = []
    for s, e in iv:
        if out and s <= out[-1][1]:
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])
    return np.array(out, dtype=np.int64).reshape(-1, 2)


def write_annotations(all_sets, sym2):
    keys = list(all_sets.keys())
    pd.Series(keys).to_csv(LD_DIR / "columns.txt", index=False, header=False)
    for chrom in range(1, 23):
        f = LD_DIR / ("annot.%d.annot" % chrom)
        old = LD_DIR / ("annot.%d.annot.gz" % chrom)
        if old.exists():
            old.unlink()
        if f.exists():
            continue
        bim = pd.read_csv(PLINK_DIR / ("1000G.EUR.QC.%d.bim" % chrom), sep=r"\s+", header=None,
                          names=["CHR", "SNP", "CM", "BP", "A1", "A2"])
        bp = bim["BP"].to_numpy()
        df = bim[["CHR", "BP", "SNP", "CM"]].copy()
        for k in keys:
            rows = [(sym2[g][1], sym2[g][2], sym2[g][3]) for g in all_sets[k]]
            iv = merged_intervals(rows, chrom)
            if len(iv) == 0:
                df[k] = 0
                continue
            idx = np.searchsorted(iv[:, 0], bp, side="right") - 1
            inside = (idx >= 0) & (bp <= iv[np.clip(idx, 0, None), 1])
            df[k] = inside.astype(np.int8)
        df.to_csv(f, sep="\t", index=False)
        df[keys].to_csv(LD_DIR / ("thin.%d.annot" % chrom), sep="\t", index=False)
    pass


def l2_cmd(c, snps, thin):
    pref = ("thin.%d.annot" if thin else "annot.%d.annot") % c
    cmd = NICE + [str(LDSC_PY), str(LDSC), "--l2", "--bfile", str(PLINK_DIR / ("1000G.EUR.QC.%d" % c)),
           "--ld-wind-cm", str(LD_WIND_CM), "--annot", str(LD_DIR / pref),
           "--out", str(LD_DIR / ("multi.%d" % c))]
    if thin:
        cmd.append("--thin-annot")
    return cmd


def frq_maf(c):
    f = next(iter(FRQ_DIR.rglob("1000G.EUR.QC.%d.frq" % c)), None)
    if f is None:
        raise FileNotFoundError("frq for chr%d" % c)
    fr = pd.read_csv(f, sep=r"\s+")
    return fr[["SNP", "MAF"]]


def write_M(c):
    mf = LD_DIR / ("multi.%d.l2.M" % c)
    m5 = LD_DIR / ("multi.%d.l2.M_5_50" % c)
    if mf.exists() and mf.stat().st_size > 0 and m5.exists() and m5.stat().st_size > 0:
        return
    an = pd.read_csv(LD_DIR / ("annot.%d.annot" % c), sep="\t")
    keys = [k for k in an.columns if k not in ("CHR", "BP", "SNP", "CM")]
    maf = frq_maf(c)
    if len(maf) == len(an) and (maf["SNP"].values == an["SNP"].values).all():
        common = maf["MAF"].values > 0.05
    else:
        mm = an[["SNP"]].merge(maf, on="SNP", how="left")
        common = mm["MAF"].fillna(0).values > 0.05
    M = an[keys].sum(axis=0).astype(int).tolist()
    M550 = an.loc[common, keys].sum(axis=0).astype(int).tolist()
    mf.write_text("\t".join(str(x) for x in M) + "\n")
    m5.write_text("\t".join(str(x) for x in M550) + "\n")


def check_M_against_baseline(c=22):
    base = prefix_of("baseline_v1.2")
    f = Path(str(base) + "%d.l2.M_5_50" % c) if base else None
    if not f or not f.exists():
        say("[M_CHECK] baseline M_5_50 not found")
        return
    ref_first = float(open(f).read().split()[0])
    n_common = int((frq_maf(c)["MAF"].values > 0.05).sum())
    if abs(n_common - ref_first) >= 0.5:
        say("[M_CHECK] chr%d SNPs with MAF>0.05: ours=%d baseline=%.0f DIFFERENT" % (c, n_common, ref_first))
    SUM["gates"]["M_CHECK"] = abs(n_common - ref_first) < 0.5


def run_l2():
    snps = LD_DIR / "print_snps.txt"
    if not snps.exists():
        with open(HM3_LIST) as f, open(snps, "w") as o:
            for line in f:
                t = line.split()
                if t and t[0].startswith("rs"):
                    o.write(t[0] + "\n")
    thin = False
    if not (LD_DIR / "multi.22.l2.ldscore.gz").exists():
        for thin in (False, True):
            t0 = time.time()
            rc, o, e = sh(l2_cmd(22, snps, thin), timeout=3 * 3600, env=L2_ENV)
            ok = (LD_DIR / "multi.22.l2.ldscore.gz").exists()
            if ok:
                break
            logf = LD_DIR / "multi.22.log"
            txt = (logf.read_text(errors="ignore") if logf.exists() else "") + "\n" + e
            for line in txt.strip().splitlines()[-25:]:
                say("       " + line[:220])
        if not (LD_DIR / "multi.22.l2.ldscore.gz").exists():
            SUM["gates"]["LDSCORES"] = False
            return False
    else:
        thin = (LD_DIR / "thin.mode").exists()
    if thin:
        (LD_DIR / "thin.mode").write_text("1")
    if (LD_DIR / "multi.22.l2.ldscore.gz").exists():
        write_M(22)
    check_M_against_baseline(22)
    todo = [c for c in range(1, 23) if not (LD_DIR / ("multi.%d.l2.ldscore.gz" % c)).exists()]
    n_todo = len(todo)
    running = []
    t0 = time.time()
    while todo or running:
        while todo and len(running) < N_WORKERS:
            c = todo.pop(0)
            errf = open(LD_DIR / ("multi.%d.stderr.txt" % c), "w")
            p = subprocess.Popen(l2_cmd(c, snps, thin), stdout=subprocess.DEVNULL, stderr=errf, text=True, env=L2_ENV)
            running.append((c, p, errf))
        time.sleep(5)
        still = []
        for c, p, errf in running:
            if p.poll() is None:
                still.append((c, p, errf))
                continue
            errf.close()
            ok = (LD_DIR / ("multi.%d.l2.ldscore.gz" % c)).exists()
            if ok:
                write_M(c)
            if not ok:
                say("    [L2] chr%-2d rc=%d FAILED %.0f min" % (c, p.returncode, (time.time() - t0) / 60))
                logf = LD_DIR / ("multi.%d.log" % c)
                txt = logf.read_text(errors="ignore") if logf.exists() else ""
                for line in txt.strip().splitlines()[-8:]:
                    say("       " + line[:200])
        running = still
    ok_all = all((LD_DIR / ("multi.%d.l2.ldscore.gz" % c)).exists() for c in range(1, 23))
    if ok_all:
        for c in range(1, 23):
            write_M(c)
    SUM["gates"]["LDSCORES_" + LD_DIR.name] = ok_all
    say("[L2] %s: %d chromosomes computed, all 22 present: %s (%.0f min)" % (LD_DIR.name, n_todo, ok_all, (time.time() - t0) / 60))
    return ok_all


def split_ldscores(keys):
    marker = LD_DIR / "split.done"
    if marker.exists():
        return
    hm3 = set(open(LD_DIR / "print_snps.txt").read().split())
    n_all = n_kept = 0
    for c in range(1, 23):
        ld = pd.read_csv(LD_DIR / ("multi.%d.l2.ldscore.gz" % c), sep="\t")
        n_all += len(ld)
        ld = ld[ld["SNP"].isin(hm3)].reset_index(drop=True)
        n_kept += len(ld)
        M = open(LD_DIR / ("multi.%d.l2.M" % c)).read().split()
        M550 = open(LD_DIR / ("multi.%d.l2.M_5_50" % c)).read().split()
        cols = [x for x in ld.columns if x not in ("CHR", "SNP", "BP")]
        if len(cols) != len(keys):
            raise RuntimeError("chr%d: %d LD columns vs %d keys" % (c, len(cols), len(keys)))
        for j, k in enumerate(keys):
            d = LD_DIR / "sets" / k
            d.mkdir(parents=True, exist_ok=True)
            out = ld[["CHR", "SNP", "BP", cols[j]]].rename(columns={cols[j]: k + "L2"})
            out.to_csv(d / ("%s.%d.l2.ldscore.gz" % (k, c)), sep="\t", index=False, compression="gzip")
            open(d / ("%s.%d.l2.M" % (k, c)), "w").write(M[j] + "\n")
            open(d / ("%s.%d.l2.M_5_50" % (k, c)), "w").write(M550[j] + "\n")
    marker.write_text("ok")



def prefix_of(dirname):
    d = REF / dirname
    for p in sorted(d.rglob("*.l2.ldscore.gz")) if d.exists() else []:
        m = re.match(r"^(.*\.)1\.l2\.ldscore\.gz$", p.name)
        if m:
            return str(p.parent / m.group(1))
    return None


def ldsc_seg(trait, fam):
    out = OUT.parent / "cache" / ("%s__%s" % (trait, fam["family"]))
    out.parent.mkdir(parents=True, exist_ok=True)
    res = Path(str(out) + ".cell_type_results.txt")
    if not res.exists():
        ldcts = LD_DIR / ("%s.ldcts" % fam["family"])
        ctrl = str(LD_DIR / "sets" / fam["control"] / (fam["control"] + "."))
        with open(ldcts, "w") as f:
            for k in fam["sets"]:
                if k == fam["control"]:
                    continue
                f.write("%s\t%s,%s\n" % (k, str(LD_DIR / "sets" / k / (k + ".")), ctrl))
        cmd = NICE + [str(LDSC_PY), str(LDSC), "--h2-cts", str(MUNGED / (trait + ".sumstats.gz")),
               "--ref-ld-chr", BASELINE, "--ref-ld-chr-cts", str(ldcts), "--w-ld-chr", WEIGHTS, "--out", str(out)]
        t0 = time.time()
        rc, o, e = sh(cmd, timeout=6 * 3600, env=L2_ENV)
        if rc != 0 or not res.exists():
            say("    [SEG] %-16s %-22s rc=%d FAILED %.0f min" % (trait, fam["family"], rc, (time.time() - t0) / 60))
            say("       " + (o + e).strip()[-400:])
            return None
    df = pd.read_csv(res, sep="\t")
    lab = fam["manifest"].set_index("set_key")["label"]
    df["label"] = df["Name"].map(lab)
    df["family"] = fam["family"]
    df["trait"] = trait
    df["q_bh"] = bh(df["Coefficient_P_value"].values)
    return df.sort_values("Coefficient_P_value")


# ----------------------------------------------------------------------------
# Helpers
# ----------------------------------------------------------------------------
VASC_LABELS = ["Arterial", "Venous", "ePV_1a", "ePV_1b", "ePV_2", "mPV", "uSMCs"]
TRAITS_K = ["KOLLER_EUR", "GCST90205183", "ENDO_ALL"]


def short(label, n=22):
    s = str(label)
    s = s.replace("SOX9_functionalis_", "SOX9f_").replace("dStromal_", "dS_").replace("Glandular_secretory", "Gland_sec")
    return s[:n]


def load_fam(mode, man):
    keys = list(man.loc[man["mode"] == mode, "set_key"]) + ["ALLGENES"]
    d, fname = (V030_LD, "KOLLER_ABS") if mode == "ABS" else (LD_BASE / ("P_" + mode), "K31_P_" + mode)
    if not (d / "split.done").exists():
        say("[STOP] LD scores for %s not found (%s); run v031 first" % (mode, d))
        return None
    sub = man[man["set_key"].isin(keys)][["set_key", "label"]]
    sub = sub.assign(label=sub["label"] + "/" + sub["set_key"].str.split("_").str[1])
    return {"family": fname, "sets": keys, "control": "ALLGENES", "manifest": sub, "dir": d, "tag": "P_" + mode}


def pref(fam, n):
    return str(fam["dir"] / "sets" / n / (n + "."))


def marginal(trait, fam):
    global LD_DIR
    LD_DIR = fam["dir"]
    df = ldsc_seg(trait, fam)
    return {} if df is None else dict(zip(df["Name"], df["Coefficient_P_value"]))


def run_joint(trait, name, lines):
    out = OUT.parent / "cache" / ("%s__%s" % (trait, name))
    out.parent.mkdir(parents=True, exist_ok=True)
    res = Path(str(out) + ".cell_type_results.txt")
    if not res.exists():
        ldcts = LD_BASE / ("%s.ldcts" % name)
        ldcts.write_text("".join(l + "\n" for l in lines))
        cmd = NICE + [str(LDSC_PY), str(LDSC), "--h2-cts", str(MUNGED / (trait + ".sumstats.gz")), "--ref-ld-chr", BASELINE,
                      "--ref-ld-chr-cts", str(ldcts), "--w-ld-chr", WEIGHTS, "--out", str(out)]
        t0 = time.time()
        rc, o, e = sh(cmd, timeout=8 * 3600, env=L2_ENV)
        if rc != 0 or not res.exists():
            say("    [JOINT_FAIL] %s %s rc=%d %s" % (trait, name, rc, (o + e).strip()[-300:]))
            return None
        say("    [JOINT] %s %s: %d fits (%.0f min)" % (trait, name, len(lines), (time.time() - t0) / 60))
    C = pd.read_csv(res, sep="\t")
    return dict(zip(C["Name"], C["Coefficient_P_value"]))


def fp(x):
    return "NA" if x is None or not np.isfinite(x) else ("%.0e" % x if x < 0.001 else "%.3f" % x)


# ----------------------------------------------------------------------------
# K7 sign decomposition (UP | DOWN and DOWN | UP for each cell type and status)
# ----------------------------------------------------------------------------
def k7(man, fA, fU, fD):
    say("")
    say("-" * 72)
    say("[SECTION] K7 sign decomposition of the |log2FC| annotations (joint S-LDSC of a type's UP and DOWN sets)")
    key = {(r["mode"], r["status"], r["compartment"], r["label"]): r["set_key"] for _, r in man.iterrows()}
    types = []
    for _, r in man[man["mode"] == "ABS"].iterrows():
        ku, kd = key.get(("UP", r["status"], r["compartment"], r["label"])), key.get(("DOWN", r["status"], r["compartment"], r["label"]))
        if ku and kd:
            types.append((r["set_key"], ku, kd, "%s/%s" % (r["label"], r["status"])))
    lines = []
    for ka, ku, kd, lab in types:
        lines.append("%s__GIVEN__%s\t%s,%s,%s" % (ku, kd, pref(fU, ku), pref(fU, "ALLGENES"), pref(fD, kd)))
        lines.append("%s__GIVEN__%s\t%s,%s,%s" % (kd, ku, pref(fD, kd), pref(fU, "ALLGENES"), pref(fU, ku)))
    say("[K7] cell types with UP and DOWN sets: %d" % len(types))
    rows = []
    for t in TRAITS_K:
        cp = run_joint(t, "K7_SIGN", lines)
        if cp is None:
            continue
        mA, mU, mD = marginal(t, fA), marginal(t, fU), marginal(t, fD)
        for ka, ku, kd, lab in types:
            pa, pu, pd_ = mA.get(ka, np.nan), mU.get(ku, np.nan), mD.get(kd, np.nan)
            pud, pdu = cp.get("%s__GIVEN__%s" % (ku, kd), np.nan), cp.get("%s__GIVEN__%s" % (kd, ku), np.nan)
            if pa < 0.05:
                cls = {(True, False): "UP-carried", (False, True): "DOWN-carried", (True, True): "both", (False, False): "neither"}[(pud < 0.05, pdu < 0.05)]
            else:
                cls = "ABS not nominal"
            rows.append({"trait": t, "type": lab, "p_abs": pa, "p_up": pu, "p_down": pd_, "p_up_given_down": pud, "p_down_given_up": pdu, "class": cls})
        R = pd.DataFrame([r for r in rows if r["trait"] == t])
        E = R[R["class"] != "ABS not nominal"]
        cnt = E["class"].value_counts().to_dict()
        if t == "KOLLER_EUR":
            panel = R[R["type"].str.split("/").str[0].isin(VASC_LABELS) | R["type"].str.contains(FOCUS_RE)].sort_values("p_abs")
            for _, r in panel.iterrows():
                say("    %-22s ABS %-6s | UP %-6s (|DOWN %-6s) | DOWN %-6s (|UP %-6s) -> %s" % (
                    short(r["type"]), fp(r["p_abs"]), fp(r["p_up"]), fp(r["p_up_given_down"]), fp(r["p_down"]), fp(r["p_down_given_up"]), r["class"]))
        say("  [K7] %-12s ABS-nominal types %d: %s" % (t[:12], len(E), ", ".join("%s %d" % (k, v) for k, v in sorted(cnt.items())) or "-"))
        if t == "KOLLER_EUR":
            endo = E[E["type"].str.match(r"^(Venous|Arterial)/")]
            ds = E[E["type"].str.match(r"^dStromal")]
            c1 = bool(len(endo)) and bool((endo["class"] == "DOWN-carried").all())
            c2 = bool(len(ds)) and bool((ds["class"] == "UP-carried").all())
            say("[H_SIGN_VERDICT] KOLLER_EUR: endothelial ABS signal DOWN-carried (%d/%d): %s | decidual-stroma ABS signal UP-carried (%d/%d): %s -> %s" % (
                int((endo["class"] == "DOWN-carried").sum()), len(endo), "YES" if c1 else "NO", int((ds["class"] == "UP-carried").sum()), len(ds),
                "YES" if c2 else "NO", "SUPPORTED" if (c1 and c2) else "NOT SUPPORTED"))
            SUM["results"]["h_sign"] = {"endothelial_down": c1, "dstromal_up": c2}
        SUM["results"]["k7_" + t] = cnt
    if rows:
        pd.DataFrame(rows).to_csv(OUT / "k7_sign_decomposition.csv", index=False)


# ----------------------------------------------------------------------------
# K8 decidual stroma (UP) vs vascular / perivascular / smooth muscle (UP)
# ----------------------------------------------------------------------------
def k8(man, fU):
    say("")
    say("-" * 72)
    say("[SECTION] K8 decidual stroma vs vascular, perivascular and smooth-muscle programs (UP sets, joint S-LDSC)")
    up = man[man["mode"] == "UP"]
    lab = dict(zip(up["set_key"], up["label"] + "/" + up["status"]))
    rows_ = [k for k in up["set_key"] if str(lab[k]).startswith("dStromal")]
    cols = [k for k in up["set_key"] if str(lab[k]).split("/")[0] in VASC_LABELS]
    if not rows_ or not cols:
        say("[K8] no decidual-stroma or vascular UP sets")
        return
    lines = []
    for a in rows_:
        for b in cols:
            lines.append("%s__GIVEN__%s\t%s,%s,%s" % (a, b, pref(fU, a), pref(fU, "ALLGENES"), pref(fU, b)))
            lines.append("%s__GIVEN__%s\t%s,%s,%s" % (b, a, pref(fU, b), pref(fU, "ALLGENES"), pref(fU, a)))
    say("[K8] rows %d decidual-stroma sets x columns %d vascular sets: %s" % (len(rows_), len(cols), ", ".join(short(lab[b], 14) for b in cols)))
    out = []
    for t in TRAITS_K:
        cp = run_joint(t, "K8_UPVASC", lines)
        if cp is None:
            continue
        m = marginal(t, fU)
        for a in rows_:
            for b in cols:
                out.append({"trait": t, "dstromal": lab[a], "other": lab[b], "p_ds": m.get(a, np.nan), "p_other": m.get(b, np.nan),
                            "p_ds_given_other": cp.get("%s__GIVEN__%s" % (a, b), np.nan), "p_other_given_ds": cp.get("%s__GIVEN__%s" % (b, a), np.nan)})
        O = pd.DataFrame([r for r in out if r["trait"] == t])
        say("  %s" % t)
        for a in rows_:
            g = O[O["dstromal"] == lab[a]]
            lost = g[g["p_ds_given_other"] >= 0.05]
            surv = g[(g["p_other"] < 0.05) & (g["p_other_given_ds"] < 0.05)]
            say("    %-16s p=%-6s survives %2d/%d | lost given: %s | vascular surviving it: %s" % (
                short(lab[a], 16), fp(m.get(a, np.nan)), int((g["p_ds_given_other"] < 0.05).sum()), len(g),
                ", ".join("%s %.2f" % (short(r["other"], 12), r["p_ds_given_other"]) for _, r in lost.iterrows()) or "none",
                ", ".join(short(r["other"], 12) for _, r in surv.iterrows()) or "none"))
        pv = O[O["dstromal"].str.startswith("dStromal_mid") & O["other"].str.startswith("ePV_2")]
        if len(pv):
            sep = bool((pv["p_ds_given_other"] < 0.05).all())
            say("  [K8_VERDICT] %s dStromal_mid given ePV_2 (UP): %s -> G4 prediction (not separable) %s" % (
                t, "; ".join("%s|%s %.3f" % (short(r["dstromal"], 12), short(r["other"], 10), r["p_ds_given_other"]) for _, r in pv.iterrows()),
                "NOT CONFIRMED (separable in S-LDSC UP)" if sep else "CONFIRMED"))
            SUM["results"]["k8_" + t] = {"dsmid_separable_from_epv2": sep}
        else:
            say("  [K8_VERDICT] %s: no dStromal_mid x ePV_2 pair" % t)
    if out:
        pd.DataFrame(out).to_csv(OUT / "k8_dstromal_vs_vascular_up.csv", index=False)


# ----------------------------------------------------------------------------
# Main
# ----------------------------------------------------------------------------
def step(name, fn, *a):
    try:
        return fn(*a)
    except Exception as e:
        import traceback
        say("[STEP_ERROR] %s %s: %s" % (name, type(e).__name__, str(e)[:300]))
        say(traceback.format_exc()[-1500:])
        return None


def main():
    global BASELINE, WEIGHTS
    say("=" * 72)
    say("PAPER 9 | v0.0.34 | Koller pipeline: sign decomposition and decidual stroma vs vascular | " + TS)
    say("=" * 72)
    t0 = time.time()
    BASELINE = prefix_of("baseline_v1.2")
    WEIGHTS = prefix_of("1000G_Phase3_weights_hm3_no_MHC")
    mf = GS_BASE / "P" / "manifest.csv"
    if not mf.exists():
        say("[STOP] v031 marker sets not found; run v031 first")
        return finish(t0)
    man = pd.read_csv(mf)
    fA, fU, fD = load_fam("ABS", man), load_fam("UP", man), load_fam("DOWN", man)
    if fA and fU and fD:
        step("K7", k7, man, fA, fU, fD)
    if fU:
        step("K8", k8, man, fU)
    finish(t0)


def finish(t0):
    with open(OUT / "p9_v034_summary.json", "w") as f:
        json.dump(SUM, f, indent=2, default=str)
    say("")
    say("[TIME] %.0f min" % ((time.time() - t0) / 60))
    say("[OUTPUT] " + str(OUT))
    say("[LOG] " + str(LOG))
    say("[POLICY] rules fixed in CHANGELOG v0.2.23 before this run")
    say("[DONE] PAPER9_V034_COMPLETE")
    _fh.close()


BASELINE = None
WEIGHTS = None

if __name__ == "__main__":
    main()
