def sh(cmd, cwd=None, timeout=None, env=None):
    try:
        p = subprocess.run([str(c) for c in cmd], cwd=cwd, capture_output=True, text=True, timeout=timeout, env=env)
        return p.returncode, p.stdout, p.stderr
    except FileNotFoundError as e:
        return 127, "", str(e)
    except OSError as e:
        return 126, "", str(e)
    except subprocess.TimeoutExpired:
        return 124, "", "timeout"


def safe(name):
    return re.sub(r"[^A-Za-z0-9]+", "_", name).strip("_")


def bh(p):
    p = np.asarray(p, dtype=float)
    n = len(p)
    order = np.argsort(p)
    ranked = p[order] * n / (np.arange(n) + 1)
    q = np.minimum.accumulate(ranked[::-1])[::-1]
    out = np.empty(n)
    out[order] = np.minimum(q, 1.0)
    return out


def dec(x):
    return x.decode() if isinstance(x, bytes) else str(x)


def obs_cat(f, name):
    obs = f["obs"]
    g = obs[name]
    if isinstance(g, h5py.Group) and "categories" in g:
        cats = np.array([dec(c) for c in g["categories"][:]], dtype=object)
        codes = g["codes"][:]
    elif "__categories" in obs and name in obs["__categories"]:
        cats = np.array([dec(c) for c in obs["__categories"][name][:]], dtype=object)
        codes = g[:]
    else:
        v = g[:]
        return np.array([dec(x) for x in v], dtype=object)
    out = np.empty(len(codes), dtype=object)
    ok = codes >= 0
    out[ok] = cats[codes[ok]]
    out[~ok] = None
    return out


def gene_map():
    sym2, dup = {}, set()
    for line in open(GENE_LOC_B37):
        t = line.split()
        if len(t) >= 6 and t[1] in [str(c) for c in range(1, 23)]:
            if t[5] in sym2:
                dup.add(t[5])
            sym2[t[5]] = (t[0], int(t[1]), int(t[2]), int(t[3]))
    for d in dup:
        sym2.pop(d, None)
    return sym2


# ----------------------------------------------------------------------------
# LDSC-SEG helpers reused verbatim from v012
# ----------------------------------------------------------------------------
def merged_intervals(gene_rows, chrom):
    iv = sorted((max(0, s - WINDOW_BP), e + WINDOW_BP) for c, s, e in gene_rows if c == chrom)
    out = []
    for s, e in iv:
        if out and s <= out[-1][1]:
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])
    return np.array(out, dtype=np.int64).reshape(-1, 2)


def write_annotations(all_sets, sym2):
    keys = list(all_sets.keys())
    pd.Series(keys).to_csv(LD_DIR / "columns.txt", index=False, header=False)
    for chrom in range(1, 23):
        f = LD_DIR / ("annot.%d.annot" % chrom)
        old = LD_DIR / ("annot.%d.annot.gz" % chrom)
        if old.exists():
            old.unlink()
        if f.exists():
            continue
        bim = pd.read_csv(PLINK_DIR / ("1000G.EUR.QC.%d.bim" % chrom), sep=r"\s+", header=None,
                          names=["CHR", "SNP", "CM", "BP", "A1", "A2"])
        bp = bim["BP"].to_numpy()
        df = bim[["CHR", "BP", "SNP", "CM"]].copy()
        for k in keys:
            rows = [(sym2[g][1], sym2[g][2], sym2[g][3]) for g in all_sets[k]]
            iv = merged_intervals(rows, chrom)
            if len(iv) == 0:
                df[k] = 0
                continue
            idx = np.searchsorted(iv[:, 0], bp, side="right") - 1
            inside = (idx >= 0) & (bp <= iv[np.clip(idx, 0, None), 1])
            df[k] = inside.astype(np.int8)
        df.to_csv(f, sep="\t", index=False)
        df[keys].to_csv(LD_DIR / ("thin.%d.annot" % chrom), sep="\t", index=False)
    pass


def l2_cmd(c, snps, thin):
    pref = ("thin.%d.annot" if thin else "annot.%d.annot") % c
    cmd = NICE + [str(LDSC_PY), str(LDSC), "--l2", "--bfile", str(PLINK_DIR / ("1000G.EUR.QC.%d" % c)),
           "--ld-wind-cm", str(LD_WIND_CM), "--annot", str(LD_DIR / pref),
           "--out", str(LD_DIR / ("multi.%d" % c))]
    if thin:
        cmd.append("--thin-annot")
    return cmd


def frq_maf(c):
    f = next(iter(FRQ_DIR.rglob("1000G.EUR.QC.%d.frq" % c)), None)
    if f is None:
        raise FileNotFoundError("frq for chr%d" % c)
    fr = pd.read_csv(f, sep=r"\s+")
    return fr[["SNP", "MAF"]]


def write_M(c):
    mf = LD_DIR / ("multi.%d.l2.M" % c)
    m5 = LD_DIR / ("multi.%d.l2.M_5_50" % c)
    if mf.exists() and mf.stat().st_size > 0 and m5.exists() and m5.stat().st_size > 0:
        return
    an = pd.read_csv(LD_DIR / ("annot.%d.annot" % c), sep="\t")
    keys = [k for k in an.columns if k not in ("CHR", "BP", "SNP", "CM")]
    maf = frq_maf(c)
    if len(maf) == len(an) and (maf["SNP"].values == an["SNP"].values).all():
        common = maf["MAF"].values > 0.05
    else:
        mm = an[["SNP"]].merge(maf, on="SNP", how="left")
        common = mm["MAF"].fillna(0).values > 0.05
    M = an[keys].sum(axis=0).astype(int).tolist()
    M550 = an.loc[common, keys].sum(axis=0).astype(int).tolist()
    mf.write_text("\t".join(str(x) for x in M) + "\n")
    m5.write_text("\t".join(str(x) for x in M550) + "\n")


def check_M_against_baseline(c=22):
    base = prefix_of("baseline_v1.2")
    f = Path(str(base) + "%d.l2.M_5_50" % c) if base else None
    if not f or not f.exists():
        say("[M_CHECK] baseline M_5_50 not found")
        return
    ref_first = float(open(f).read().split()[0])
    n_common = int((frq_maf(c)["MAF"].values > 0.05).sum())
    if abs(n_common - ref_first) >= 0.5:
        say("[M_CHECK] chr%d SNPs with MAF>0.05: ours=%d baseline=%.0f DIFFERENT" % (c, n_common, ref_first))
    SUM["gates"]["M_CHECK"] = abs(n_common - ref_first) < 0.5


def run_l2():
    snps = LD_DIR / "print_snps.txt"
    if not snps.exists():
        with open(HM3_LIST) as f, open(snps, "w") as o:
            for line in f:
                t = line.split()
                if t and t[0].startswith("rs"):
                    o.write(t[0] + "\n")
    thin = False
    if not (LD_DIR / "multi.22.l2.ldscore.gz").exists():
        for thin in (False, True):
            t0 = time.time()
            rc, o, e = sh(l2_cmd(22, snps, thin), timeout=3 * 3600, env=L2_ENV)
            ok = (LD_DIR / "multi.22.l2.ldscore.gz").exists()
            if ok:
                break
            logf = LD_DIR / "multi.22.log"
            txt = (logf.read_text(errors="ignore") if logf.exists() else "") + "\n" + e
            for line in txt.strip().splitlines()[-25:]:
                say("       " + line[:220])
        if not (LD_DIR / "multi.22.l2.ldscore.gz").exists():
            SUM["gates"]["LDSCORES"] = False
            return False
    else:
        thin = (LD_DIR / "thin.mode").exists()
    if thin:
        (LD_DIR / "thin.mode").write_text("1")
    if (LD_DIR / "multi.22.l2.ldscore.gz").exists():
        write_M(22)
    check_M_against_baseline(22)
    todo = [c for c in range(1, 23) if not (LD_DIR / ("multi.%d.l2.ldscore.gz" % c)).exists()]
    n_todo = len(todo)
    running = []
    t0 = time.time()
    while todo or running:
        while todo and len(running) < N_WORKERS:
            c = todo.pop(0)
            errf = open(LD_DIR / ("multi.%d.stderr.txt" % c), "w")
            p = subprocess.Popen(l2_cmd(c, snps, thin), stdout=subprocess.DEVNULL, stderr=errf, text=True, env=L2_ENV)
            running.append((c, p, errf))
        time.sleep(5)
        still = []
        for c, p, errf in running:
            if p.poll() is None:
                still.append((c, p, errf))
                continue
            errf.close()
            ok = (LD_DIR / ("multi.%d.l2.ldscore.gz" % c)).exists()
            if ok:
                write_M(c)
            if not ok:
                say("    [L2] chr%-2d rc=%d FAILED %.0f min" % (c, p.returncode, (time.time() - t0) / 60))
                logf = LD_DIR / ("multi.%d.log" % c)
                txt = logf.read_text(errors="ignore") if logf.exists() else ""
                for line in txt.strip().splitlines()[-8:]:
                    say("       " + line[:200])
        running = still
    ok_all = all((LD_DIR / ("multi.%d.l2.ldscore.gz" % c)).exists() for c in range(1, 23))
    if ok_all:
        for c in range(1, 23):
            write_M(c)
    SUM["gates"]["LDSCORES_" + LD_DIR.name] = ok_all
    say("[L2] %s: %d chromosomes computed, all 22 present: %s (%.0f min)" % (LD_DIR.name, n_todo, ok_all, (time.time() - t0) / 60))
    return ok_all


def split_ldscores(keys):
    marker = LD_DIR / "split.done"
    if marker.exists():
        return
    hm3 = set(open(LD_DIR / "print_snps.txt").read().split())
    n_all = n_kept = 0
    for c in range(1, 23):
        ld = pd.read_csv(LD_DIR / ("multi.%d.l2.ldscore.gz" % c), sep="\t")
        n_all += len(ld)
        ld = ld[ld["SNP"].isin(hm3)].reset_index(drop=True)
        n_kept += len(ld)
        M = open(LD_DIR / ("multi.%d.l2.M" % c)).read().split()
        M550 = open(LD_DIR / ("multi.%d.l2.M_5_50" % c)).read().split()
        cols = [x for x in ld.columns if x not in ("CHR", "SNP", "BP")]
        if len(cols) != len(keys):
            raise RuntimeError("chr%d: %d LD columns vs %d keys" % (c, len(cols), len(keys)))
        for j, k in enumerate(keys):
            d = LD_DIR / "sets" / k
            d.mkdir(parents=True, exist_ok=True)
            out = ld[["CHR", "SNP", "BP", cols[j]]].rename(columns={cols[j]: k + "L2"})
            out.to_csv(d / ("%s.%d.l2.ldscore.gz" % (k, c)), sep="\t", index=False, compression="gzip")
            open(d / ("%s.%d.l2.M" % (k, c)), "w").write(M[j] + "\n")
            open(d / ("%s.%d.l2.M_5_50" % (k, c)), "w").write(M550[j] + "\n")
    marker.write_text("ok")



def prefix_of(dirname):
    d = REF / dirname
    for p in sorted(d.rglob("*.l2.ldscore.gz")) if d.exists() else []:
        m = re.match(r"^(.*\.)1\.l2\.ldscore\.gz$", p.name)
        if m:
            return str(p.parent / m.group(1))
    return None


def ldsc_seg(trait, fam):
    out = OUT.parent / "cache" / ("%s__%s" % (trait, fam["family"]))
    out.parent.mkdir(parents=True, exist_ok=True)
    res = Path(str(out) + ".cell_type_results.txt")
    if not res.exists():
        ldcts = LD_DIR / ("%s.ldcts" % fam["family"])
        ctrl = str(LD_DIR / "sets" / fam["control"] / (fam["control"] + "."))
        with open(ldcts, "w") as f:
            for k in fam["sets"]:
                if k == fam["control"]:
                    continue
                f.write("%s\t%s,%s\n" % (k, str(LD_DIR / "sets" / k / (k + ".")), ctrl))
        cmd = NICE + [str(LDSC_PY), str(LDSC), "--h2-cts", str(MUNGED / (trait + ".sumstats.gz")),
               "--ref-ld-chr", BASELINE, "--ref-ld-chr-cts", str(ldcts), "--w-ld-chr", WEIGHTS, "--out", str(out)]
        t0 = time.time()
        rc, o, e = sh(cmd, timeout=6 * 3600, env=L2_ENV)
        if rc != 0 or not res.exists():
            say("    [SEG] %-16s %-22s rc=%d FAILED %.0f min" % (trait, fam["family"], rc, (time.time() - t0) / 60))
            say("       " + (o + e).strip()[-400:])
            return None
    df = pd.read_csv(res, sep="\t")
    lab = fam["manifest"].set_index("set_key")["label"]
    df["label"] = df["Name"].map(lab)
    df["family"] = fam["family"]
    df["trait"] = trait
    df["q_bh"] = bh(df["Coefficient_P_value"].values)
    return df.sort_values("Coefficient_P_value")


# ----------------------------------------------------------------------------
# Fixed (CHANGELOG v0.2.26)
# ----------------------------------------------------------------------------
HECA_GS = PROC / "genesets" / "heca_v014"
WORK = INTERIM / "magma_v037"
WORK.mkdir(parents=True, exist_ok=True)
OBS_BETA_DSMID = 0.947      # KOLLER_EUR dStromal_mid beta (v024 base model), as in R4 (v027)
SIM_SEED = 20261107
N_SIM = 60
# scenario: (name, strength label, [(profile, strength), ...]); PAR = summed specificity over stromal + epithelial types
SCENARIOS = [("null", 0.0, []), ("PAR", 2.0, [("PAR", 2.0)]), ("PAR", 4.0, [("PAR", 4.0)]),
             ("PAR+dS_mid", 2.0, [("PAR", 2.0), ("dStromal_mid", 2.0)])]
PAR_RE = r"Stromal|Fibroblast|SOX9|Lumin|Gland|MUC5B|KRT5|iliated|HOXA13"
STROMAL_RE = r"^(dStromal|eStromal|Fibroblast)"
VASC = ["Arterial", "Venous", "ePV_1a", "ePV_1b", "ePV_2", "mPV", "uSMCs"]
ENDOTH = ["Arterial", "Venous"]


def group_of(label):
    b = str(label).split("/")[0]
    if b.startswith("dStromal"):
        return "dStromal"
    if b in ENDOTH:
        return "endothelial"
    if b in VASC:
        return "perivascular/SM"
    return "other"


def read_raw(trait):
    raw = MAGMA_OUT / (trait + "_35_10.genes.raw")
    lines = raw.read_text().splitlines()
    out = pd.read_csv(MAGMA_OUT / (trait + "_35_10.genes.out"), sep=r"\s+")
    zmap = dict(zip(out["GENE"].astype(str), out["ZSTAT"]))
    data_idx = [i for i, l in enumerate(lines) if l.strip() and not l.startswith("#")]
    votes = {}
    for i in data_idx[:300]:
        tok = lines[i].split()
        z = zmap.get(tok[0])
        if z is None:
            continue
        for j in range(1, min(len(tok), 12)):
            try:
                if abs(float(tok[j]) - z) < 1e-3:
                    votes[j] = votes.get(j, 0) + 1
            except ValueError:
                pass
    zi = max(votes, key=votes.get)
    genes = [lines[i].split()[0] for i in data_idx]
    z = np.array([float(lines[i].split()[zi]) for i in data_idx])
    return lines, data_idx, zi, genes, z


def write_raw(lines, data_idx, zi, znew, path):
    out = list(lines)
    for k, i in enumerate(data_idx):
        t2 = out[i].split()
        t2[zi] = "%.6g" % znew[k]
        out[i] = " ".join(t2)
    Path(path).write_text("\n".join(out) + "\n")


def magma_sets_run(raw, sf, tag):
    outp = WORK / tag
    gsa = Path(str(outp) + ".gsa.out")
    for model in (["--model", "condition-hide=ALLGENES"], []):
        if gsa.exists():
            gsa.unlink()
        rc, o, e = sh(NICE + [MAGMA, "--gene-results", raw, "--set-annot", sf] + model + ["--out", outp], timeout=3600, env=L2_ENV)
        if gsa.exists():
            break
    if not gsa.exists():
        say("    [MAGMA_FAIL] %s %s" % (tag, (o + e).strip()[-200:]))
        return None
    rows = [l for l in open(gsa) if not l.startswith("#") and l.strip()]
    hdr = rows[0].split()
    res = {}
    for l in rows[1:]:
        d = dict(zip(hdr, l.split()))
        try:
            res[d.get("FULL_NAME", d.get("VARIABLE"))] = float(d["P"])
        except (KeyError, ValueError):
            continue
    return res


def summarize(res, man):
    out = {}
    for mode in ("ABS", "UP", "DOWN"):
        m = man[man["mode"] == mode]
        keys = [k for k in m["set_key"] if k in res]
        if not keys:
            continue
        lab = dict(zip(m["set_key"], m["label"] + "/" + m["status"]))
        p = np.array([res[k] for k in keys])
        q = bh(p)
        o = np.argsort(p)
        top = lab[keys[o[0]]]
        g = np.array([group_of(lab[k]) for k in keys])
        out[mode] = {"top": top, "top_group": group_of(top), "any_q05": bool((q < 0.05).any()),
                     "endo_q05": bool(((q < 0.05) & (g == "endothelial")).any()), "ds_q05": bool(((q < 0.05) & (g == "dStromal")).any()),
                     "best_ds_rank": int(np.where(g[o] == "dStromal")[0][0]) + 1 if (g == "dStromal").any() else -1,
                     "best_endo_rank": int(np.where(g[o] == "endothelial")[0][0]) + 1 if (g == "endothelial").any() else -1}
    return out


def simulate(man, sets, sym2):
    say("")
    say("-" * 72)
    say("[SECTION] S-ABS rotation design (MAGMA gene-set analysis, condition-hide=ALLGENES; real KOLLER_EUR z, annotation layer rotated)")
    S = pd.read_csv(HECA_GS / "specificity_by_type.csv.gz", index_col=0)
    lines, data_idx, zi, genes, z0 = read_raw("KOLLER_EUR")
    n = len(genes)
    idx_of = {g: i for i, g in enumerate(genes)}
    ent = {sym2[g][0]: g for g in S.index if g in sym2}
    sym_of = np.array([ent.get(g) for g in genes], dtype=object)
    has = np.array([s is not None for s in sym_of])
    b_std = OBS_BETA_DSMID * float(S["dStromal_mid"].std())
    keys = list(man["set_key"])
    set_idx = {k: np.array(sorted({idx_of[sym2[x][0]] for x in sets[k] if x in sym2 and sym2[x][0] in idx_of}), dtype=int) for k in keys}
    say("[SIM] genes.raw %d genes (Z column %d); HECA profiles for %d genes; effect per SD of profile x1 = %.4f" % (n, zi, int(has.sum()), b_std))
    sf = WORK / "sets_rot.txt"
    simraw = WORK / "SIM_35_10.genes.raw"
    realraw = MAGMA_OUT / "KOLLER_EUR_35_10.genes.raw"

    def write_sets(off):
        with open(sf, "w") as o:
            for k in keys:
                ii = (set_idx[k] + off) % n
                o.write(k + " " + " ".join(genes[i] for i in ii) + "\n")

    write_sets(0)
    obs = magma_sets_run(realraw, sf, "observed")
    if obs:
        so = summarize(obs, man)
        say("[SIM] observed KOLLER_EUR (no rotation): " + " | ".join("%s top %s" % (m, short(v["top"])) for m, v in so.items()))
    rng = np.random.default_rng(SIM_SEED)
    rows = []
    t0 = time.time()
    par_cols = [c for c in S.columns if re.search(PAR_RE, c) and c not in ("Arterial", "Venous")]
    say("[SIM] PAR profile = sum of specificity over %d types: %s" % (len(par_cols), ", ".join(par_cols)))

    def std_profile(target):
        prof = np.zeros(n)
        if target == "PAR":
            v = S.loc[list(sym_of[has]), par_cols].sum(axis=1).to_numpy(dtype=float)
        else:
            v = S.loc[list(sym_of[has]), target].to_numpy(dtype=float)
        prof[has] = (v - v.mean()) / v.std()
        return prof

    for name, strength, comps in SCENARIOS:
        if any(c != "PAR" and c not in S.columns for c, _ in comps) or (any(c == "PAR" for c, _ in comps) and not par_cols):
            say("[SIM] %s: profile not available; skipped" % name)
            continue
        prof = None
        for c, st in comps:
            p_ = st * b_std * std_profile(c)
            prof = p_ if prof is None else prof + p_
        for rep in range(N_SIM):
            off = int(rng.integers(500, n - 500))
            write_sets(off)
            if prof is None:
                raw = realraw
            else:
                write_raw(lines, data_idx, zi, z0 + np.roll(prof, off), simraw)
                raw = simraw
            res = magma_sets_run(raw, sf, "sim")
            if not res:
                continue
            for mode, v in summarize(res, man).items():
                rows.append({"truth": name, "strength": strength, "rep": rep, "offset": off, "mode": mode, **v})
        say("    [SIM] truth %-12s x%.0f done (%.0f min)" % (name, strength, (time.time() - t0) / 60))
    R = pd.DataFrame(rows)
    R.to_csv(OUT / "s_abs_parenchymal.csv", index=False)
    say("")
    say("[SIM_SUM] share of replicates: top set group (dStromal / endothelial / perivascular+SM / other) | any q<0.05 | endothelial q<0.05 | dStromal q<0.05")
    for (name, strength), g0 in R.groupby(["truth", "strength"], sort=False):
        for mode in ("ABS", "UP", "DOWN"):
            g = g0[g0["mode"] == mode]
            if not len(g):
                continue
            sh_ = g["top_group"].value_counts(normalize=True)
            fq = g["top"].value_counts(normalize=True).head(3)
            say("    truth %-12s x%.0f %-4s n=%-3d top: dS %.2f endo %.2f pv/SM %.2f other %.2f | anyq %.2f endoq %.2f dSq %.2f | rank dS %d endo %d | most often: %s" % (
                name, strength, mode, len(g), sh_.get("dStromal", 0), sh_.get("endothelial", 0), sh_.get("perivascular/SM", 0), sh_.get("other", 0),
                g["any_q05"].mean(), g["endo_q05"].mean(), g["ds_q05"].mean(), int(g["best_ds_rank"].median()), int(g["best_endo_rank"].median()),
                ", ".join("%s %.2f" % (short(k, 16), v) for k, v in fq.items())))

    def share(name, strength, mode, col, val=None):
        g = R[(R["truth"] == name) & (R["strength"] == strength) & (R["mode"] == mode)]
        if not len(g):
            return np.nan
        return float((g[col] == val).mean()) if val is not None else float(g[col].mean())
    calib = {m: share("null", 0.0, m, "any_q05") for m in ("ABS", "UP", "DOWN")}
    e2, e4, e0 = share("PAR", 2.0, "ABS", "top_group", "endothelial"), share("PAR", 4.0, "ABS", "top_group", "endothelial"), share("null", 0.0, "ABS", "top_group", "endothelial")
    say("[H_PAR_VERDICT] null any q<0.05: ABS %.2f, UP %.2f, DOWN %.2f | ABS top endothelial: null %.2f, PAR x2 %.2f, PAR x4 %.2f -> H-PAR (x2 >= null + 0.10): %s" % (
        calib["ABS"], calib["UP"], calib["DOWN"], e0, e2, e4, "SUPPORTED" if (e2 - e0 >= 0.10) else "NOT SUPPORTED"))
    # signature of the observed data: ABS top endothelial and UP top stromal
    W = R.pivot_table(index=["truth", "strength", "rep"], columns="mode", values="top", aggfunc="first").reset_index()
    W["sig"] = W["ABS"].map(lambda x: group_of(x) == "endothelial") & W["UP"].map(lambda x: bool(re.match(STROMAL_RE, str(x))))
    say("[SIGNATURE] share of replicates with ABS top endothelial AND UP top stromal (observed KOLLER pattern): " + "; ".join(
        "%s x%.0f %.2f" % (a, b, g["sig"].mean()) for (a, b), g in W.groupby(["truth", "strength"], sort=False)))
    SUM["results"]["h_par"] = {"null_anyq": calib, "abs_endo_top": {"null": e0, "x2": e2, "x4": e4},
                               "signature": {"%s_x%.0f" % k: float(g["sig"].mean()) for k, g in W.groupby(["truth", "strength"])}}


def short(label, n=22):
    s = str(label)
    s = s.replace("SOX9_functionalis_", "SOX9f_").replace("dStromal_", "dS_").replace("Glandular_secretory", "Gland_sec")
    return s[:n]


def main():
    say("=" * 72)
    say("PAPER 9 | v0.0.37 | simulation, rotation design: parenchymal source vs |log2FC| marker sets | " + TS)
    say("=" * 72)
    t0 = time.time()
    mf = GS_BASE / "P" / "manifest.csv"
    if not mf.exists():
        say("[STOP] v031 marker sets not found; run v031 first")
    else:
        man = pd.read_csv(mf)
        sets = {k: open(GS_BASE / "P" / (k + ".txt")).read().split() for k in man["set_key"]}
        try:
            simulate(man, sets, gene_map())
        except Exception as e:
            import traceback
            say("[STEP_ERROR] %s: %s" % (type(e).__name__, str(e)[:300]))
            say(traceback.format_exc()[-1500:])
    with open(OUT / "p9_v037_summary.json", "w") as f:
        json.dump(SUM, f, indent=2, default=str)
    say("")
    say("[TIME] %.0f min" % ((time.time() - t0) / 60))
    say("[OUTPUT] " + str(OUT))
    say("[LOG] " + str(LOG))
    say("[POLICY] rules fixed in CHANGELOG v0.2.26 before this run")
    say("[DONE] PAPER9_V037_COMPLETE")
    _fh.close()


if __name__ == "__main__":
    main()
''',
    'scripts/p9_v038_figures.py': r'''#!/usr/bin/env python3
# Paper 9 | v0.0.38 | draft paper figures for the Koller-pipeline / marker-rule results (no new analysis):
#   F1 rule flip (S-LDSC |log2FC| vs up-only vs down-only), F2 sign decomposition, F3 joint resolution,
#   F4 known-source simulations (recovery and detection), F5 composition of |log2FC| sets.
# Reads the newest results of v031, v034, v036, v037; writes PNG (300 dpi) + PDF + source-data CSV per figure.
# Runs in ~/Desktop/paper9/.venv; a few seconds, no heavy computation.

import datetime as dt
import math
import re
from pathlib import Path

import numpy as np
import pandas as pd
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
from matplotlib.lines import Line2D
from matplotlib.patches import Patch

HOME = Path.home()
REPO = HOME / "Desktop" / "paper9"
RES = REPO / "results" / "koller_repro"
TS = dt.datetime.now(dt.timezone.utc).strftime("%Y%m%dT%H%M%SZ")
OUT = REPO / "results" / "paper_figures" / ("p9_v038_" + TS)
LOG = REPO / "logs" / ("p9_v038_figures_" + TS + ".log")
OUT.mkdir(parents=True, exist_ok=True)
LOG.parent.mkdir(parents=True, exist_ok=True)
_fh = open(LOG, "w", encoding="utf-8")

TRAIT = "KOLLER_EUR"
# Colors (validated: categorical slots 1-3 pass all-pairs CVD / normal-vision checks on the light surface;
# slot 3 is below 3:1 contrast, so every figure carries a legend and direct labels)
COL = {"dStromal": "#2a78d6", "endothelial": "#eb6834", "perivascular/SM": "#1baf7a", "other": "#a3a29c"}
INK, INK2, GRID = "#0b0b0b", "#52514e", "#e4e3df"
SEQ = ["#f4f8fd", "#cde2fb", "#9ec5f4", "#6da7ec", "#3987e5", "#256abf", "#184f95", "#0d366b"]
VASC = ["Arterial", "Venous", "ePV_1a", "ePV_1b", "ePV_2", "mPV", "uSMCs"]

plt.rcParams.update({"font.size": 8, "axes.titlesize": 9, "axes.labelsize": 8, "xtick.labelsize": 7, "ytick.labelsize": 7,
                     "axes.edgecolor": INK2, "axes.labelcolor": INK, "xtick.color": INK2, "ytick.color": INK2, "text.color": INK,
                     "axes.spines.top": False, "axes.spines.right": False, "axes.linewidth": 0.6, "legend.frameon": False,
                     "font.family": "DejaVu Sans", "pdf.fonttype": 42, "figure.facecolor": "white", "savefig.facecolor": "white"})


def say(msg=""):
    print(msg, flush=True)
    _fh.write(msg + "\n")
    _fh.flush()


def newest(pattern, fname):
    dirs = sorted(RES.glob(pattern))
    for d in reversed(dirs):
        if (d / fname).exists():
            return d / fname
    return None


def group_of(label):
    b = str(label).split("/")[0]
    if b.startswith("dStromal"):
        return "dStromal"
    if b in ("Arterial", "Venous"):
        return "endothelial"
    if b in VASC:
        return "perivascular/SM"
    return "other"


def short(label, n=24):
    s = str(label).replace("SOX9_functionalis_", "SOX9f_").replace("dStromal_", "dS_").replace("Glandular_secretory", "Gland_sec")
    return s[:n]


def nl10(p):
    return -np.log10(np.clip(np.asarray(p, dtype=float), 1e-300, 1))


def save(fig, name, data=None):
    for ext in ("png", "pdf"):
        fig.savefig(OUT / ("%s.%s" % (name, ext)), dpi=300, bbox_inches="tight")
    plt.close(fig)
    if data is not None:
        data.to_csv(OUT / ("%s_source_data.csv" % name), index=False)
    say("[FIG] %s" % name)


def legend_groups(ax, loc="lower right"):
    h = [Line2D([0], [0], marker="o", color="none", markerfacecolor=COL[g], markeredgecolor=COL[g], markersize=5, label=g) for g in COL]
    ax.legend(handles=h, loc=loc, fontsize=7, handletextpad=0.3)


# ----------------------------------------------------------------------------
# F1 rule flip
# ----------------------------------------------------------------------------
def f1():
    fams = {}
    for mode in ("ABS", "UP", "DOWN"):
        f = newest("p9_v031_*", "sldsc_P_%s.csv" % mode)
        if f is None:
            say("[F1] sldsc_P_%s.csv not found; skipped" % mode)
            return
        d = pd.read_csv(f)
        fams[mode] = d[d["trait"] == TRAIT]
    rows = []
    for mode, d in fams.items():
        d = d.copy()
        d["base"] = d["label"].astype(str).str.split("/").str[0]
        b = d.sort_values("Coefficient_P_value").groupby("base", as_index=False).first()
        for _, r in b.iterrows():
            rows.append({"mode": mode, "cell_type": r["base"], "best_status": str(r["label"]).split("/")[-1], "p": r["Coefficient_P_value"], "q_bh": r["q_bh"]})
    D = pd.DataFrame(rows)
    order = D[D["mode"] == "ABS"].sort_values("p")["cell_type"].tolist()
    order += [c for c in D["cell_type"].unique() if c not in order]
    n = len(order)
    fig, axes = plt.subplots(1, 3, figsize=(7.2, 0.16 * n + 1.2), sharey=True)
    titles = {"ABS": "|log2FC| > 1.2 (Koller rule)", "UP": "up-regulated only", "DOWN": "down-regulated only"}
    xmax = max(3.5, float(nl10(D["p"]).max()) * 1.08)
    for ax, mode in zip(axes, ("ABS", "UP", "DOWN")):
        d = D[D["mode"] == mode].set_index("cell_type").reindex(order)
        y = np.arange(n)[::-1]
        x = nl10(d["p"].values)
        g = [group_of(c) for c in order]
        ax.axvline(-math.log10(0.05), color=INK2, lw=0.6, ls=(0, (3, 3)), zorder=1)
        ax.hlines(y, 0, x, color=GRID, lw=1.0, zorder=1)
        for yi, xi, gi, qi in zip(y, x, g, d["q_bh"].values):
            filled = bool(qi < 0.05)
            ax.scatter([xi], [yi], s=22, color=COL[gi] if filled else "white", edgecolor=COL[gi], linewidth=1.2, zorder=3)
        ax.set_title(titles[mode], loc="left", color=INK)
        ax.set_xlim(0, xmax)
        ax.set_xlabel("-log10 p (S-LDSC, %s)" % TRAIT)
        ax.grid(axis="x", color=GRID, lw=0.5)
        ax.set_axisbelow(True)
    axes[0].set_yticks(np.arange(n)[::-1])
    axes[0].set_yticklabels([short(c) for c in order])
    h = [Line2D([0], [0], marker="o", color="none", markerfacecolor=COL[g], markeredgecolor=COL[g], markersize=5, label=g) for g in COL]
    h += [Line2D([0], [0], marker="o", color="none", markerfacecolor=INK2, markeredgecolor=INK2, markersize=5, label="BH q < 0.05"),
          Line2D([0], [0], marker="o", color="none", markerfacecolor="white", markeredgecolor=INK2, markersize=5, label="q >= 0.05"),
          Line2D([0], [0], color=INK2, lw=0.6, ls=(0, (3, 3)), label="p = 0.05")]
    fig.suptitle("The prioritized cell type depends on the marker-gene selection rule (HECA, Koller pipeline; best status per type)", x=0.01, ha="left", fontsize=9)
    fig.tight_layout(rect=(0, 0.06, 1, 1))
    fig.legend(handles=h, loc="lower center", ncol=7, fontsize=7, handletextpad=0.3, columnspacing=1.2, bbox_to_anchor=(0.5, 0.0))
    save(fig, "F1_rule_flip", D)


# ----------------------------------------------------------------------------
# F2 sign decomposition
# ----------------------------------------------------------------------------
def f2():
    f = newest("p9_v034_*", "k7_sign_decomposition.csv")
    if f is None:
        say("[F2] k7 file not found; skipped")
        return
    d = pd.read_csv(f)
    d = d[(d["trait"] == TRAIT) & (d["class"] != "ABS not nominal")].copy()
    if not len(d):
        say("[F2] no ABS-nominal types; skipped")
        return
    d["x"] = nl10(d["p_up_given_down"])
    d["y"] = nl10(d["p_down_given_up"])
    d["group"] = d["type"].map(group_of)
    t = -math.log10(0.05)
    fig, ax = plt.subplots(figsize=(4.4, 4.0))
    lim = max(3.2, float(max(d["x"].max(), d["y"].max())) * 1.1)
    ax.axvline(t, color=INK2, lw=0.6, ls=(0, (3, 3)))
    ax.axhline(t, color=INK2, lw=0.6, ls=(0, (3, 3)))
    for gname, g in d.groupby("group"):
        ax.scatter(g["x"], g["y"], s=34, color=COL[gname], edgecolor="white", linewidth=0.8, zorder=3, label=gname)
    lab = d[(d["x"] > t) | (d["y"] > t)].sort_values("p_abs").head(12)
    for _, r in lab.iterrows():
        ax.annotate(short(r["type"], 18), (r["x"], r["y"]), xytext=(4, 2), textcoords="offset points", fontsize=6.3, color=INK2)
    ax.set_xlim(0, lim)
    ax.set_ylim(0, lim)
    ax.set_xlabel("-log10 p (UP set | DOWN set)")
    ax.set_ylabel("-log10 p (DOWN set | UP set)")
    cnt = d["class"].value_counts().to_dict()
    ax.set_title("%s: %d nominal |log2FC| annotations — %d down-carried, %d up-carried\nupper left: signal from genes depleted in the named type; lower right: from its up-regulated genes" % (
        TRAIT, len(d), cnt.get("DOWN-carried", 0), cnt.get("UP-carried", 0)), loc="left", fontsize=7.5)
    ax.legend(loc="upper right", fontsize=7, handletextpad=0.2)
    ax.grid(color=GRID, lw=0.5)
    ax.set_axisbelow(True)
    fig.tight_layout()
    save(fig, "F2_sign_decomposition", d)


# ----------------------------------------------------------------------------
# F3 joint resolution heatmaps
# ----------------------------------------------------------------------------
def heat(ax, M, title, rows, cols):
    from matplotlib.colors import LinearSegmentedColormap, BoundaryNorm
    cmap = LinearSegmentedColormap.from_list("seq", SEQ)
    bounds = [0, -math.log10(0.5), -math.log10(0.2), -math.log10(0.1), -math.log10(0.05), -math.log10(0.01), -math.log10(0.001), 6]
    norm = BoundaryNorm(bounds, cmap.N)
    im = ax.imshow(nl10(M), cmap=cmap, norm=norm, aspect="auto")
    for i in range(M.shape[0]):
        for j in range(M.shape[1]):
            v = M[i, j]
            if np.isfinite(v):
                txt = "<.001" if v < 0.001 else (("%.3f" % v)[1:] if v < 0.01 else ("%.2f" % v)[1:] if v < 1 else "1")
                ax.text(j, i, txt, ha="center", va="center", fontsize=5.4, color="white" if v < 0.01 else INK)
    ax.set_xticks(range(len(cols)))
    ax.set_xticklabels([short(c, 14) for c in cols], rotation=45, ha="right")
    ax.set_yticks(range(len(rows)))
    ax.set_yticklabels([short(r, 16) for r in rows])
    ax.set_title(title, loc="left", fontsize=8)
    for s in ax.spines.values():
        s.set_visible(False)
    ax.tick_params(length=0)
    return im


def f3():
    fa = newest("p9_v031_*", "k4_joint_P_ABS.csv")
    fu = newest("p9_v034_*", "k8_dstromal_vs_vascular_up.csv")
    if fa is None or fu is None:
        say("[F3] joint files not found; skipped")
        return
    A = pd.read_csv(fa)
    A = A[A["trait"] == TRAIT]
    U = pd.read_csv(fu)
    U = U[U["trait"] == TRAIT]
    ra, ca = list(dict.fromkeys(A["focus"])), list(dict.fromkeys(A["other"]))
    ru, cu = list(dict.fromkeys(U["dstromal"])), list(dict.fromkeys(U["other"]))
    pa1 = A.pivot(index="focus", columns="other", values="p_focus_given_other").reindex(index=ra, columns=ca).values
    pa2 = A.pivot(index="focus", columns="other", values="p_other_given_focus").reindex(index=ra, columns=ca).values
    pu1 = U.pivot(index="dstromal", columns="other", values="p_ds_given_other").reindex(index=ru, columns=cu).values
    pu2 = U.pivot(index="dstromal", columns="other", values="p_other_given_ds").reindex(index=ru, columns=cu).values
    fig, axes = plt.subplots(2, 2, figsize=(7.6, 6.4), layout="constrained",
                             gridspec_kw={"height_ratios": [len(ra), max(len(ru), 4)], "hspace": 0.12})
    im = heat(axes[0, 0], pa1, "a  |log2FC| sets: p(focus | other)", ra, ca)
    heat(axes[0, 1], pa2, "b  |log2FC| sets: p(other | focus)", ra, ca)
    heat(axes[1, 0], pu1, "c  up-only sets: p(decidual | vascular)", ru, cu)
    heat(axes[1, 1], pu2, "d  up-only sets: p(vascular | decidual)", ru, cu)
    for ax in (axes[0, 1], axes[1, 1]):
        ax.set_yticklabels([])
    pt = [0.5, 0.2, 0.1, 0.05, 0.01, 0.001]
    cb = fig.colorbar(im, ax=axes, shrink=0.5, pad=0.02, ticks=[-math.log10(x) for x in pt])
    cb.ax.set_yticklabels([str(x) for x in pt])
    cb.set_label("p (joint S-LDSC; darker = survives)")
    cb.outline.set_visible(False)
    fig.suptitle("%s joint S-LDSC: which annotation survives conditioning on the other" % TRAIT, x=0.01, ha="left", fontsize=9)
    src = pd.concat([A.assign(panel="ab"), U.rename(columns={"dstromal": "focus", "p_ds": "p_focus", "p_ds_given_other": "p_focus_given_other",
                                                             "p_other_given_ds": "p_other_given_focus"}).assign(panel="cd")], ignore_index=True)
    save(fig, "F3_joint_resolution", src)


# ----------------------------------------------------------------------------
# F4 known-source simulations
# ----------------------------------------------------------------------------
def f4():
    f36 = newest("p9_v036_*", "s_abs_rotation.csv")
    if f36 is None:
        say("[F4] v036 simulation file not found; skipped")
        return
    R = pd.read_csv(f36)
    truths = [("dStromal_mid", 2.0, "dStromal", "decidual stroma x2"), ("dStromal_mid", 4.0, "dStromal", "decidual stroma x4"),
              ("Venous", 2.0, "endothelial", "venous endothelium x2"), ("ePV_2", 2.0, "perivascular/SM", "perivascular ePV_2 x2")]
    rows = []
    for name, st, grp, lab in truths:
        for mode in ("ABS", "UP"):
            g = R[(R["truth"] == name) & (R["strength"] == st) & (R["mode"] == mode)]
            n0 = R[(R["truth"] == "null") & (R["mode"] == mode)]
            if not len(g):
                continue
            rows.append({"truth": lab, "group": grp, "rule": mode, "n": len(g), "top_correct": float((g["top_group"] == grp).mean()),
                         "top_correct_null": float((n0["top_group"] == grp).mean()) if len(n0) else np.nan,
                         "detected_any_q05": float(g["any_q05"].mean()), "detected_null": float(n0["any_q05"].mean()) if len(n0) else np.nan})
    D = pd.DataFrame(rows)
    if not len(D):
        say("[F4] no scenarios; skipped")
        return
    labs = list(dict.fromkeys(D["truth"]))
    fig, axes = plt.subplots(1, 2, figsize=(7.2, 2.9), sharey=True)
    w = 0.36
    for ax, col, ncol, title in ((axes[0], "top_correct", "top_correct_null", "a  true cell group ranked first"),
                                 (axes[1], "detected_any_q05", "detected_null", "b  any annotation BH q < 0.05")):
        for i, lab in enumerate(labs):
            for k, mode in enumerate(("ABS", "UP")):
                r = D[(D["truth"] == lab) & (D["rule"] == mode)]
                if not len(r):
                    continue
                r = r.iloc[0]
                x = i + (k - 0.5) * (w + 0.04)
                c = COL[r["group"]]
                ax.bar(x, r[col], width=w, color=c if mode == "UP" else "white", edgecolor=c, linewidth=1.2,
                       hatch=None if mode == "UP" else "////", zorder=2)
                ax.hlines(r[ncol], x - w / 2, x + w / 2, color=INK, lw=1.0, zorder=3)
                ax.text(x, r[col] + 0.02, "%.0f" % (100 * r[col]), ha="center", va="bottom", fontsize=6.3, color=INK2)
        ax.set_xticks(range(len(labs)))
        ax.set_xticklabels(labs, rotation=20, ha="right")
        ax.set_ylim(0, 1.08)
        ax.set_title(title, loc="left", fontsize=8)
        ax.grid(axis="y", color=GRID, lw=0.5)
        ax.set_axisbelow(True)
    axes[0].set_ylabel("share of 60 replicates")
    h = [Patch(facecolor="white", edgecolor=INK2, hatch="////", label="|log2FC| rule"), Patch(facecolor=INK2, edgecolor=INK2, label="up-only rule"),
         Line2D([0], [0], color=INK, lw=1.0, label="same quantity under the null")]
    axes[1].legend(handles=h, loc="upper right", fontsize=6.5)
    fig.suptitle("Known-source simulations (rotation design; real %s z-scores)" % TRAIT, x=0.01, ha="left", fontsize=9)
    fig.tight_layout()
    save(fig, "F4_simulation_recovery", D)


# ----------------------------------------------------------------------------
# F5 composition of |log2FC| sets
# ----------------------------------------------------------------------------
def f5():
    f = newest("p9_v031_*", "k2_abs_composition.csv")
    if f is None:
        say("[F5] composition file not found; skipped")
        return
    d = pd.read_csv(f)
    d["group"] = d["label"].map(group_of)
    d["pct"] = 100 * d["down_share"]
    order = d.groupby("label")["pct"].mean().sort_values().index.tolist()
    n = len(order)
    fig, ax = plt.subplots(figsize=(4.6, 0.17 * n + 1.3))
    ypos = {l: i for i, l in enumerate(order)}
    for status, mk in (("CTL", "o"), ("ENDO", "^")):
        s_ = d[d["status"] == status]
        for _, r in s_.iterrows():
            ax.scatter(r["pct"], ypos[r["label"]], marker=mk, s=26, color=COL[r["group"]], edgecolor="white", linewidth=0.6, zorder=3)
    for l in order:
        v = d.loc[d["label"] == l, "pct"]
        ax.hlines(ypos[l], v.min(), v.max(), color=GRID, lw=1.2, zorder=1)
    med = float(d["pct"].median())
    ax.axvline(50, color=INK2, lw=0.6, ls=(0, (3, 3)))
    ax.axvline(med, color=INK, lw=0.8)
    ax.text(med + 1, n - 0.4, "median %.0f%%" % med, fontsize=6.5, color=INK, va="top")
    ax.set_yticks(range(n))
    ax.set_yticklabels([short(l) for l in order])
    ax.set_xlim(0, 100)
    ax.set_ylim(-0.7, n - 0.3)
    ax.set_xlabel("% of genes in the |log2FC| set depleted in the named cell type")
    ax.set_title("|log2FC| marker sets are mostly depleted genes", loc="left", fontsize=8)
    ax.grid(axis="x", color=GRID, lw=0.5)
    ax.set_axisbelow(True)
    h = [Line2D([0], [0], marker="o", color="none", markerfacecolor=COL[g], markeredgecolor=COL[g], markersize=5, label=g) for g in COL]
    h += [Line2D([0], [0], marker="o", color="none", markerfacecolor=INK2, markersize=5, label="control donors"),
          Line2D([0], [0], marker="^", color="none", markerfacecolor=INK2, markersize=5, label="endometriosis donors")]
    fig.tight_layout(rect=(0, 0.1, 1, 1))
    fig.legend(handles=h, loc="lower center", ncol=3, fontsize=6.5, handletextpad=0.3, columnspacing=1.0, bbox_to_anchor=(0.5, 0.0))
    save(fig, "F5_abs_composition", d)


def main():
    say("=" * 72)
    say("PAPER 9 | v0.0.38 | draft figures (Koller pipeline, marker rules, simulations) | " + TS)
    say("=" * 72)
    for name, fn in (("F1", f1), ("F2", f2), ("F3", f3), ("F4", f4), ("F5", f5)):
        try:
            fn()
        except Exception as e:
            import traceback
            say("[FIG_ERROR] %s %s: %s" % (name, type(e).__name__, str(e)[:300]))
            say(traceback.format_exc()[-1200:])
    say("")
    say("[OUTPUT] " + str(OUT))
    say("[LOG] " + str(LOG))
    say("[DONE] PAPER9_V038_COMPLETE")
    _fh.close()


if __name__ == "__main__":
    main()
''',
    'scripts/p9_v039_locus_atlas.py': r'''#!/usr/bin/env python3
# Paper 9 | v0.0.39 | Locus atlas (rules CHANGELOG v0.2.28): where in the endometrium do individual endometriosis
#   risk loci act, and which loci drive the aggregate cell-type rankings?
#   L1 loci (distance clumping, p < 5e-8) and their candidate genes mapped to endometrial compartments (HECA);
#   L2 leave-one-locus-out influence on the MAGMA gene-set rankings (|log2FC|, up-only, down-only sets of v031);
#   L3 loci shared with leiomyoma / T2D / hypertension (descriptive).
# Runs in ~/Desktop/paper9/.venv, low-heat (MAGMA single thread, nice 10). ~20-40 min.

import os
os.environ.setdefault("OMP_NUM_THREADS", "1")
os.environ.setdefault("OPENBLAS_NUM_THREADS", "1")
os.environ.setdefault("VECLIB_MAXIMUM_THREADS", "1")
try:
    os.nice(10)
except Exception:
    pass

import datetime as dt
import json
import math
import re
import subprocess
import time
from pathlib import Path

import numpy as np
import pandas as pd

HOME = Path.home()
REPO = HOME / "Desktop" / "paper9"
INTERIM = REPO / "data" / "interim"
PROC = REPO / "data" / "processed"
TOOLS = REPO / "tools"
MAGMA = TOOLS / "magma" / "magma_bin"
GENE_LOC_B37 = TOOLS / "magma" / "genes_b37" / "NCBI37.3.gene.loc"
G1000_BIM = TOOLS / "magma" / "ref_eur" / "g1000_eur.bim"
MAGMA_OUT = INTERIM / "magma"
HECA_GS = PROC / "genesets" / "heca_v014"
GS_P = PROC / "genesets" / "heca_koller_v031" / "P"
TS = dt.datetime.now(dt.timezone.utc).strftime("%Y%m%dT%H%M%SZ")
OUT = REPO / "results" / "locus_atlas" / ("p9_v039_" + TS)
WORK = INTERIM / "magma_v039"
LOG = REPO / "logs" / ("p9_v039_locus_atlas_" + TS + ".log")
NICE = ["nice", "-n", "10"]
ENV1 = dict(os.environ, OPENBLAS_NUM_THREADS="1", OMP_NUM_THREADS="1", VECLIB_MAXIMUM_THREADS="1")

# Fixed (CHANGELOG v0.2.28)
GWS = 5e-8
CLUMP_BP = 500_000
GENE_WIN_BP = 250_000
DROP_WIN_BP = 500_000
PCT_ASSIGN = 0.90   # a gene is assigned to the compartment where its specificity share ranks highest across genes, if >= 90th percentile
SHARED_P = 1e-5
PRIMARY = "KOLLER_EUR"
TRAITS = ["KOLLER_EUR", "GCST90205183", "LEIOMYOMA", "HYPERTENSION", "T2D"]
SHARE_TRAITS = ["LEIOMYOMA", "T2D", "HYPERTENSION"]
COMPARTMENTS = [("stroma", r"Stromal|Fibroblast"),
                ("epithelium", r"SOX9|Lumin|Gland|MUC5B|KRT5|iliated|HOXA13"),
                ("endothelium", r"^(Arterial|Venous|Lymphatic)"),
                ("perivascular/SM", r"^(ePV|mPV|uSMC)"),
                ("immune", r"^(uM|uNK|NK|T_|T$|B_|B$|Mast|DC|cDC|pDC|Macro|Mono|Lymphoid|Myeloid|ILC|Plasma|Neutro|Immune|Treg)")]

for d in (OUT, WORK, LOG.parent):
    d.mkdir(parents=True, exist_ok=True)
_fh = open(LOG, "w", encoding="utf-8")
SUM = {"task": "PAPER9_V039_LOCUS_ATLAS", "timestamp_utc": TS, "results": {}}


def say(msg=""):
    print(msg, flush=True)
    _fh.write(msg + "\n")
    _fh.flush()


def sh(cmd, timeout=None):
    try:
        p = subprocess.run([str(c) for c in cmd], capture_output=True, text=True, timeout=timeout, env=ENV1)
        return p.returncode, p.stdout, p.stderr
    except subprocess.TimeoutExpired:
        return 124, "", "timeout"


def gene_loc():
    ent2sym, sym2ent, pos = {}, {}, {}
    dup = set()
    for line in open(GENE_LOC_B37):
        t = line.split()
        if len(t) >= 6 and t[1] in [str(c) for c in range(1, 23)]:
            ent2sym[t[0]] = t[5]
            pos[t[0]] = (int(t[1]), int(t[2]), int(t[3]))
            if t[5] in sym2ent:
                dup.add(t[5])
            sym2ent[t[5]] = t[0]
    for d in dup:
        sym2ent.pop(d, None)
    return ent2sym, sym2ent, pos


# ----------------------------------------------------------------------------
# L1 loci and compartments
# ----------------------------------------------------------------------------
def read_sig(trait, thr):
    f = MAGMA_OUT / (trait + ".pval.txt")
    if not f.exists():
        return None
    out = {}
    with open(f) as fh:
        hdr = fh.readline().split()
        ip = hdr.index("P") if "P" in hdr else 1
        for line in fh:
            t = line.split()
            try:
                p = float(t[ip])
            except (ValueError, IndexError):
                continue
            if p < thr:
                out[t[0]] = p
    return out


def bim_positions(wanted):
    pos = {}
    with open(G1000_BIM) as fh:
        for line in fh:
            t = line.split()
            if t[1] in wanted:
                pos[t[1]] = (int(t[0]), int(t[3]))
    return pos


def clump(sig, pos):
    rows = sorted([(p, s) for s, p in sig.items() if s in pos])
    leads, taken = [], {}
    for p, s in rows:
        c, b = pos[s]
        if any(abs(b - b2) <= CLUMP_BP for b2 in taken.get(c, [])):
            continue
        taken.setdefault(c, []).append(b)
        leads.append({"lead_snp": s, "chr": c, "bp": b, "p": p})
    return pd.DataFrame(leads)


def compartment_table(S):
    comp = {}
    for c in S.columns:
        g = next((name for name, rx in COMPARTMENTS if re.search(rx, c)), "other")
        comp[c] = g
    names = [n for n, _ in COMPARTMENTS] + ["other"]
    share = pd.DataFrame({n: S[[c for c in S.columns if comp[c] == n]].sum(axis=1) if any(comp[c] == n for c in S.columns) else 0.0
                          for n in names}, index=S.index)
    base = share.median(axis=0)
    ratio = share.rank(pct=True)
    for n in names:
        if not any(comp[c] == n for c in S.columns):
            ratio[n] = np.nan
    return comp, share, ratio, base


def assign(ratio_row):
    r = ratio_row.drop(labels=["other"], errors="ignore").dropna()
    if not len(r):
        return "no expression", np.nan
    best = r.idxmax()
    return (best if r[best] >= PCT_ASSIGN else "broad"), float(r[best])


def loci_for(trait, sig, pos, genes_out, ent2sym, ratio, S):
    L = clump(sig, pos)
    if not len(L):
        return L
    g = genes_out
    rows = []
    for _, r in L.iterrows():
        m = g[(g["CHR"] == r["chr"]) & (g["STOP"] >= r["bp"] - GENE_WIN_BP) & (g["START"] <= r["bp"] + GENE_WIN_BP)].sort_values("P")
        syms = [ent2sym.get(str(e), str(e)) for e in m["GENE"]]
        prio = syms[0] if syms else ""
        expr = [s for s in syms if s in ratio.index]
        comp, best_ratio = assign(ratio.loc[expr[0]]) if expr else ("no expression", np.nan)
        top_type = S.loc[expr[0]].idxmax() if expr else ""
        # sensitivity: top-3 expressed candidate genes, mean ratio
        if expr:
            rr = ratio.loc[expr[:3]].mean(axis=0)
            comp3, _ = assign(rr)
        else:
            comp3 = "no expression"
        rows.append({**r.to_dict(), "n_genes": len(syms), "prioritized_gene": prio, "gene_min_p": float(m["P"].iloc[0]) if len(m) else np.nan,
                     "top3_genes": ",".join(syms[:3]), "expressed_gene_used": expr[0] if expr else "", "compartment": comp,
                     "compartment_pct": best_ratio, "top_heca_type": top_type, "compartment_top3": comp3})
    D = pd.DataFrame(rows)
    D.insert(0, "trait", trait)
    return D


def l1(ent2sym, sym2ent):
    say("")
    say("-" * 72)
    say("[SECTION] L1 risk loci and endometrial compartments (HECA heca_v014 specificity)")
    S = pd.read_csv(HECA_GS / "specificity_by_type.csv.gz", index_col=0)
    comp, share, ratio, base = compartment_table(S)
    for n in [n for n, _ in COMPARTMENTS] + ["other"]:
        say("[COMP] %-15s %s" % (n, ", ".join(c for c in S.columns if comp[c] == n) or "-"))
    say("[COMP] median specificity share per compartment: " + "; ".join("%s %.3f" % (k, v) for k, v in base.items() if np.isfinite(v)))
    say("[COMP] assignment: compartment with the highest percentile of its share across genes, if >= %.0f%%; otherwise 'broad'" % (100 * PCT_ASSIGN))
    sigs = {}
    for t in TRAITS:
        s = read_sig(t, GWS)
        if s is None:
            say("[L1] %s: pval file missing; skipped" % t)
            continue
        sigs[t] = s
    wanted = set().union(*[set(s) for s in sigs.values()]) if sigs else set()
    t0 = time.time()
    pos = bim_positions(wanted)
    say("[L1] genome-wide significant SNPs: %s; positions found %d (%.1f min)" % (
        ", ".join("%s %d" % (t, len(s)) for t, s in sigs.items()), len(pos), (time.time() - t0) / 60))
    all_loci = []
    for t, s in sigs.items():
        go = MAGMA_OUT / (t + "_35_10.genes.out")
        if not go.exists():
            say("[L1] %s genes.out missing" % t)
            continue
        g = pd.read_csv(go, sep=r"\s+")
        D = loci_for(t, s, pos, g, ent2sym, ratio, S)
        if not len(D):
            say("[L1] %s: no loci" % t)
            continue
        all_loci.append(D)
        vc = D["compartment"].value_counts()
        a = D[~D["compartment"].isin(["broad", "no expression"])]
        sh_ = a["compartment"].value_counts(normalize=True)
        say("[L1] %-12s loci %3d | assigned %3d | %s | broad %d, no expr %d" % (
            t[:12], len(D), len(a), ", ".join("%s %d (%.0f%%)" % (k, vc[k], 100 * sh_.get(k, 0)) for k in sh_.index),
            int(vc.get("broad", 0)), int(vc.get("no expression", 0))))
    if not all_loci:
        return None, ratio, S
    A = pd.concat(all_loci, ignore_index=True)
    A.to_csv(OUT / "l1_loci_compartments.csv", index=False)
    k = A[A["trait"] == PRIMARY]
    if len(k):
        say("[L1] %s loci (lead p, prioritized gene -> compartment, top HECA type):" % PRIMARY)
        for _, r in k.sort_values("p").iterrows():
            say("    chr%-2d %11d %-12s p=%.1e  %-12s -> %-15s %-22s (top3: %s)" % (
                r["chr"], r["bp"], r["lead_snp"], r["p"], str(r["prioritized_gene"])[:12], r["compartment"], str(r["top_heca_type"])[:22],
                str(r["top3_genes"])[:40]))
        a = k[~k["compartment"].isin(["broad", "no expression"])]
        sh_ = a["compartment"].value_counts(normalize=True)
        # background: the same assignment applied to every expressed gene
        from scipy.stats import binomtest
        bg = pd.Series([assign(ratio.loc[g_])[0] for g_ in ratio.index])
        bgs = bg.value_counts(normalize=True)
        n_expr = int((k["compartment"] != "no expression").sum())
        parts = []
        for cn in [n for n, _ in COMPARTMENTS] + ["broad"]:
            obs = int((k["compartment"] == cn).sum())
            exp_ = float(bgs.get(cn, 0.0))
            pv = binomtest(obs, n_expr, exp_, alternative="greater").pvalue if (n_expr and exp_ > 0) else np.nan
            parts.append("%s %d/%d (genome %.0f%%, p %.3g)" % (cn, obs, n_expr, 100 * exp_, pv))
            SUM["results"].setdefault("l1_enrichment", {})[cn] = {"obs": obs, "n": n_expr, "genome_share": exp_, "p_greater": pv}
        say("[L1_ENRICH] %s loci vs all expressed genes: %s" % (PRIMARY, "; ".join(parts)))
        n_ge10 = int((sh_ >= 0.10).sum())
        top_share = float(sh_.max()) if len(sh_) else np.nan
        multi = (n_ge10 >= 3) and (top_share <= 0.5)
        lei = A[(A["trait"] == "LEIOMYOMA") & ~A["compartment"].isin(["broad", "no expression"])]
        lei_top = float(lei["compartment"].value_counts(normalize=True).max()) if len(lei) else np.nan
        say("[H_MULTI_VERDICT] %s assigned loci %d: compartments with >= 10%% share %d, top share %.2f -> %s | leiomyoma top share %s (more concentrated: %s)" % (
            PRIMARY, len(a), n_ge10, top_share, "SUPPORTED" if multi else "NOT SUPPORTED",
            "%.2f" % lei_top if np.isfinite(lei_top) else "NA", "NA" if not np.isfinite(lei_top) else ("YES" if lei_top > top_share else "NO")))
        SUM["results"]["h_multi"] = {"assigned": len(a), "n_ge10": n_ge10, "top_share": top_share, "supported": multi, "leiomyoma_top_share": lei_top}
    return A, ratio, S


# ----------------------------------------------------------------------------
# L2 leave-one-locus-out influence on MAGMA gene-set rankings
# ----------------------------------------------------------------------------
def magma_sets_run(raw, sf, tag):
    outp = WORK / tag
    gsa = Path(str(outp) + ".gsa.out")
    for model in (["--model", "condition-hide=ALLGENES"], []):
        if gsa.exists():
            gsa.unlink()
        rc, o, e = sh(NICE + [MAGMA, "--gene-results", raw, "--set-annot", sf] + model + ["--out", outp], timeout=3600)
        if gsa.exists():
            break
    if not gsa.exists():
        say("    [MAGMA_FAIL] %s %s" % (tag, (o + e).strip()[-200:]))
        return None
    rows = [l for l in open(gsa) if not l.startswith("#") and l.strip()]
    hdr = rows[0].split()
    res = {}
    for l in rows[1:]:
        d = dict(zip(hdr, l.split()))
        try:
            res[d.get("FULL_NAME", d.get("VARIABLE"))] = float(d["P"])
        except (KeyError, ValueError):
            continue
    return res


def l2(A, sym2ent, pos_gene):
    say("")
    say("-" * 72)
    say("[SECTION] L2 leave-one-locus-out: which %s loci drive the gene-set rankings (v031 marker sets)" % PRIMARY)
    mf = GS_P / "manifest.csv"
    raw = MAGMA_OUT / (PRIMARY + "_35_10.genes.raw")
    if not mf.exists() or not raw.exists() or A is None:
        say("[L2] inputs missing; skipped")
        return
    man = pd.read_csv(mf)
    lab = dict(zip(man["set_key"], man["label"] + "/" + man["status"]))
    mode = dict(zip(man["set_key"], man["mode"]))
    sets = {}
    for k in man["set_key"]:
        sets[k] = [sym2ent[s] for s in open(GS_P / (k + ".txt")).read().split() if s in sym2ent]

    def write_sets(drop, path):
        with open(path, "w") as o:
            for k, g in sets.items():
                keep = g if k == "ALLGENES" else [x for x in g if x not in drop]
                o.write(k + " " + " ".join(keep) + "\n")

    sf = WORK / "sets_base.txt"
    write_sets(set(), sf)
    base = magma_sets_run(raw, sf, "base")
    if not base:
        return
    tracked = []
    for m in ("ABS", "UP", "DOWN"):
        ks = sorted([k for k in base if mode.get(k) == m], key=lambda k: base[k])[:3]
        tracked += ks
        say("[L2] baseline %-4s top: %s" % (m, "; ".join("%s p=%.1e" % (lab[k], base[k]) for k in ks)))
    K = A[A["trait"] == PRIMARY].reset_index(drop=True)
    rows = []
    t0 = time.time()
    sfl = WORK / "sets_drop.txt"
    for i, r in K.iterrows():
        drop = {e for e, (c, s, en) in pos_gene.items() if c == r["chr"] and en >= r["bp"] - DROP_WIN_BP and s <= r["bp"] + DROP_WIN_BP}
        write_sets(drop, sfl)
        res = magma_sets_run(raw, sfl, "drop")
        if not res:
            continue
        for k in tracked:
            rows.append({"locus": r["lead_snp"], "chr": r["chr"], "bp": r["bp"], "gene": r["prioritized_gene"], "compartment": r["compartment"],
                         "set": lab[k], "mode": mode[k], "p_base": base[k], "p_drop": res.get(k, np.nan),
                         "delta_log10": -math.log10(base[k]) + math.log10(max(res.get(k, np.nan), 1e-300)) if np.isfinite(res.get(k, np.nan)) else np.nan,
                         "n_dropped_genes": len(drop)})
    say("[L2] %d loci x %d tracked sets (%.0f min)" % (len(K), len(tracked), (time.time() - t0) / 60))
    R = pd.DataFrame(rows)
    if not len(R):
        return
    R.to_csv(OUT / "l2_leave_one_locus_out.csv", index=False)
    drivers = {}
    for s_, g in R.groupby("set", sort=False):
        d = g[g["delta_log10"] >= 1.0].sort_values("delta_log10", ascending=False)
        drivers[s_] = d
        say("    [DRIVERS] %-24s %-4s p=%.1e | %d loci raise p >= 10x: %s" % (
            s_[:24], g["mode"].iloc[0], g["p_base"].iloc[0], len(d),
            "; ".join("%s (%s, %s) %.1e" % (r["gene"], r["compartment"], r["locus"], r["p_drop"]) for _, r in d.head(5).iterrows()) or "-"))
    # all drivers of a set removed together
    for s_, d in drivers.items():
        if not len(d):
            continue
        loci = K[K["lead_snp"].isin(d["locus"])]
        drop = set()
        for _, r in loci.iterrows():
            drop |= {e for e, (c, s, en) in pos_gene.items() if c == r["chr"] and en >= r["bp"] - DROP_WIN_BP and s <= r["bp"] + DROP_WIN_BP}
        write_sets(drop, sfl)
        res = magma_sets_run(raw, sfl, "drop_all")
        k = next(k for k in tracked if lab[k] == s_)
        if res:
            say("    [DRIVERS_ALL] %-24s without its %d driver loci: p=%.1e (base %.1e)" % (s_[:24], len(d), res.get(k, np.nan), base[k]))
    SUM["results"]["l2_drivers"] = {s_: list(d["gene"]) for s_, d in drivers.items()}


# ----------------------------------------------------------------------------
# L3 loci shared with other traits (descriptive)
# ----------------------------------------------------------------------------
def l3(A):
    say("")
    say("-" * 72)
    say("[SECTION] L3 %s loci shared with leiomyoma / T2D / hypertension (min p in lead +-%d kb < %.0e; descriptive)" % (
        PRIMARY, GENE_WIN_BP // 1000, SHARED_P))
    if A is None:
        return
    K = A[A["trait"] == PRIMARY].copy()
    if not len(K):
        return
    win = {}
    for _, r in K.iterrows():
        win.setdefault(r["chr"], []).append((r["bp"] - GENE_WIN_BP, r["bp"] + GENE_WIN_BP, r["lead_snp"]))
    snp_locus = {}
    t0 = time.time()
    with open(G1000_BIM) as fh:
        for line in fh:
            t = line.split()
            c = int(t[0]) if t[0].isdigit() else -1
            if c in win:
                b = int(t[3])
                for lo, hi, ls in win[c]:
                    if lo <= b <= hi:
                        snp_locus[t[1]] = ls
                        break
    say("[L3] reference SNPs in %d windows: %d (%.1f min)" % (len(K), len(snp_locus), (time.time() - t0) / 60))
    for tr in SHARE_TRAITS:
        f = MAGMA_OUT / (tr + ".pval.txt")
        if not f.exists():
            say("[L3] %s pval file missing" % tr)
            continue
        best = {}
        with open(f) as fh:
            hdr = fh.readline().split()
            ip = hdr.index("P") if "P" in hdr else 1
            for line in fh:
                t = line.split()
                ls = snp_locus.get(t[0])
                if ls is None:
                    continue
                try:
                    p = float(t[ip])
                except (ValueError, IndexError):
                    continue
                if p < best.get(ls, 1.0):
                    best[ls] = p
        K["minp_" + tr] = K["lead_snp"].map(best)
        K["shared_" + tr] = K["minp_" + tr] < SHARED_P
    cols = [c for c in K.columns if c.startswith("shared_")]
    if not cols:
        return
    K["shared_any"] = K[cols].any(axis=1)
    K.to_csv(OUT / "l3_shared_loci.csv", index=False)
    for c in cols + ["shared_any"]:
        g = K[K[c]]
        say("[L3] %-20s %2d loci: %s" % (c, len(g), ", ".join("%s(%s)" % (r["prioritized_gene"], r["compartment"][:5]) for _, r in g.iterrows())[:300] or "-"))
    for flag, g in K.groupby("shared_any"):
        a = g[~g["compartment"].isin(["broad", "no expression"])]
        say("[L3] %-9s loci %2d | assigned compartments: %s" % ("shared" if flag else "specific", len(g),
                                                               ", ".join("%s %d" % (k, v) for k, v in a["compartment"].value_counts().items()) or "-"))


def main():
    say("=" * 72)
    say("PAPER 9 | v0.0.39 | locus atlas: compartments of risk loci and drivers of cell-type rankings | " + TS)
    say("=" * 72)
    t0 = time.time()
    ent2sym, sym2ent, pos_gene = gene_loc()
    A = None
    for name, fn in (("L1", lambda: l1(ent2sym, sym2ent)), ("L2", None), ("L3", None)):
        try:
            if name == "L1":
                A = fn()[0]
            elif name == "L2":
                l2(A, sym2ent, pos_gene)
            else:
                l3(A)
        except Exception as e:
            import traceback
            say("[STEP_ERROR] %s %s: %s" % (name, type(e).__name__, str(e)[:300]))
            say(traceback.format_exc()[-1500:])
    with open(OUT / "p9_v039_summary.json", "w") as f:
        json.dump(SUM, f, indent=2, default=str)
    say("")
    say("[TIME] %.0f min" % ((time.time() - t0) / 60))
    say("[OUTPUT] " + str(OUT))
    say("[LOG] " + str(LOG))
    say("[POLICY] rules fixed in CHANGELOG v0.2.28 before this run")
    say("[DONE] PAPER9_V039_COMPLETE")
    _fh.close()


if __name__ == "__main__":
    main()
''',
    'scripts/p9_v040_locus_atlas.py': r'''#!/usr/bin/env python3
# Paper 9 | v0.0.40 | Locus atlas, corrected re-run (rules CHANGELOG v0.2.28 + v0.2.29): v039 matched no genes for
#   KOLLER / FinnGen traits (chromosome column of genes.out read as text because of chrX rows). Adds L2b (all
#   genome-wide loci removed at once), a random-window baseline for L3 sharing, and K1b (Koller cohort vs the
#   E-MTAB-14039 sample table).
#   L1 loci (distance clumping, p < 5e-8) and their candidate genes mapped to endometrial compartments (HECA);
#   L2 leave-one-locus-out influence on the MAGMA gene-set rankings (|log2FC|, up-only, down-only sets of v031);
#   L3 loci shared with leiomyoma / T2D / hypertension (descriptive).
# Runs in ~/Desktop/paper9/.venv, low-heat (MAGMA single thread, nice 10). ~20-40 min.

import os
os.environ.setdefault("OMP_NUM_THREADS", "1")
os.environ.setdefault("OPENBLAS_NUM_THREADS", "1")
os.environ.setdefault("VECLIB_MAXIMUM_THREADS", "1")
try:
    os.nice(10)
except Exception:
    pass

import datetime as dt
import json
import math
import re
import subprocess
import time
from pathlib import Path

import numpy as np
import pandas as pd

HOME = Path.home()
REPO = HOME / "Desktop" / "paper9"
INTERIM = REPO / "data" / "interim"
PROC = REPO / "data" / "processed"
TOOLS = REPO / "tools"
MAGMA = TOOLS / "magma" / "magma_bin"
GENE_LOC_B37 = TOOLS / "magma" / "genes_b37" / "NCBI37.3.gene.loc"
G1000_BIM = TOOLS / "magma" / "ref_eur" / "g1000_eur.bim"
MAGMA_OUT = INTERIM / "magma"
HECA_GS = PROC / "genesets" / "heca_v014"
GS_P = PROC / "genesets" / "heca_koller_v031" / "P"
TS = dt.datetime.now(dt.timezone.utc).strftime("%Y%m%dT%H%M%SZ")
OUT = REPO / "results" / "locus_atlas" / ("p9_v040_" + TS)
WORK = INTERIM / "magma_v040"
LOG = REPO / "logs" / ("p9_v040_locus_atlas_" + TS + ".log")
NICE = ["nice", "-n", "10"]
ENV1 = dict(os.environ, OPENBLAS_NUM_THREADS="1", OMP_NUM_THREADS="1", VECLIB_MAXIMUM_THREADS="1")

# Fixed (CHANGELOG v0.2.28)
GWS = 5e-8
CLUMP_BP = 500_000
GENE_WIN_BP = 250_000
DROP_WIN_BP = 500_000
PCT_ASSIGN = 0.90   # a gene is assigned to the compartment where its specificity share ranks highest across genes, if >= 90th percentile
SHARED_P = 1e-5
PRIMARY = "KOLLER_EUR"
TRAITS = ["KOLLER_EUR", "GCST90205183", "LEIOMYOMA", "HYPERTENSION", "T2D"]
SHARE_TRAITS = ["LEIOMYOMA", "T2D", "HYPERTENSION"]
COMPARTMENTS = [("stroma", r"Stromal|Fibroblast"),
                ("epithelium", r"SOX9|Lumin|Gland|MUC5B|KRT5|iliated|HOXA13"),
                ("endothelium", r"^(Arterial|Venous|Lymphatic)"),
                ("perivascular/SM", r"^(ePV|mPV|uSMC)"),
                ("immune", r"^(uM|uNK|NK|T_|T$|B_|B$|Mast|DC|cDC|pDC|Macro|Mono|Lymphoid|Myeloid|ILC|Plasma|Neutro|Immune|Treg)")]

for d in (OUT, WORK, LOG.parent):
    d.mkdir(parents=True, exist_ok=True)
_fh = open(LOG, "w", encoding="utf-8")
SUM = {"task": "PAPER9_V040_LOCUS_ATLAS", "timestamp_utc": TS, "results": {}}


def say(msg=""):
    print(msg, flush=True)
    _fh.write(msg + "\n")
    _fh.flush()


def sh(cmd, timeout=None):
    try:
        p = subprocess.run([str(c) for c in cmd], capture_output=True, text=True, timeout=timeout, env=ENV1)
        return p.returncode, p.stdout, p.stderr
    except subprocess.TimeoutExpired:
        return 124, "", "timeout"


def gene_loc():
    ent2sym, sym2ent, pos = {}, {}, {}
    dup = set()
    for line in open(GENE_LOC_B37):
        t = line.split()
        if len(t) >= 6 and t[1] in [str(c) for c in range(1, 23)]:
            ent2sym[t[0]] = t[5]
            pos[t[0]] = (int(t[1]), int(t[2]), int(t[3]))
            if t[5] in sym2ent:
                dup.add(t[5])
            sym2ent[t[5]] = t[0]
    for d in dup:
        sym2ent.pop(d, None)
    return ent2sym, sym2ent, pos


# ----------------------------------------------------------------------------
# L1 loci and compartments
# ----------------------------------------------------------------------------
def read_sig(trait, thr):
    f = MAGMA_OUT / (trait + ".pval.txt")
    if not f.exists():
        return None
    out = {}
    with open(f) as fh:
        hdr = fh.readline().split()
        ip = hdr.index("P") if "P" in hdr else 1
        for line in fh:
            t = line.split()
            try:
                p = float(t[ip])
            except (ValueError, IndexError):
                continue
            if p < thr:
                out[t[0]] = p
    return out


def bim_positions(wanted):
    pos = {}
    with open(G1000_BIM) as fh:
        for line in fh:
            t = line.split()
            if t[1] in wanted:
                pos[t[1]] = (int(t[0]), int(t[3]))
    return pos


def clump(sig, pos):
    rows = sorted([(p, s) for s, p in sig.items() if s in pos and 1 <= pos[s][0] <= 22])
    leads, taken = [], {}
    for p, s in rows:
        c, b = pos[s]
        if any(abs(b - b2) <= CLUMP_BP for b2 in taken.get(c, [])):
            continue
        taken.setdefault(c, []).append(b)
        leads.append({"lead_snp": s, "chr": c, "bp": b, "p": p})
    return pd.DataFrame(leads)


def compartment_table(S):
    comp = {}
    for c in S.columns:
        g = next((name for name, rx in COMPARTMENTS if re.search(rx, c)), "other")
        comp[c] = g
    names = [n for n, _ in COMPARTMENTS] + ["other"]
    share = pd.DataFrame({n: S[[c for c in S.columns if comp[c] == n]].sum(axis=1) if any(comp[c] == n for c in S.columns) else 0.0
                          for n in names}, index=S.index)
    base = share.median(axis=0)
    ratio = share.rank(pct=True)
    for n in names:
        if not any(comp[c] == n for c in S.columns):
            ratio[n] = np.nan
    return comp, share, ratio, base


def assign(ratio_row):
    r = ratio_row.drop(labels=["other"], errors="ignore").dropna()
    if not len(r):
        return "no expression", np.nan
    best = r.idxmax()
    return (best if r[best] >= PCT_ASSIGN else "broad"), float(r[best])


def loci_for(trait, sig, pos, genes_out, ent2sym, ratio, S):
    L = clump(sig, pos)
    if not len(L):
        return L
    g = genes_out
    rows = []
    for _, r in L.iterrows():
        m = g[(g["CHR"] == r["chr"]) & (g["STOP"] >= r["bp"] - GENE_WIN_BP) & (g["START"] <= r["bp"] + GENE_WIN_BP)].sort_values("P")
        syms = [ent2sym.get(str(e), str(e)) for e in m["GENE"]]
        prio = syms[0] if syms else ""
        expr = [s for s in syms if s in ratio.index]
        comp, best_ratio = assign(ratio.loc[expr[0]]) if expr else ("no expression", np.nan)
        top_type = S.loc[expr[0]].idxmax() if expr else ""
        # sensitivity: top-3 expressed candidate genes, mean ratio
        if expr:
            rr = ratio.loc[expr[:3]].mean(axis=0)
            comp3, _ = assign(rr)
        else:
            comp3 = "no expression"
        rows.append({**r.to_dict(), "n_genes": len(syms), "prioritized_gene": prio, "gene_min_p": float(m["P"].iloc[0]) if len(m) else np.nan,
                     "top3_genes": ",".join(syms[:3]), "expressed_gene_used": expr[0] if expr else "", "compartment": comp,
                     "compartment_pct": best_ratio, "top_heca_type": top_type, "compartment_top3": comp3})
    D = pd.DataFrame(rows)
    D.insert(0, "trait", trait)
    return D


def l1(ent2sym, sym2ent):
    say("")
    say("-" * 72)
    say("[SECTION] L1 risk loci and endometrial compartments (HECA heca_v014 specificity)")
    S = pd.read_csv(HECA_GS / "specificity_by_type.csv.gz", index_col=0)
    comp, share, ratio, base = compartment_table(S)
    for n in [n for n, _ in COMPARTMENTS] + ["other"]:
        say("[COMP] %-15s %s" % (n, ", ".join(c for c in S.columns if comp[c] == n) or "-"))
    say("[COMP] median specificity share per compartment: " + "; ".join("%s %.3f" % (k, v) for k, v in base.items() if np.isfinite(v)))
    say("[COMP] assignment: compartment with the highest percentile of its share across genes, if >= %.0f%%; otherwise 'broad'" % (100 * PCT_ASSIGN))
    sigs = {}
    for t in TRAITS:
        s = read_sig(t, GWS)
        if s is None:
            say("[L1] %s: pval file missing; skipped" % t)
            continue
        sigs[t] = s
    wanted = set().union(*[set(s) for s in sigs.values()]) if sigs else set()
    t0 = time.time()
    pos = bim_positions(wanted)
    say("[L1] genome-wide significant SNPs: %s; positions found %d (%.1f min)" % (
        ", ".join("%s %d" % (t, len(s)) for t, s in sigs.items()), len(pos), (time.time() - t0) / 60))
    all_loci = []
    say("[L1] loci = distance clumping of SNPs with p < 5e-8 (lead = smallest p, +-500 kb; no LD clumping); positions GRCh37 from the")
    say("[L1]   MAGMA 1000G EUR reference via rsID; autosomes 1-22 only (chrX / non-autosomal SNPs and genes excluded explicitly)")
    for t, s in sigs.items():
        nonauto = sum(1 for x in s if x in pos and not (1 <= pos[x][0] <= 22))
        if nonauto:
            say("[L1_CHECK] %s: %d significant SNPs on non-autosomal chromosomes excluded" % (t, nonauto))
        go = MAGMA_OUT / (t + "_35_10.genes.out")
        if not go.exists():
            say("[L1] %s genes.out missing" % t)
            continue
        g = pd.read_csv(go, sep=r"\s+", dtype={"GENE": str, "CHR": str})
        n0 = len(g)
        nonauto_vals = sorted(set(g.loc[~g["CHR"].str.fullmatch(r"\d+"), "CHR"]))
        for c in ("CHR", "START", "STOP", "P"):
            g[c] = pd.to_numeric(g[c], errors="coerce")
        g = g.dropna(subset=["CHR", "START", "STOP", "P"])
        g["CHR"] = g["CHR"].astype(int)
        g = g[(g["CHR"] >= 1) & (g["CHR"] <= 22)]
        say("[L1_CHECK] %s genes.out: %d genes, autosomal %d, excluded %d (chromosome values %s)" % (
            t, n0, len(g), n0 - len(g), ",".join(nonauto_vals) or "none"))
        D = loci_for(t, s, pos, g, ent2sym, ratio, S)
        if not len(D):
            say("[L1] %s: no loci" % t)
            continue
        all_loci.append(D)
        say("[L1_CHECK] %s: loci %d, with >= 1 candidate gene %d, candidate genes total %d, with an expressed (HECA) gene %d" % (
            t, len(D), int((D["n_genes"] > 0).sum()), int(D["n_genes"].sum()), int((D["compartment"] != "no expression").sum())))
        vc = D["compartment"].value_counts()
        a = D[~D["compartment"].isin(["broad", "no expression"])]
        sh_ = a["compartment"].value_counts(normalize=True)
        say("[L1] %-12s loci %3d | assigned %3d | %s | broad %d, no expr %d" % (
            t[:12], len(D), len(a), ", ".join("%s %d (%.0f%%)" % (k, vc[k], 100 * sh_.get(k, 0)) for k in sh_.index),
            int(vc.get("broad", 0)), int(vc.get("no expression", 0))))
    if not all_loci:
        return None, ratio, S
    A = pd.concat(all_loci, ignore_index=True)
    A.to_csv(OUT / "l1_loci_compartments.csv", index=False)
    k = A[A["trait"] == PRIMARY]
    if len(k):
        say("[L1] %s loci (lead p, prioritized gene -> compartment, top HECA type):" % PRIMARY)
        for _, r in k.sort_values("p").iterrows():
            say("    chr%-2d %11d %-12s p=%.1e  %-12s -> %-15s %-22s (top3: %s)" % (
                r["chr"], r["bp"], r["lead_snp"], r["p"], str(r["prioritized_gene"])[:12], r["compartment"], str(r["top_heca_type"])[:22],
                str(r["top3_genes"])[:40]))
        a = k[~k["compartment"].isin(["broad", "no expression"])]
        sh_ = a["compartment"].value_counts(normalize=True)
        # background: the same assignment applied to every expressed gene
        from scipy.stats import binomtest
        bg = pd.Series([assign(ratio.loc[g_])[0] for g_ in ratio.index])
        bgs = bg.value_counts(normalize=True)
        n_expr = int((k["compartment"] != "no expression").sum())
        parts = []
        for cn in [n for n, _ in COMPARTMENTS] + ["broad"]:
            obs = int((k["compartment"] == cn).sum())
            exp_ = float(bgs.get(cn, 0.0))
            pv = binomtest(obs, n_expr, exp_, alternative="greater").pvalue if (n_expr and exp_ > 0) else np.nan
            parts.append("%s %d/%d (genome %.0f%%, p %.3g)" % (cn, obs, n_expr, 100 * exp_, pv))
            SUM["results"].setdefault("l1_enrichment", {})[cn] = {"obs": obs, "n": n_expr, "genome_share": exp_, "p_greater": pv}
        say("[L1_ENRICH] %s loci vs all expressed genes: %s" % (PRIMARY, "; ".join(parts)))
        n_ge10 = int((sh_ >= 0.10).sum())
        top_share = float(sh_.max()) if len(sh_) else np.nan
        multi = (n_ge10 >= 3) and (top_share <= 0.5)
        lei = A[(A["trait"] == "LEIOMYOMA") & ~A["compartment"].isin(["broad", "no expression"])]
        lei_top = float(lei["compartment"].value_counts(normalize=True).max()) if len(lei) else np.nan
        say("[H_MULTI_VERDICT] %s assigned loci %d: compartments with >= 10%% share %d, top share %.2f -> %s | leiomyoma top share %s (more concentrated: %s)" % (
            PRIMARY, len(a), n_ge10, top_share, "SUPPORTED" if multi else "NOT SUPPORTED",
            "%.2f" % lei_top if np.isfinite(lei_top) else "NA", "NA" if not np.isfinite(lei_top) else ("YES" if lei_top > top_share else "NO")))
        SUM["results"]["h_multi"] = {"assigned": len(a), "n_ge10": n_ge10, "top_share": top_share, "supported": multi, "leiomyoma_top_share": lei_top}
    return A, ratio, S


# ----------------------------------------------------------------------------
# L2 leave-one-locus-out influence on MAGMA gene-set rankings
# ----------------------------------------------------------------------------
def magma_sets_run(raw, sf, tag):
    outp = WORK / tag
    gsa = Path(str(outp) + ".gsa.out")
    for model in (["--model", "condition-hide=ALLGENES"], []):
        if gsa.exists():
            gsa.unlink()
        rc, o, e = sh(NICE + [MAGMA, "--gene-results", raw, "--set-annot", sf] + model + ["--out", outp], timeout=3600)
        if gsa.exists():
            break
    if not gsa.exists():
        say("    [MAGMA_FAIL] %s %s" % (tag, (o + e).strip()[-200:]))
        return None
    rows = [l for l in open(gsa) if not l.startswith("#") and l.strip()]
    hdr = rows[0].split()
    res = {}
    for l in rows[1:]:
        d = dict(zip(hdr, l.split()))
        try:
            res[d.get("FULL_NAME", d.get("VARIABLE"))] = float(d["P"])
        except (KeyError, ValueError):
            continue
    return res


def l2(A, sym2ent, pos_gene):
    say("")
    say("-" * 72)
    say("[SECTION] L2 leave-one-locus-out: which %s loci drive the gene-set rankings (v031 marker sets)" % PRIMARY)
    mf = GS_P / "manifest.csv"
    raw = MAGMA_OUT / (PRIMARY + "_35_10.genes.raw")
    if not mf.exists() or not raw.exists() or A is None:
        say("[L2] inputs missing; skipped")
        return
    man = pd.read_csv(mf)
    lab = dict(zip(man["set_key"], man["label"] + "/" + man["status"]))
    mode = dict(zip(man["set_key"], man["mode"]))
    sets = {}
    for k in man["set_key"]:
        sets[k] = [sym2ent[s] for s in open(GS_P / (k + ".txt")).read().split() if s in sym2ent]

    def write_sets(drop, path):
        with open(path, "w") as o:
            for k, g in sets.items():
                keep = g if k == "ALLGENES" else [x for x in g if x not in drop]
                o.write(k + " " + " ".join(keep) + "\n")

    sf = WORK / "sets_base.txt"
    write_sets(set(), sf)
    base = magma_sets_run(raw, sf, "base")
    if not base:
        return
    tracked = []
    for m in ("ABS", "UP", "DOWN"):
        ks = sorted([k for k in base if mode.get(k) == m], key=lambda k: base[k])[:3]
        tracked += ks
        say("[L2] baseline %-4s top: %s" % (m, "; ".join("%s p=%.1e" % (lab[k], base[k]) for k in ks)))
    K = A[A["trait"] == PRIMARY].reset_index(drop=True)
    rows = []
    t0 = time.time()
    sfl = WORK / "sets_drop.txt"
    for i, r in K.iterrows():
        drop = {e for e, (c, s, en) in pos_gene.items() if c == r["chr"] and en >= r["bp"] - DROP_WIN_BP and s <= r["bp"] + DROP_WIN_BP}
        write_sets(drop, sfl)
        res = magma_sets_run(raw, sfl, "drop")
        if not res:
            continue
        for k in tracked:
            rows.append({"locus": r["lead_snp"], "chr": r["chr"], "bp": r["bp"], "gene": r["prioritized_gene"], "compartment": r["compartment"],
                         "set": lab[k], "mode": mode[k], "p_base": base[k], "p_drop": res.get(k, np.nan),
                         "delta_log10": -math.log10(base[k]) + math.log10(max(res.get(k, np.nan), 1e-300)) if np.isfinite(res.get(k, np.nan)) else np.nan,
                         "n_dropped_genes": len(drop)})
    say("[L2] %d loci x %d tracked sets (%.0f min)" % (len(K), len(tracked), (time.time() - t0) / 60))
    R = pd.DataFrame(rows)
    if not len(R):
        return
    R.to_csv(OUT / "l2_leave_one_locus_out.csv", index=False)
    drivers = {}
    for s_, g in R.groupby("set", sort=False):
        d = g[g["delta_log10"] >= 1.0].sort_values("delta_log10", ascending=False)
        drivers[s_] = d
        say("    [DRIVERS] %-24s %-4s p=%.1e | %d loci raise p >= 10x: %s" % (
            s_[:24], g["mode"].iloc[0], g["p_base"].iloc[0], len(d),
            "; ".join("%s (%s, %s) %.1e" % (r["gene"], r["compartment"], r["locus"], r["p_drop"]) for _, r in d.head(5).iterrows()) or "-"))
    # all drivers of a set removed together
    for s_, d in drivers.items():
        if not len(d):
            continue
        loci = K[K["lead_snp"].isin(d["locus"])]
        drop = set()
        for _, r in loci.iterrows():
            drop |= {e for e, (c, s, en) in pos_gene.items() if c == r["chr"] and en >= r["bp"] - DROP_WIN_BP and s <= r["bp"] + DROP_WIN_BP}
        write_sets(drop, sfl)
        res = magma_sets_run(raw, sfl, "drop_all")
        k = next(k for k in tracked if lab[k] == s_)
        if res:
            say("    [DRIVERS_ALL] %-24s without its %d driver loci: p=%.1e (base %.1e)" % (s_[:24], len(d), res.get(k, np.nan), base[k]))
    SUM["results"]["l2_drivers"] = {s_: list(d["gene"]) for s_, d in drivers.items()}
    # L2b: every genome-wide significant locus removed at once
    drop = set()
    for _, r in K.iterrows():
        drop |= {e for e, (c, s, en) in pos_gene.items() if c == r["chr"] and en >= r["bp"] - DROP_WIN_BP and s <= r["bp"] + DROP_WIN_BP}
    write_sets(drop, sfl)
    res = magma_sets_run(raw, sfl, "drop_all_gws")
    if res:
        keep = [k for k in tracked if np.isfinite(res.get(k, np.nan))]
        say("[L2_ALL_GWS] all %d loci removed (%d genes out of the sets): %s" % (
            len(K), len(drop), "; ".join("%s %s p=%.1e (base %.1e)" % (mode[k], lab[k], res[k], base[k]) for k in keep)))
        for m in ("ABS", "UP", "DOWN"):
            ks = sorted([k for k in res if mode.get(k) == m], key=lambda k: res[k])[:3]
            say("    [L2_ALL_GWS] %-4s new top: %s" % (m, "; ".join("%s p=%.1e" % (lab[k], res[k]) for k in ks)))
        surv = [lab[k] for k in keep if res[k] < 0.05]
        say("[L2_ALL_GWS_VERDICT] tracked sets still p < 0.05 without any genome-wide locus: %d/%d -> %s" % (
            len(surv), len(keep), "signal persists without the genome-wide loci (distributed over sub-threshold regions)" if len(surv) >= len(keep) / 2 else "signal depends on the genome-wide loci jointly"))
        SUM["results"]["l2_all_gws"] = {lab[k]: {"base": base[k], "without_gws": res[k]} for k in keep}


# ----------------------------------------------------------------------------
# L3 loci shared with other traits (descriptive)
# ----------------------------------------------------------------------------
CHR_LEN_B37 = [249250621, 243199373, 198022430, 191154276, 180915260, 171115067, 159138663, 146364022, 141213431, 135534747, 135006516,
               133851895, 115169878, 107349540, 102531392, 90354753, 81195210, 78077248, 59128983, 63025520, 48129895, 51304566]
N_POOL = 800
K_MATCH = 7
RAND_SEED = 20261108


def l3(A, pos_gene):
    from scipy.stats import fisher_exact
    say("")
    say("-" * 72)
    say("[SECTION] L3 %s loci shared with leiomyoma / T2D / hypertension (min p in lead +-%d kb < %.0e) vs random windows matched on genes and SNPs" % (
        PRIMARY, GENE_WIN_BP // 1000, SHARED_P))
    if A is None:
        return
    K = A[A["trait"] == PRIMARY].copy()
    if not len(K):
        return
    rng = np.random.default_rng(RAND_SEED)
    lens = np.array(CHR_LEN_B37, dtype=float)
    taken = {c: [int(b) for b in K.loc[K["chr"] == c, "bp"]] for c in range(1, 23)}
    pool, tries = [], 0
    while len(pool) < N_POOL and tries < 200000:
        tries += 1
        c = int(rng.choice(22, p=lens / lens.sum())) + 1
        b = int(rng.integers(1_000_000, CHR_LEN_B37[c - 1] - 1_000_000))
        lead_d = min([abs(b - x) for x in K.loc[K["chr"] == c, "bp"]] or [10 ** 9])
        if lead_d < 1_000_000 or any(abs(b - x) < 2 * GENE_WIN_BP for x in taken[c]):
            continue
        taken[c].append(b)
        pool.append((c, b, "R%03d" % len(pool)))
    wins = [(int(r["chr"]), int(r["bp"]), r["lead_snp"]) for _, r in K.iterrows()] + pool
    bych = {}
    for c, b, name in wins:
        bych.setdefault(c, []).append((b - GENE_WIN_BP, b + GENE_WIN_BP, name))
    for c in bych:
        bych[c].sort()
    snp_win, nsnp = {}, {}
    t0 = time.time()
    for ch in pd.read_csv(G1000_BIM, sep=r"\s+", header=None, usecols=[0, 1, 3], names=["c", "snp", "bp"], chunksize=2_000_000,
                          dtype={"c": str, "snp": str, "bp": np.int64}):
        ch = ch[ch["c"].str.fullmatch(r"\d+")]
        ch["c"] = ch["c"].astype(int)
        for c, g in ch.groupby("c"):
            if c not in bych:
                continue
            st = np.array([w[0] for w in bych[c]])
            en = np.array([w[1] for w in bych[c]])
            nm = [w[2] for w in bych[c]]
            bp = g["bp"].to_numpy()
            ix = np.searchsorted(st, bp, side="right") - 1
            ok = (ix >= 0) & (bp <= en[np.clip(ix, 0, None)])
            for snp, i in zip(g["snp"].to_numpy()[ok], ix[ok]):
                snp_win[snp] = nm[i]
                nsnp[nm[i]] = nsnp.get(nm[i], 0) + 1
    ngene = {}
    for c, b, name in wins:
        ngene[name] = sum(1 for e, (cc, s_, en_) in pos_gene.items() if cc == c and en_ >= b - GENE_WIN_BP and s_ <= b + GENE_WIN_BP)
    feat = lambda nm: np.array([np.log1p(ngene.get(nm, 0)), np.log1p(nsnp.get(nm, 0))])
    P = np.array([feat(w[2]) for w in pool])
    sd = P.std(axis=0)
    sd[sd == 0] = 1
    used, matched = set(), []
    for _, r in K.sort_values("p").iterrows():
        f0 = feat(r["lead_snp"])
        d = np.sqrt((((P - f0) / sd) ** 2).sum(axis=1))
        order = [i for i in np.argsort(d) if i not in used and nsnp.get(pool[i][2], 0) >= 50][:K_MATCH]
        used |= set(order)
        matched += [pool[i][2] for i in order]
    pool_ok = [w[2] for w in pool if nsnp.get(w[2], 0) >= 50]
    med = lambda names, dct: float(np.median([dct.get(x, 0) for x in names])) if names else float("nan")
    say("[L3] reference SNPs in windows %d (%.1f min); pool %d windows (%d with >= 50 SNPs); matched controls %d" % (
        len(snp_win), (time.time() - t0) / 60, len(pool), len(pool_ok), len(matched)))
    say("[L3_BALANCE] median genes / SNPs per window: endometriosis loci %.0f / %.0f; matched %.0f / %.0f; all pool %.0f / %.0f" % (
        med(list(K["lead_snp"]), ngene), med(list(K["lead_snp"]), nsnp), med(matched, ngene), med(matched, nsnp), med(pool_ok, ngene), med(pool_ok, nsnp)))
    rows = []
    for tr in SHARE_TRAITS:
        f = MAGMA_OUT / (tr + ".pval.txt")
        if not f.exists():
            say("[L3] %s pval file missing" % tr)
            continue
        b_ = {}
        with open(f) as fh:
            hdr = fh.readline().split()
            ip = hdr.index("P") if "P" in hdr else 1
            for line in fh:
                t = line.split()
                w = snp_win.get(t[0])
                if w is None:
                    continue
                try:
                    p = float(t[ip])
                except (ValueError, IndexError):
                    continue
                if p < b_.get(w, 1.0):
                    b_[w] = p
        k_sh = int(sum(b_.get(ls, 1.0) < SHARED_P for ls in K["lead_snp"]))
        m_sh = int(sum(b_.get(w, 1.0) < SHARED_P for w in matched))
        a_sh = int(sum(b_.get(w, 1.0) < SHARED_P for w in pool_ok))
        orm, pm = fisher_exact([[k_sh, len(K) - k_sh], [m_sh, len(matched) - m_sh]], alternative="greater")
        ora, pa = fisher_exact([[k_sh, len(K) - k_sh], [a_sh, len(pool_ok) - a_sh]], alternative="greater")
        K["minp_" + tr] = K["lead_snp"].map(b_)
        K["shared_" + tr] = K["minp_" + tr] < SHARED_P
        rows.append({"trait": tr, "loci_shared": k_sh, "loci": len(K), "matched_shared": m_sh, "matched": len(matched), "or_matched": orm,
                     "p_matched": pm, "pool_shared": a_sh, "pool": len(pool_ok), "or_pool": ora, "p_pool": pa})
        say("[L3] %-12s shared %2d/%d loci (%.0f%%) | matched windows %d/%d (%.0f%%): OR %.2f, p %.2g | all pool %d/%d (%.0f%%): OR %.2f, p %.2g" % (
            tr, k_sh, len(K), 100 * k_sh / len(K), m_sh, len(matched), 100 * m_sh / max(1, len(matched)), orm, pm,
            a_sh, len(pool_ok), 100 * a_sh / max(1, len(pool_ok)), ora, pa))
        g = K[K["shared_" + tr]]
        say("       %s" % ", ".join("%s(%s)" % (r["prioritized_gene"] or r["lead_snp"], str(r["compartment"])[:5]) for _, r in g.iterrows())[:400])
    pd.DataFrame(rows).to_csv(OUT / "l3_sharing_vs_matched.csv", index=False)
    cols = [c for c in K.columns if c.startswith("shared_")]
    if cols:
        K["shared_any"] = K[cols].any(axis=1)
        for flag, g in K.groupby("shared_any"):
            a = g[~g["compartment"].isin(["broad", "no expression"])]
            say("[L3] %-9s loci %2d | assigned compartments: %s" % ("shared" if flag else "specific", len(g),
                                                                   ", ".join("%s %d" % (k, v) for k, v in a["compartment"].value_counts().items()) or "-"))
    K.to_csv(OUT / "l3_shared_loci.csv", index=False)
    SUM["results"]["l3"] = rows


# ----------------------------------------------------------------------------
# K1b Koller cohort audit against the E-MTAB-14039 sample table (descriptive)
# ----------------------------------------------------------------------------
HECA_FILE = REPO / "data" / "raw" / "heca" / "endometriumAtlasV2_cells_with_counts.h5ad"
SDRF = REPO / "data" / "raw" / "arrayexpress" / "E-MTAB-14039.sdrf.txt"
SDRF_URLS = ["https://www.ebi.ac.uk/biostudies/files/E-MTAB-14039/E-MTAB-14039.sdrf.txt",
             "https://ftp.ebi.ac.uk/biostudies/fire/E-MTAB-/039/E-MTAB-14039/Files/E-MTAB-14039.sdrf.txt"]


def obs_cat(f, name):
    import h5py
    g = f["obs"][name]
    dec = lambda x: x.decode() if isinstance(x, bytes) else str(x)
    if isinstance(g, h5py.Group) and "categories" in g:
        cats = np.array([dec(c) for c in g["categories"][:]], dtype=object)
        codes = g["codes"][:]
        out = np.empty(len(codes), dtype=object)
        out[codes >= 0] = cats[codes[codes >= 0]]
        return out
    return np.array([dec(x) for x in g[:]], dtype=object)


def k1b():
    import h5py
    say("")
    say("-" * 72)
    say("[SECTION] K1b Koller cohort audit: E-MTAB-14039 sample table vs HECA libraries (descriptive)")
    SDRF.parent.mkdir(parents=True, exist_ok=True)
    if not SDRF.exists():
        for u in SDRF_URLS:
            rc, o, e = sh(["curl", "-sSL", "--fail", "--max-time", "300", "-A", "paper9", "-o", SDRF, u], timeout=400)
            if rc == 0 and SDRF.exists() and SDRF.stat().st_size > 1000:
                say("[K1b] downloaded %s" % u)
                break
            if SDRF.exists():
                SDRF.unlink()
    if not SDRF.exists():
        say("[K1b] sample table not available (download failed)")
        return
    T = pd.read_csv(SDRF, sep="\t", dtype=str).fillna("")
    say("[K1b] rows %d, columns %d" % (len(T), T.shape[1]))
    keys = re.compile(r"individual|disease|endometriosis|treat|hormon|stage|phase|library|single|nucle|assay name|source name|organism part|sampling", re.I)
    for c in T.columns:
        if keys.search(c):
            vc = T[c].value_counts()
            say("    [SDRF] %-45s n=%-4d %s" % (c[:45], len(vc), " | ".join("%s=%d" % (k[:30], v) for k, v in vc.head(6).items())))
    with h5py.File(HECA_FILE, "r") as f:
        cols = list(f["obs"].keys())
        ds = obs_cat(f, "dataset") if "dataset" in cols else None
        lib = obs_cat(f, "library") if "library" in cols else None
        path = obs_cat(f, "Endometrial_pathology")
        stage = obs_cat(f, "Binary Stage")
        don = obs_cat(f, "genotype")
    if ds is None or lib is None:
        say("[K1b] HECA dataset / library columns missing")
        return
    m = ds == "Mareckova"
    H = pd.DataFrame({"library": lib[m], "pathology": path[m], "stage": stage[m], "donor": don[m]}).drop_duplicates("library")
    text = "\n".join("\t".join(r) for r in T.values.tolist())
    H["in_sdrf"] = H["library"].map(lambda x: bool(x) and x in text)
    say("[K1b] HECA Mareckova libraries %d; found in the sample table %d" % (len(H), int(H["in_sdrf"].sum())))
    for (pa, st), g in H.groupby([H["pathology"].fillna("NA"), H["stage"].fillna("NA")]):
        say("    [HECA_LIB] pathology %-10s stage %-14s libraries %3d donors %3d (in table %d)" % (pa[:10], st[:14], len(g), g["donor"].nunique(), int(g["in_sdrf"].sum())))
    H.to_csv(OUT / "k1b_heca_mareckova_libraries.csv", index=False)
    T.to_csv(OUT / "k1b_sdrf_copy.tsv", sep="\t", index=False)


def main():
    say("=" * 72)
    say("PAPER 9 | v0.0.40 | locus atlas (corrected): compartments of risk loci, drivers, sharing | " + TS)
    say("=" * 72)
    t0 = time.time()
    ent2sym, sym2ent, pos_gene = gene_loc()
    A = None
    try:
        k1b()
    except Exception as e:
        say("[STEP_ERROR] K1b %s: %s" % (type(e).__name__, str(e)[:300]))
    for name, fn in (("L1", lambda: l1(ent2sym, sym2ent)), ("L2", None), ("L3", None)):
        try:
            if name == "L1":
                A = fn()[0]
            elif name == "L2":
                l2(A, sym2ent, pos_gene)
            else:
                l3(A, pos_gene)
        except Exception as e:
            import traceback
            say("[STEP_ERROR] %s %s: %s" % (name, type(e).__name__, str(e)[:300]))
            say(traceback.format_exc()[-1500:])
    with open(OUT / "p9_v040_summary.json", "w") as f:
        json.dump(SUM, f, indent=2, default=str)
    say("")
    say("[TIME] %.0f min" % ((time.time() - t0) / 60))
    say("[OUTPUT] " + str(OUT))
    say("[LOG] " + str(LOG))
    say("[POLICY] rules fixed in CHANGELOG v0.2.28 / v0.2.29 before this run")
    say("[DONE] PAPER9_V040_COMPLETE")
    _fh.close()


if __name__ == "__main__":
    main()
