def main():
    if not REPO.exists():
        print("[FATAL] " + str(REPO) + " not found (clone the repository first)")
        sys.exit(2)
    written = 0
    for rel, content in FILES.items():
        dst = REPO / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        if dst.exists() and dst.read_text() == content:
            continue
        dst.write_text(content)
        written += 1
        print("[WRITE] " + rel)
    (REPO / SCRIPT).chmod(0o755)
    print("[FILES] written=%d of %d" % (written, len(FILES)))
    print("[RUN] .venv/bin/python " + str(REPO / SCRIPT))
    print("")
    rc = subprocess.run([str(REPO / ".venv" / "bin" / "python"), str(REPO / SCRIPT)], cwd=str(REPO)).returncode
    print("")
    print("[EXIT] " + str(rc))
    print("[NEXT] send the log from ~/Desktop/paper9/logs/ (newest file) to continue")


if __name__ == "__main__":
    main()
